        }

        .portal-modal h2 {
            font-size: 28px;
            font-weight: 700;
            color: var(--up-text);
            text-align: center;
            margin-bottom: 8px;
        }

        .portal-modal p {
            font-size: 15px;
            color: var(--up-text-secondary);
            text-align: center;
            margin-bottom: 32px;
