            align-items: center;
            justify-content: center;
            margin: 0 auto 16px;
            font-size: 28px;
            color: var(--up-gold);
        }

        .portal-option h3 {
            font-size: 18px;
            font-weight: 600;
            color: var(--up-text);
            margin-bottom: 8px;
        }

        .portal-option p {
            font-size: 13px;
            color: var(--up-text-muted);
            margin-bottom: 0;
        }

        /* ===== AUTH MODALS ===== */
        .auth-modal-overlay {
            position: fixed;
            inset: 0;
            background: rgba(0, 0, 0, 0.7);
            backdrop-filter: blur(8px);
            display: none;
            align-items: center;
            justify-content: center;
            z-index: 99999;
            padding: 20px;
        }

        .auth-modal-overlay.active {
            display: flex !important;
        }

        .auth-modal {
            background: var(--up-bg);
            border-radius: var(--up-radius-lg);
            padding: 40px;
            max-width: 440px;
            width: 100%;
            box-shadow: var(--up-shadow-xl);
            animation: modal-in 0.3s ease;
            position: relative;
            max-height: 90vh;
            overflow-y: auto;
            -webkit-overflow-scrolling: touch;
        }

        .auth-modal-close {
            position: absolute;
            top: 16px;
            right: 16px;
            width: 36px;
            height: 36px;
            border-radius: 50%;
            border: none;
            background: var(--up-bg-subtle);
            color: var(--up-text-muted);
            cursor: pointer;
            font-size: 16px;
            transition: all 0.2s;
        }

        .auth-modal-close:hover {
            background: var(--up-bg-muted);
            color: var(--up-text);
        }

        .auth-modal h2 {
            font-size: 24px;
            font-weight: 700;
            color: var(--up-text);
            text-align: center;
            margin-bottom: 8px;
        }

        .auth-modal > p {
            font-size: 14px;
            color: var(--up-text-secondary);
            text-align: center;
            margin-bottom: 32px;
        }

        .auth-form-group {
            margin-bottom: 20px;
        }

        .auth-form-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 16px;
        }

        .auth-form-label {
            display: block;
            font-size: 13px;
            font-weight: 500;
            color: var(--up-text-secondary);
            margin-bottom: 8px;
        }

        .auth-form-input {
            width: 100%;
            padding: 10px 14px;
            background: var(--up-bg);
            border: 1px solid var(--up-border);
            border-radius: 8px;
            color: var(--up-text);
            font-size: 14px;
            font-family: inherit;
            transition: all 0.2s;
            position: relative;
            z-index: 1;
            -webkit-appearance: none;
        }

        .auth-form-input:focus {
            outline: none;
            border-color: var(--up-gold);
            box-shadow: 0 0 0 3px rgba(201, 169, 98, 0.1);
        }

        .auth-form-input::placeholder {
            color: var(--up-text-muted);
        }

        .auth-form-select {
            width: 100%;
            padding: 10px 14px;
            background: var(--up-bg);
            border: 1px solid var(--up-border);
            border-radius: 8px;
            color: var(--up-text);
            font-size: 14px;
            font-family: inherit;
            cursor: pointer;
        }

        .auth-btn {
            width: 100%;
            padding: 14px;
            background: var(--up-gold);
            color: var(--up-navy);
            border: none;
            border-radius: var(--up-radius-sm);
            font-size: 15px;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s;
            font-family: inherit;
            margin-top: 8px;
        }

        .auth-btn:hover {
            background: var(--up-gold-dark);
            transform: translateY(-1px);
        }

        .auth-btn:active {
            transform: translateY(0) scale(0.98);
            box-shadow: none;
        }

        .auth-btn:disabled {
            opacity: 0.6;
            cursor: not-allowed;
        }

        .auth-divider {
            display: flex;
            align-items: center;
            gap: 16px;
            margin: 24px 0;
        }

        .auth-divider::before,
        .auth-divider::after {
            content: '';
            flex: 1;
            height: 1px;
            background: var(--up-border);
        }

        .auth-divider span {
            font-size: 13px;
            color: var(--up-text-muted);
        }

        .auth-link {
            font-size: 14px;
            color: var(--up-text-secondary);
            text-align: center;
            display: block;
        }

        .auth-link a {
            color: var(--up-gold);
            text-decoration: none;
            font-weight: 500;
        }

        .auth-link a:hover {
            text-decoration: underline;
        }

        .auth-error {
            background: rgba(239, 68, 68, 0.1);
            border: 1px solid var(--up-danger);
            color: var(--up-danger);
            padding: 12px 16px;
            border-radius: var(--up-radius-sm);
            font-size: 13px;
            margin-bottom: 20px;
            display: none;
        }

        .auth-error.show {
            display: block;
        }

        /* ===== WELCOME ANIMATION ===== */
        .welcome-overlay {
            position: fixed;
            inset: 0;
            background: linear-gradient(135deg, var(--emph-bg) 0%, #1e2d4a 50%, var(--emph-bg) 100%);
            z-index: 9999;
            display: none;
            align-items: center;
            justify-content: center;
            flex-direction: column;
            opacity: 0;
            transition: opacity 0.5s ease;
        }

        .welcome-overlay.active {
            display: flex;
            opacity: 1;
        }

        .welcome-overlay.fade-out {
            opacity: 0;
        }

        .welcome-content {
            text-align: center;
            transform: scale(0.8);
            opacity: 0;
            animation: welcome-zoom-in 0.8s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
        }

        @keyframes welcome-zoom-in {
            0% {
                transform: scale(0.8);
                opacity: 0;
            }
            100% {
                transform: scale(1);
                opacity: 1;
            }
        }

        .welcome-logo {
            font-size: 64px;
            font-weight: 800;
            color: #fff;
            margin-bottom: 16px;
            text-shadow: 0 4px 30px rgba(201, 169, 98, 0.3);
        }

        .welcome-logo span {
            color: var(--up-gold);
        }

        .welcome-text {
            font-size: 32px;
            font-weight: 600;
            color: #fff;
            margin-bottom: 12px;
            opacity: 0;
            animation: welcome-fade-in 0.6s ease forwards 0.3s;
        }

        .welcome-subtext {
            font-size: 18px;
            color: rgba(255, 255, 255, 0.7);
            opacity: 0;
            animation: welcome-fade-in 0.6s ease forwards 0.5s;
        }

        @keyframes welcome-fade-in {
            0% {
                opacity: 0;
                transform: translateY(10px);
            }
            100% {
                opacity: 1;
                transform: translateY(0);
            }
        }

        /* Floating particles for welcome */
        .welcome-particles {
            position: absolute;
            inset: 0;
            overflow: hidden;
            pointer-events: none;
        }

        .welcome-particle {
            position: absolute;
            width: 6px;
            height: 6px;
            background: var(--up-gold);
            border-radius: 50%;
            opacity: 0.4;
            animation: particle-float 4s ease-in-out infinite;
        }

        @keyframes particle-float {
            0%, 100% {
                transform: translateY(0) scale(1);
                opacity: 0.4;
            }
            50% {
                transform: translateY(-30px) scale(1.2);
                opacity: 0.8;
            }
        }

        /* ===== ONBOARDING TOUR - Premium Spotlight Effect ===== */
        /* Main onboarding overlay styles are defined later in the file (line ~41670) */

        /* Spotlight highlight - glows softly without blocking the view */
        .onboarding-highlight {
            position: fixed;
            border-radius: 16px;
            pointer-events: none;
            z-index: 8001;
            opacity: 0;
            transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .onboarding-highlight.active {
            opacity: 1;
            box-shadow:
                0 0 0 3px var(--up-gold),
                0 0 0 6px rgba(201, 169, 98, 0.3),
                0 0 40px rgba(201, 169, 98, 0.4),
                0 0 80px rgba(201, 169, 98, 0.2);
            animation: spotlight-glow 2s ease-in-out infinite;
        }

        @keyframes spotlight-glow {
            0%, 100% {
                box-shadow:
                    0 0 0 3px var(--up-gold),
                    0 0 0 6px rgba(201, 169, 98, 0.3),
                    0 0 40px rgba(201, 169, 98, 0.4),
                    0 0 80px rgba(201, 169, 98, 0.2);
            }
            50% {
                box-shadow:
                    0 0 0 4px var(--up-gold),
                    0 0 0 8px rgba(201, 169, 98, 0.4),
                    0 0 60px rgba(201, 169, 98, 0.5),
                    0 0 100px rgba(201, 169, 98, 0.3);
            }
        }

        /* Premium floating tooltip */
        .onboarding-tooltip {
            position: fixed;
            background: linear-gradient(145deg, #ffffff 0%, #fafafa 100%);
            border-radius: 16px;
            padding: 32px;
            max-width: 360px;
            width: calc(100vw - 48px);
            box-shadow:
                0 4px 6px rgba(0, 0, 0, 0.05),
                0 10px 20px rgba(0, 0, 0, 0.08),
                0 30px 60px rgba(0, 0, 0, 0.12);
            z-index: 8002;
            transform: translateY(20px);
            opacity: 0;
            /* When idle this fixed, invisible box floated over the top navigation and
               swallowed clicks on the tabs beneath it — keep it fully inert until active. */
            visibility: hidden;
            pointer-events: none;
            transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
            border: 1px solid rgba(201, 169, 98, 0.2);
        }

        .onboarding-tooltip.active {
            transform: translateY(0);
            opacity: 1;
            visibility: visible;
            pointer-events: auto;
        }

        /* Smooth connecting line instead of arrow */
        .onboarding-connector {
            position: fixed;
            pointer-events: none;
            width: 2px;
            background: linear-gradient(to bottom, var(--up-gold), transparent);
            z-index: 8001;
            opacity: 0;
            transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
            transform-origin: top center;
        }

        .onboarding-connector.active {
            opacity: 1;
        }

        .onboarding-tooltip-arrow {
            display: none; /* Hide old arrows */
        }

        /* Progress indicator - horizontal line style */
        .onboarding-step-indicator {
            display: flex;
            gap: 6px;
            margin-bottom: 24px;
            justify-content: center;
        }

        .onboarding-step-dot {
            width: 32px;
            height: 4px;
            border-radius: 2px;
            background: #e5e7eb;
            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .onboarding-step-dot.active {
            background: linear-gradient(90deg, var(--up-gold) 0%, #d4b876 100%);
            width: 48px;
        }

        .onboarding-step-dot.completed {
            background: var(--up-gold);
        }

        /* Icon with subtle animation */
        .onboarding-icon {
            width: 64px;
            height: 64px;
            border-radius: 14px;
            background: linear-gradient(145deg, var(--up-gold) 0%, #d4b876 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--ink);
            font-size: 26px;
            margin: 0 auto 24px;
            box-shadow: 0 8px 24px rgba(201, 169, 98, 0.3);
            animation: icon-float 3s ease-in-out infinite;
        }

        @keyframes icon-float {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-4px); }
        }

        .onboarding-title {
            font-size: 24px;
            font-weight: 700;
            color: var(--ink);
            margin-bottom: 12px;
            text-align: center;
            letter-spacing: -0.3px;
        }

        .onboarding-desc {
            font-size: 15px;
            color: var(--muted);
            line-height: 1.7;
            margin-bottom: 28px;
            text-align: center;
        }

        .onboarding-actions {
            display: flex;
            gap: 16px;
            justify-content: center;
            align-items: center;
            flex-direction: column;
        }

        .onboarding-skip {
            background: none;
            border: none;
            color: var(--muted);
            font-size: 14px;
            cursor: pointer;
            padding: 8px 16px;
            font-family: inherit;
            transition: all 0.3s ease;
            order: 2;
        }

        .onboarding-skip:hover {
            color: var(--muted);
        }

        .onboarding-next {
            background: linear-gradient(145deg, var(--up-gold) 0%, #d4b876 100%);
            color: var(--ink);
            border: none;
            padding: 16px 40px;
            border-radius: 16px;
            font-size: 16px;
            font-weight: 600;
            cursor: pointer;
            font-family: inherit;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            display: flex;
            align-items: center;
            gap: 10px;
            box-shadow: 0 4px 16px rgba(201, 169, 98, 0.3);
            order: 1;
        }

        .onboarding-next:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 24px rgba(201, 169, 98, 0.4);
        }

        .onboarding-next:active {
            transform: translateY(0);
        }

        .onboarding-next i {
            font-size: 14px;
            transition: transform 0.2s;
        }

        .onboarding-next:hover i {
            transform: translateX(4px);
        }

        /* Mobile adjustments for onboarding */
        @media (max-width: 768px) {
            .welcome-logo {
                font-size: 48px;
            }
            .welcome-text {
                font-size: 24px;
            }
            .welcome-subtext {
                font-size: 16px;
                padding: 0 20px;
            }
            .onboarding-tooltip {
                position: fixed !important;
                bottom: 24px !important;
                left: 50% !important;
                top: auto !important;
                right: auto !important;
                transform: translateX(-50%) !important;
                max-width: calc(100vw - 32px);
                width: calc(100vw - 32px);
                padding: 24px;
                border-radius: 14px;
            }
            .onboarding-tooltip.active {
                transform: translateX(-50%) translateY(0) !important;
            }
            .onboarding-icon {
                width: 56px;
                height: 56px;
                font-size: 22px;
                margin-bottom: 16px;
            }
            .onboarding-title {
                font-size: 20px;
            }
            .onboarding-desc {
                font-size: 14px;
                margin-bottom: 20px;
            }
            .onboarding-next {
                padding: 14px 32px;
                font-size: 15px;
                width: 100%;
                justify-content: center;
            }
            .onboarding-step-dot {
                width: 24px;
                height: 3px;
            }
            .onboarding-step-dot.active {
                width: 36px;
            }
        }

        /* ===== USER PORTAL LAYOUT ===== */
        .user-portal {
            min-height: 100vh;
            /* warm laid-paper texture: faint ink grid + soft corner vignette over cream */
            background:
                radial-gradient(1200px 600px at 85% -10%, rgba(155,27,34,.025), transparent 60%),
                repeating-linear-gradient(0deg, rgba(21,17,15,.016) 0 1px, transparent 1px 7px),
                repeating-linear-gradient(90deg, rgba(21,17,15,.012) 0 1px, transparent 1px 7px),
                var(--paper);
            color: var(--up-text);
            display: none;
        }

        .user-portal.active {
            display: block;
        }

        [data-theme="dark"] .user-portal {
            background: var(--paper);
        }

        /* Floating Navigation - Minimal */
        .up-float-nav {
            display: none !important;
            position: fixed;
            top: 20px;
            right: 20px;
            z-index: 100;
            opacity: 0;
            transform: translateY(-20px);
            pointer-events: none;
            transition: all 0.3s ease;
        }

        .up-float-nav.visible {
            opacity: 1;
            transform: translateY(0);
            pointer-events: all;
        }

        .up-float-collapsed {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: rgba(0, 0, 0, 0.08);
            backdrop-filter: blur(10px);
            border: none;
            color: rgba(0, 0, 0, 0.3);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            transition: all 0.3s;
        }

        .up-float-collapsed:hover {
            background: rgba(0, 0, 0, 0.15);
            color: rgba(0, 0, 0, 0.5);
        }

        .up-float-expanded {
            display: flex;
            flex-direction: column;
            gap: 4px;
            padding: 8px;
            background: rgba(255, 255, 255, 0.98);
            backdrop-filter: blur(20px);
            border: 1px solid rgba(0, 0, 0, 0.08);
            border-radius: 16px;
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.15);
            /* Animation states */
            opacity: 0;
            visibility: hidden;
            transform: scale(0.8) translateY(20px);
            transform-origin: bottom right;
            transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .up-float-collapsed {
            transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .up-float-nav.expanded .up-float-collapsed {
            opacity: 0;
            transform: scale(0.8);
            visibility: hidden;
        }

        .up-float-nav.expanded .up-float-expanded {
            opacity: 1;
            visibility: visible;
            transform: scale(1) translateY(0);
        }

        .up-float-expanded .up-float-btn {
            opacity: 0;
            transform: translateX(20px) scale(0.8);
            transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .up-float-nav.expanded .up-float-expanded .up-float-btn {
            opacity: 1;
            transform: translateX(0) scale(1);
        }

        .up-float-nav.expanded .up-float-expanded .up-float-btn:nth-child(1) { transition-delay: 0.03s; }
        .up-float-nav.expanded .up-float-expanded .up-float-btn:nth-child(2) { transition-delay: 0.06s; }
        .up-float-nav.expanded .up-float-expanded .up-float-btn:nth-child(3) { transition-delay: 0.09s; }
        .up-float-nav.expanded .up-float-expanded .up-float-btn:nth-child(4) { transition-delay: 0.12s; }
        .up-float-nav.expanded .up-float-expanded .up-float-btn:nth-child(5) { transition-delay: 0.15s; }
        .up-float-nav.expanded .up-float-expanded .up-float-btn:nth-child(6) { transition-delay: 0.18s; }

        .up-float-close {
            background: rgba(0, 0, 0, 0.05) !important;
            margin-bottom: 4px;
        }

        .up-float-close:hover {
            background: rgba(239, 68, 68, 0.1) !important;
            color: var(--danger) !important;
