        /* Button Styles */
        .floating-btn.notes {
            color: var(--up-gold);
        }
        .floating-btn.notes span {
            color: rgba(201, 169, 98, 0.8);
        }
        .floating-btn.notes:hover {
            border-color: rgba(201, 169, 98, 0.3);
