            border: none;
        }
        .floating-btn.messages i {
            color: var(--up-gold);
        }
        .floating-btn.messages span {
            color: rgba(201, 169, 98, 0.8);
        }
        .floating-btn.messages:hover {
            box-shadow: 0 8px 30px rgba(20,15,12, 0.4);
        }

        .floating-btn.contact {
            color: var(--muted);
        }
        .floating-btn.contact span {
            color: var(--muted);
        }
        .floating-btn.contact:hover {
            color: var(--ink);
        }

        .floating-btn.ai-agent {
