        .alan-typing span:nth-child(2) { animation-delay: 0.2s; }
        .alan-typing span:nth-child(3) { animation-delay: 0.4s; }

        @keyframes typingDot {
            0%, 60%, 100% { transform: translateY(0); }
            30% { transform: translateY(-6px); }
