        .alan-chat-input-area {
            padding: 16px 20px;
            border-top: 1px solid rgba(0, 0, 0, 0.06);
            display: flex;
            gap: 10px;
        }

        [data-theme="dark"] .alan-chat-input-area {
            border-top-color: rgba(255, 255, 255, 0.06);
        }

        .alan-chat-input {
            flex: 1;
            padding: 12px 16px;
            background: rgba(0, 0, 0, 0.04);
            border: 1px solid transparent;
            border-radius: 14px;
            font-size: 14px;
            color: var(--up-text, #1d1d1f);
            font-family: inherit;
            transition: all 0.2s;
        }

        .alan-chat-input:focus {
