        [data-theme="dark"] .alan-chat-input {
            background: rgba(255, 255, 255, 0.08);
            color: var(--up-text);
        }

        .alan-chat-send {
            width: 44px;
            height: 44px;
            border-radius: 14px;
            background: linear-gradient(135deg, var(--crimson-deep) 0%, var(--accent) 100%);
            border: none;
            color: white;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 16px;
            transition: all 0.2s;
        }

        .alan-chat-send:hover {
            transform: scale(1.05);
        }

        .alan-chat-send:disabled {
