            background: rgba(37, 99, 235, 0.15);
            border-color: rgba(37, 99, 235, 0.25);
            color: var(--accent);
        }

        /* ===== Header Menu Expansion ===== */
        .hub-menu-wrapper {
            position: relative;
            overflow: visible;
        }

        .hub-menu-btn {
            position: relative;
            width: 44px;
            height: 44px;
            border-radius: 14px;
            background: linear-gradient(135deg, var(--up-gold) 0%, #d4b876 100%);
            backdrop-filter: blur(12px);
            -webkit-backdrop-filter: blur(12px);
            border: none;
            color: var(--ink);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 16px;
            transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
            overflow: visible;
            margin-top: 6px;
            box-shadow: 0 4px 16px rgba(201, 169, 98, 0.4), 0 0 0 3px rgba(201, 169, 98, 0.15);
            overflow: visible;
        }

        .hub-menu-btn:hover {
            transform: scale(1.1);
            box-shadow: 0 8px 28px rgba(201, 169, 98, 0.55), 0 0 0 5px rgba(201, 169, 98, 0.25);
        }

        .hub-menu-btn:active {
            transform: scale(0.95);
            transition: all 0.1s ease;
        }

        .hub-menu-btn.active {
            box-shadow: 0 4px 16px rgba(201, 169, 98, 0.3);
        }

        [data-theme="dark"] .hub-menu-btn {
            background: linear-gradient(135deg, var(--up-gold) 0%, #d4b876 100%);
            color: var(--ink);
        }

        [data-theme="dark"] .hub-menu-btn:hover {
            box-shadow: 0 6px 24px rgba(201, 169, 98, 0.5), 0 0 0 4px rgba(201, 169, 98, 0.25);
        }

        /* Notification Badge on Menu Button */
        .hub-menu-btn-badge {
            position: absolute;
            top: -5px;
            right: -5px;
            min-width: 18px;
            height: 18px;
            padding: 0 5px;
            background: var(--danger);
            color: white;
            font-size: 10px;
            font-weight: 600;
            border-radius: 9px;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: 0 2px 6px rgba(239, 68, 68, 0.4);
            animation: badgePulse 2s infinite;
            z-index: 1;
        }

        .hub-menu-btn-badge:empty,
        .hub-menu-btn-badge[data-count="0"] {
            display: none;
        }

        @keyframes badgePulse {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.1); }
        }

        /* Notification Badge on Menu Item */
        .hub-menu-item.notifications {
            position: relative;
            color: var(--warning);
        }

        .hub-menu-item.notifications i {
            color: var(--warning);
        }

        .hub-menu-notif-badge {
            position: absolute;
            top: -4px;
            right: -4px;
            min-width: 16px;
            height: 16px;
            padding: 0 4px;
            background: var(--danger);
            color: white;
            font-size: 10px;
            font-weight: 600;
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: 0 2px 4px rgba(239, 68, 68, 0.3);
        }

        .hub-menu-notif-badge:empty,
        .hub-menu-notif-badge[data-count="0"] {
            display: none;
        }

        .hub-menu-expanded {
            position: absolute;
            top: 0;
            right: 0;
            display: flex;
            align-items: center;
            gap: 8px;
            pointer-events: none;
        }

        .hub-menu-expanded.active {
            pointer-events: all;
        }

        .hub-menu-item {
            position: relative;
            width: 44px;
            height: 44px;
            border-radius: 14px;
            background: rgba(255, 255, 255, 0.9);
            backdrop-filter: blur(16px);
            -webkit-backdrop-filter: blur(16px);
            border: 1px solid rgba(255, 255, 255, 0.4);
            box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transform: scale(0) translateX(20px);
            opacity: 0;
            transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .hub-menu-item i {
            font-size: 16px;
            transition: transform 0.2s ease;
        }

        .hub-menu-item:hover i {
            transform: scale(1.15);
        }

        /* Expanded state - items pop out to the left */
        .hub-menu-expanded.active .hub-menu-item:nth-child(1) {
            transform: scale(1) translateX(0);
            opacity: 1;
            transition-delay: 0s;
        }

        .hub-menu-expanded.active .hub-menu-item:nth-child(2) {
            transform: scale(1) translateX(0);
            opacity: 1;
            transition-delay: 0.05s;
        }

        .hub-menu-expanded.active .hub-menu-item:nth-child(3) {
            transform: scale(1) translateX(0);
            opacity: 1;
            transition-delay: 0.1s;
        }

        .hub-menu-expanded.active .hub-menu-item:nth-child(4) {
            transform: scale(1) translateX(0);
            opacity: 1;
            transition-delay: 0.15s;
        }

        .hub-menu-expanded.active .hub-menu-item:nth-child(5) {
            transform: scale(1) translateX(0);
            opacity: 1;
            transition-delay: 0.2s;
        }

        .hub-menu-expanded.active .hub-menu-item:nth-child(6) {
            transform: scale(1) translateX(0);
            opacity: 1;
            transition-delay: 0.25s;
        }

        .hub-menu-expanded.active .hub-menu-item:nth-child(7) {
            transform: scale(1) translateX(0);
            opacity: 1;
            transition-delay: 0.3s;
        }

        /* Closing animation */
        .hub-menu-expanded.closing .hub-menu-item {
            transform: scale(0) translateX(20px) !important;
            opacity: 0 !important;
        }

        .hub-menu-expanded.closing .hub-menu-item:nth-child(7) { transition-delay: 0s !important; }
        .hub-menu-expanded.closing .hub-menu-item:nth-child(6) { transition-delay: 0.03s !important; }
        .hub-menu-expanded.closing .hub-menu-item:nth-child(5) { transition-delay: 0.06s !important; }
        .hub-menu-expanded.closing .hub-menu-item:nth-child(4) { transition-delay: 0.09s !important; }
        .hub-menu-expanded.closing .hub-menu-item:nth-child(3) { transition-delay: 0.12s !important; }
        .hub-menu-expanded.closing .hub-menu-item:nth-child(2) { transition-delay: 0.15s !important; }
        .hub-menu-expanded.closing .hub-menu-item:nth-child(1) { transition-delay: 0.18s !important; }

        /* Menu item colors */
        .hub-menu-item.plexus { color: var(--accent); }
        .hub-menu-item.accelerator { color: var(--warning); }
        .hub-menu-item.forum { color: #1d1d1f; }
        .hub-menu-item.network { color: var(--success); }
        .hub-menu-item.settings { color: #6b7280; }
        .hub-menu-item.theme { color: var(--accent); }
        .hub-menu-item.close { color: var(--danger); }

        .hub-menu-item.plexus:hover { background: rgba(37, 99, 235, 0.1); }
        .hub-menu-item.accelerator:hover { background: rgba(245, 158, 11, 0.1); }
        .hub-menu-item.forum:hover { background: rgba(29, 29, 31, 0.1); }
        .hub-menu-item.network:hover { background: rgba(47, 107, 58, 0.1); }
        .hub-menu-item.settings:hover { background: rgba(107, 114, 128, 0.1); }
        .hub-menu-item.theme:hover { background: rgba(155, 27, 34, 0.1); }
        .hub-menu-item.close:hover { background: rgba(239, 68, 68, 0.1); }

        [data-theme="dark"] .hub-menu-item {
            background: rgba(40, 40, 44, 0.95);
            border-color: rgba(255, 255, 255, 0.1);
        }

        [data-theme="dark"] .hub-menu-item.forum { color: #f5f5f7; }
        [data-theme="dark"] .hub-menu-item.theme { color: #fbbf24; }

        /* Notes Slide Panel */
        .notes-slide-panel {
            position: fixed;
            top: 0;
            right: -400px;
            width: 380px;
            max-width: 90vw;
            height: 100vh;
            background: rgba(255, 255, 255, 0.98);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            border-left: 1px solid rgba(0, 0, 0, 0.08);
            box-shadow: -20px 0 60px rgba(0, 0, 0, 0.1);
            z-index: 1000;
            display: flex;
            flex-direction: column;
            transition: right 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .notes-slide-panel.active {
            right: 0;
        }

        [data-theme="dark"] .notes-slide-panel {
            background: rgba(20, 20, 22, 0.98);
            border-left-color: rgba(255, 255, 255, 0.08);
