            border-bottom-color: rgba(255, 255, 255, 0.06);
        }

        .notes-panel-header h4 {
            font-size: 18px;
            font-weight: 600;
            color: var(--up-text, #1d1d1f);
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .notes-panel-header h4 i {
            color: var(--up-gold);
        }

        .notes-panel-close {
            width: 36px;
            height: 36px;
            border-radius: 12px;
            background: rgba(0, 0, 0, 0.05);
            border: none;
            color: var(--up-text-muted, #86868b);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s;
        }

        .notes-panel-close:hover {
            background: rgba(239, 68, 68, 0.1);
            color: var(--danger);
        }

        .notes-panel-body {
            flex: 1;
            padding: 24px;
            display: flex;
            flex-direction: column;
        }

        .notes-textarea {
            flex: 1;
            width: 100%;
