        }

        .notes-textarea:focus {
            outline: none;
            border-color: rgba(201, 169, 98, 0.4);
            background: rgba(0, 0, 0, 0.01);
        }

        .notes-textarea::placeholder {
            color: var(--up-text-muted, #86868b);
        }

        [data-theme="dark"] .notes-textarea {
            background: rgba(255, 255, 255, 0.05);
            border-color: rgba(255, 255, 255, 0.08);
            color: var(--up-text);
        }

        .notes-panel-footer {
            padding: 16px 24px 24px;
            display: flex;
            justify-content: flex-end;
        }

        .notes-save-btn {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 12px 24px;
            background: var(--up-gold);
            color: var(--up-navy, #1d1d1f);
            border: none;
            border-radius: 12px;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s;
        }

        .notes-save-btn:hover {
            background: #ddb872;
        }

        .notes-save-btn:active {
