        [data-theme="dark"] .notes-floating-btn {
            background: rgba(40, 40, 44, 0.9);
            border-color: rgba(255, 255, 255, 0.1);
        }

        /* Notification Dropdown */
        .hub-notif-dropdown {
            position: absolute;
            top: calc(100% + 12px);
            right: 0;
            width: 340px;
            background: #ffffff;
            border-radius: 16px;
            box-shadow: 0 20px 50px rgba(0, 0, 0, 0.15);
            opacity: 0;
            visibility: hidden;
            transform: translateY(-10px) scale(0.95);
            transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
            z-index: 1000;
            overflow: hidden;
        }

        .hub-notif-dropdown.active {
            opacity: 1;
            visibility: visible;
            transform: translateY(0) scale(1);
        }

        .hub-notif-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 16px 20px;
            border-bottom: 1px solid var(--paper-2);
        }

        .hub-notif-header h4 {
            font-size: 15px;
            font-weight: 600;
            color: var(--ink);
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .hub-notif-header h4 i {
            color: var(--up-gold);
        }

        .hub-notif-clear {
            font-size: 12px;
            color: var(--muted);
            background: none;
            border: none;
            cursor: pointer;
            transition: color 0.2s;
        }

        .hub-notif-clear:hover {
