            background: var(--paper);
        }

        .hub-notif-item.unread {
            background: rgba(201, 169, 98, 0.05);
        }

        .hub-notif-icon {
            width: 36px;
            height: 36px;
            border-radius: 10px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            flex-shrink: 0;
        }

        .hub-notif-icon.plexus {
            background: rgba(155, 27, 34, 0.1);
            color: var(--accent);
        }

        .hub-notif-icon.network {
            background: rgba(47, 107, 58, 0.1);
            color: var(--success);
        }

        .hub-notif-icon.quiz {
            background: rgba(201, 169, 98, 0.1);
            color: var(--up-gold);
