        .hub-notif-footer button {
            font-size: 13px;
            font-weight: 500;
            color: var(--up-gold);
            background: none;
            border: none;
            cursor: pointer;
            transition: opacity 0.2s;
        }

        .hub-notif-footer button:hover {
            opacity: 0.8;
