        .hub-account-dropdown-progress-fill.bronze { background: linear-gradient(90deg, #cd7f32, #a5632a); }
        .hub-account-dropdown-progress-fill.silver { background: linear-gradient(90deg, #c0c0c0, #9a9a9a); }
        .hub-account-dropdown-progress-fill.gold { background: linear-gradient(90deg, #ffd700, #daa520); }
        .hub-account-dropdown-progress-fill.platinum { background: linear-gradient(90deg, #b8b0d0, #d0c8e8); }

        .hub-account-dropdown-rewards-link {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-top: 10px;
            font-size: 12px;
            color: var(--up-gold);
            font-weight: 500;
        }

        .hub-account-dropdown-rewards-link i {
            font-size: 10px;
            transition: transform 0.2s;
        }

        .hub-account-dropdown-rewards:hover .hub-account-dropdown-rewards-link i {
            transform: translateX(3px);
        }

