            padding: 8px 0;
        }

        .hub-account-dropdown-item {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 12px 20px;
            font-size: 14px;
            color: var(--ink);
            cursor: pointer;
            transition: all 0.15s;
        }

        .hub-account-dropdown-item:hover {
            background: var(--paper);
            color: var(--ink);
        }

        .hub-account-dropdown-item i {
            width: 18px;
            color: var(--muted);
            text-align: center;
        }

        .hub-account-dropdown-item:hover i {
            color: var(--up-gold);
        }

        .hub-account-dropdown-divider {
            height: 1px;
            background: var(--paper-2);
            margin: 4px 0;
        }

        .hub-account-dropdown-item.danger {
            color: var(--danger);
        }

        .hub-account-dropdown-item.danger i {
            color: var(--danger);
        }

        .hub-account-dropdown-item.danger:hover {
            background: rgba(239, 68, 68, 0.05);
