        /* ===== Liquid Quick Actions Orb ===== */
        .quick-actions-orb-container {
            display: flex;
            justify-content: center;
            align-items: center;
            gap: 24px;
            padding: 0;
            position: relative;
            min-height: 280px;
            margin: 32px 0;
        }

        .quick-actions-orb-wrapper {
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .quick-actions-orb {
            width: 88px;
            height: 88px;
            border-radius: 16px;
            background: rgba(255, 255, 255, 0.7);
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            border: 1px solid rgba(255, 255, 255, 0.3);
            cursor: pointer;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 6px;
            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
            position: relative;
            z-index: 10;
            box-shadow: 0 4px 24px rgba(0, 0, 0, 0.08);
        }

        .quick-actions-orb::before {
            content: '';
            position: absolute;
            inset: 0;
            border-radius: 16px;
            border: 2px solid rgba(201, 169, 98, 0.2);
            animation: orbPulse 3s ease-in-out infinite;
            pointer-events: none;
        }

        .quick-actions-orb::after {
            content: '';
            position: absolute;
            inset: -4px;
            border-radius: 28px;
            border: 1px solid rgba(201, 169, 98, 0.1);
            animation: orbPulse 3s ease-in-out infinite 0.5s;
            pointer-events: none;
        }

        @keyframes orbPulse {
            0%, 100% { transform: scale(1); opacity: 1; }
            50% { transform: scale(1.06); opacity: 0.4; }
        }

        .quick-actions-orb i {
            font-size: 20px;
            color: var(--gold);
            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .quick-actions-orb span {
            font-size: 10px;
            font-weight: 600;
            color: rgba(0, 0, 0, 0.4);
            text-transform: uppercase;
            letter-spacing: 0.5px;
            transition: all 0.3s ease;
        }

        .quick-actions-orb:hover {
            background: rgba(255, 255, 255, 0.85);
            transform: scale(1.05);
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12);
            border-color: rgba(201, 169, 98, 0.3);
        }

        .quick-actions-orb:hover i {
            color: #B8963F;
            transform: rotate(90deg);
        }

        .quick-actions-orb:hover span {
            color: rgba(0, 0, 0, 0.6);
        }

        /* Expanded state - liquid separation into 4 circles */
        .quick-actions-orb.expanded {
            opacity: 0;
            transform: scale(0);
            pointer-events: none;
            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .quick-actions-orb.expanded::before,
        .quick-actions-orb.expanded::after {
            animation: none;
            opacity: 0;
        }

        /* Return animation for orb */
        .quick-actions-orb:not(.expanded) {
            transition: all 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) 0.3s;
        }

        .quick-actions-expanded {
            position: absolute;
            display: flex;
            align-items: center;
            justify-content: center;
            pointer-events: none;
            opacity: 0;
        }

        .quick-actions-expanded.active {
            pointer-events: all;
            opacity: 1;
        }

        .qa-item {
            position: absolute;
            width: 72px;
            height: 72px;
            border-radius: 14px;
            background: rgba(255, 255, 255, 0.85);
            backdrop-filter: blur(16px);
            -webkit-backdrop-filter: blur(16px);
            border: 1px solid rgba(255, 255, 255, 0.4);
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12);
            cursor: pointer;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 4px;
            opacity: 0;
        }

        .qa-item i {
            font-size: 20px;
            transition: transform 0.2s ease;
        }

        .qa-item span {
            font-size: 10px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.3px;
        }

        .qa-item:hover {
            box-shadow: 0 12px 40px rgba(0, 0, 0, 0.2);
        }

        .qa-item:hover i {
            transform: scale(1.15);
        }

        /* Individual item positions when expanded */
        .quick-actions-expanded.active .qa-item:nth-child(1) {
            transform: translate(-70px, -70px);
            opacity: 1;
            transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) 0s, opacity 0.3s ease 0s;
        }

        .quick-actions-expanded.active .qa-item:nth-child(2) {
            transform: translate(70px, -70px);
            opacity: 1;
            transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) 0.05s, opacity 0.3s ease 0.05s;
        }

        .quick-actions-expanded.active .qa-item:nth-child(3) {
            transform: translate(-70px, 70px);
            opacity: 1;
            transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) 0.1s, opacity 0.3s ease 0.1s;
        }

        .quick-actions-expanded.active .qa-item:nth-child(4) {
            transform: translate(70px, 70px);
            opacity: 1;
            transition: transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) 0.15s, opacity 0.3s ease 0.15s;
        }

        /* Closing animation - items return to center smoothly */
        .quick-actions-expanded.closing .qa-item {
            transform: translate(0, 0) scale(0.3) !important;
            opacity: 0 !important;
        }

        .quick-actions-expanded.closing .qa-item:nth-child(1) {
            transition: transform 0.5s cubic-bezier(0.4, 0, 0.6, 1) 0.15s, opacity 0.4s ease 0.25s !important;
        }

        .quick-actions-expanded.closing .qa-item:nth-child(2) {
            transition: transform 0.5s cubic-bezier(0.4, 0, 0.6, 1) 0.1s, opacity 0.4s ease 0.2s !important;
        }

        .quick-actions-expanded.closing .qa-item:nth-child(3) {
            transition: transform 0.5s cubic-bezier(0.4, 0, 0.6, 1) 0.05s, opacity 0.4s ease 0.15s !important;
        }

        .quick-actions-expanded.closing .qa-item:nth-child(4) {
            transition: transform 0.5s cubic-bezier(0.4, 0, 0.6, 1) 0s, opacity 0.4s ease 0.1s !important;
        }

        .quick-actions-expanded.closing .qa-close {
            transform: scale(0) !important;
            opacity: 0 !important;
            transition: all 0.3s ease 0s !important;
        }

        .quick-actions-expanded:not(.active):not(.closing) .qa-item {
            transform: translate(0, 0) scale(0);
            opacity: 0;
            transition: none;
        }

        /* Color themes for quick action items */
        .qa-item.plexus {
            background: linear-gradient(135deg, rgba(30, 64, 175, 0.95) 0%, rgba(37, 99, 235, 0.85) 100%);
            border-color: rgba(37, 99, 235, 0.3);
