            transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.2s, opacity 0.3s ease 0.2s;
        }

        .quick-actions-expanded:not(.active) .qa-close {
            transform: scale(0);
            opacity: 0;
            transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1) 0.15s, opacity 0.2s ease 0.15s;
