            font-weight: 600;
            cursor: pointer;
            transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
            position: relative;
            z-index: 2;
        }

        .hub-hero-cta:hover {
            background: #d4b876;
            gap: 14px;
            transform: translateY(-3px) scale(1.02);
            box-shadow: 0 12px 32px rgba(201, 169, 98, 0.5);
        }

        .hub-hero-cta:active {
            transform: translateY(0) scale(0.98);
            transition: all 0.1s ease;
        }

        .hub-hero-cta i {
            font-size: 12px;
            transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .hub-hero-cta:hover i {
            transform: translateX(6px);
        }

        /* Clicking state */
        .hub-hero-cta.clicking {
            pointer-events: none;
        }

        /* ===== FEATURED CAROUSEL ===== */
        .featured-carousel {
            position: relative;
            margin-bottom: 32px;
            border-radius: 16px;
            overflow: hidden;
            box-shadow: 0 16px 48px rgba(0, 0, 0, 0.15);
        }

        .featured-carousel-track {
            display: flex;
            transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .featured-slide {
            min-width: 100%;
            position: relative;
            padding: 48px;
            cursor: pointer;
            opacity: 0.5;
            transition: opacity 0.3s ease;
        }

        .featured-slide.active {
            opacity: 1;
        }

        .featured-slide-bg {
            position: absolute;
            inset: 0;
            z-index: 0;
        }

        .featured-slide-bg.plexus {
            background: linear-gradient(135deg, var(--emph-bg) 0%, var(--emph-bg-2) 50%, var(--crimson-deep) 100%);
        }

        .featured-slide-bg.plexus::before {
            content: '';
            position: absolute;
            top: 0;
            right: 0;
            width: 50%;
            height: 100%;
            background: radial-gradient(circle at 90% 10%, rgba(194, 72, 78, 0.2) 0%, transparent 50%);
        }

        .featured-slide-bg.accelerator {
            background: linear-gradient(135deg, var(--emph-bg) 0%, #083344 50%, #7e151b 100%);
        }

        .featured-slide-bg.accelerator::before {
            content: '';
            position: absolute;
            top: 0;
            right: 0;
            width: 50%;
            height: 100%;
            background: radial-gradient(circle at 90% 10%, rgba(176, 106, 31, 0.2) 0%, transparent 50%);
        }

        .featured-slide-bg.forum {
            background: linear-gradient(135deg, var(--emph-bg) 0%, #1a2540 50%, #2c3e5f 100%);
        }

        .featured-slide-bg.forum::before {
            content: '';
            position: absolute;
            top: 0;
            right: 0;
            width: 50%;
            height: 100%;
            background: radial-gradient(circle at 90% 10%, rgba(107,98,88, 0.15) 0%, transparent 50%);
        }

        .featured-slide-bg.gala {
            background: linear-gradient(135deg, var(--emph-bg) 0%, #2d1525 50%, #5c2040 100%);
        }

        .featured-slide-bg.gala::before {
            content: '';
            position: absolute;
            top: 0;
            right: 0;
            width: 50%;
            height: 100%;
            background: radial-gradient(circle at 90% 10%, rgba(225, 160, 180, 0.15) 0%, transparent 50%);
        }

        .featured-slide-bg.bridges {
            background: linear-gradient(135deg, #1a1a2e 0%, #2d1b4e 50%, #4a1d6b 100%);
        }

        .featured-slide-bg.bridges::before {
            content: '';
            position: absolute;
            top: 0;
            right: 0;
            width: 50%;
            height: 100%;
            background: radial-gradient(circle at 90% 10%, rgba(201, 169, 98, 0.2) 0%, transparent 50%);
        }

        /* Featured Slide Hero Image (fading from right) */
        .featured-slide-hero {
            position: absolute;
            top: 0;
            right: 0;
            width: 55%;
            height: 100%;
            background-size: cover;
            background-position: center;
            z-index: 0;
            opacity: 0.55;
            -webkit-mask-image: linear-gradient(to right, transparent 0%, rgba(0,0,0,0.4) 25%, rgba(0,0,0,0.8) 60%, rgba(0,0,0,1) 100%);
            mask-image: linear-gradient(to right, transparent 0%, rgba(0,0,0,0.4) 25%, rgba(0,0,0,0.8) 60%, rgba(0,0,0,1) 100%);
        }
        .featured-slide-hero.plexus {
            background-image: url('https://images.squarespace-cdn.com/content/v1/65982200bf95c64c8e823ecc/3d2949c3-41fa-48e2-9c50-df3116cb6800/Plexus+conference+-+Day+1-23.jpg');
        }
        .featured-slide-hero.accelerator {
            background-image: url('https://images.squarespace-cdn.com/content/v1/65982200bf95c64c8e823ecc/43fce86e-5811-4cab-a952-f13ef45e630b/375A5023.jpg');
        }
        .featured-slide-hero.forum {
            background-image: url('https://images.squarespace-cdn.com/content/v1/65982200bf95c64c8e823ecc/0595d4e3-e9c6-4d84-98c4-f1be67f2a547/375A4748.jpg');
        }
        .featured-slide-hero.gala {
            background-image: url('https://images.squarespace-cdn.com/content/v1/65982200bf95c64c8e823ecc/c5ba9724-0a82-46b1-b8f0-d66190200241/Plexus+conference+-+Day+1-24.jpg');
        }
        .featured-slide-hero.bridges {
            background-image: url('https://images.squarespace-cdn.com/content/v1/65982200bf95c64c8e823ecc/aab785ef-877b-4a21-a052-b5f88a0541d4/PHOTO-2023-09-05-11-36-15+3.jpg');
        }
        @media (max-width: 640px) {
            .featured-slide-hero {
                width: 100%;
                opacity: 0.2;
                -webkit-mask-image: linear-gradient(to bottom, transparent 0%, rgba(0,0,0,0.3) 50%, rgba(0,0,0,0.5) 100%);
                mask-image: linear-gradient(to bottom, transparent 0%, rgba(0,0,0,0.3) 50%, rgba(0,0,0,0.5) 100%);
            }
        }

        .featured-slide-content {
            position: relative;
            z-index: 2;
            pointer-events: auto;
        }

        .featured-badge {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 8px 16px;
            background: rgba(255, 255, 255, 0.15);
            backdrop-filter: blur(8px);
            -webkit-backdrop-filter: blur(8px);
            border-radius: 100px;
            font-size: 12px;
            font-weight: 600;
            color: white;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            margin-bottom: 20px;
        }

        .featured-badge i.pulse {
            animation: pulse 2s ease-in-out infinite;
        }

        @keyframes pulse {
            0%, 100% { opacity: 1; transform: scale(1); }
            50% { opacity: 0.5; transform: scale(1.2); }
        }

        .featured-title {
            font-size: clamp(24px, 4vw, 36px);
            font-weight: 700;
            color: #ffffff;
            margin-bottom: 12px;
            line-height: 1.2;
        }

        .featured-desc {
            font-size: 16px;
            color: rgba(255, 255, 255, 0.7);
            line-height: 1.6;
            max-width: 500px;
            margin-bottom: 28px;
        }

        .featured-cta {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            padding: 14px 28px;
            background: var(--up-gold);
            color: var(--ink);
            border: none;
            border-radius: 14px;
            font-size: 15px;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.3s ease;
            position: relative;
            z-index: 5;
            touch-action: manipulation;
        }

        .featured-cta:hover {
            background: #d4b876;
            transform: translateY(-2px);
            box-shadow: 0 8px 24px rgba(201, 169, 98, 0.4);
        }

        .featured-carousel-nav {
            position: absolute;
            bottom: 24px;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            align-items: center;
            gap: 16px;
            z-index: 10;
        }

        .featured-nav-arrow {
            width: 36px;
            height: 36px;
            display: flex;
            align-items: center;
            justify-content: center;
            background: rgba(255, 255, 255, 0.2);
            backdrop-filter: blur(8px);
            -webkit-backdrop-filter: blur(8px);
            border: none;
            border-radius: 50%;
            color: white;
            font-size: 14px;
            cursor: pointer;
            transition: all 0.2s;
            touch-action: manipulation;
            z-index: 20;
        }

        .featured-nav-arrow:hover {
            background: rgba(255, 255, 255, 0.3);
            transform: scale(1.1);
        }

        .featured-dots {
            display: flex;
            gap: 8px;
        }

        .featured-dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.3);
            border: none;
            cursor: pointer;
            transition: all 0.3s ease;
            touch-action: manipulation;
        }

        .featured-dot.active {
            background: var(--up-gold);
            transform: scale(1.2);
        }

        .featured-dot:hover:not(.active) {
            background: rgba(255, 255, 255, 0.5);
        }

        /* Mobile responsive */
        @media (max-width: 768px) {
            .featured-slide {
                padding: 32px 24px;
            }

            .featured-carousel-nav {
                bottom: 16px;
            }

            .featured-nav-arrow {
                width: 44px;
                height: 44px;
            }
        }

        /* Dollar sign pop animation */
        .dollar-pop {
            position: fixed;
            font-size: 24px;
            font-weight: bold;
            color: var(--success);
            pointer-events: none;
            z-index: 10000;
            text-shadow: 0 2px 8px rgba(47, 107, 58, 0.5);
            animation: dollar-float 1s ease-out forwards;
        }

        @keyframes dollar-float {
            0% {
                opacity: 1;
                transform: translateY(0) scale(0.5) rotate(0deg);
            }
            50% {
                opacity: 1;
                transform: translateY(-40px) scale(1.2) rotate(10deg);
            }
            100% {
                opacity: 0;
                transform: translateY(-80px) scale(0.8) rotate(-5deg);
            }
        }

        /* Bento Grid */
        .hub-bento {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 16px;
            margin-top: 32px;
        }

        /* ===== NEW CLEAN BENTO LAYOUT ===== */
        .hub-bento-clean {
            display: flex;
            flex-direction: column;
            gap: 32px;
            margin-top: 32px;
        }

        .hub-section-label {
            font-size: 15px;
            font-weight: 700;
            text-transform: none;
            letter-spacing: 0.3px;
            color: var(--up-text, #1d1d1f);
            margin-bottom: 8px;
        }

        [data-theme="dark"] .hub-section-label {
            color: var(--up-text, var(--line));
        }

        /* News + Programs Side by Side Row */
        .news-programs-row {
            display: grid;
            grid-template-columns: 1fr;
            gap: 16px;
            margin-top: 24px;
        }
        @media (max-width: 768px) {
            .news-programs-row {
                grid-template-columns: 1fr;
            }
        }
        .news-half, .programs-half {
            display: flex;
            flex-direction: column;
            gap: 8px;
        }
        .medx-news-compact {
            background: var(--up-bg-subtle, #f5f5f7);
            border-radius: 16px;
            padding: 12px;
            border: 1px solid var(--up-border, #d2d2d7);
        }
        [data-theme="dark"] .medx-news-compact {
            background: rgba(20,15,12, 0.4);
            border-color: rgba(201, 169, 98, 0.1);
        }
        .news-compact-list {
            display: flex;
            flex-direction: column;
            gap: 4px;
        }
        .news-view-more {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
            width: 100%;
            padding: 10px;
            margin-top: 8px;
            background: none;
            border: 1px solid var(--up-border, #d2d2d7);
            border-radius: 10px;
            color: var(--up-gold, var(--gold));
            font-size: 12px;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s;
        }
        .news-view-more:hover {
            background: rgba(201, 169, 98, 0.1);
            border-color: var(--up-gold, var(--gold));
        }
        .programs-compact {
            display: flex;
            flex-direction: column;
            gap: 4px;
        }
        .program-compact-item {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 8px 12px;
            background: var(--up-bg-subtle, #f5f5f7);
            border-radius: 10px;
            border: 1px solid var(--up-border, #d2d2d7);
            cursor: pointer;
            transition: all 0.2s;
        }
        .program-compact-item:hover {
            background: var(--up-bg-muted, #e5e5ea);
            border-color: var(--up-gold, var(--gold));
        }
        [data-theme="dark"] .program-compact-item {
            background: rgba(20,15,12, 0.4);
            border-color: rgba(201, 169, 98, 0.1);
        }
        [data-theme="dark"] .program-compact-item:hover {
            background: rgba(201, 169, 98, 0.08);
            border-color: rgba(201, 169, 98, 0.25);
        }
        .program-compact-icon {
            width: 30px;
            height: 30px;
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 13px;
            color: white;
            flex-shrink: 0;
        }
        .program-compact-icon.plexus { background: linear-gradient(135deg, #9b1b22, var(--accent)); }
        .program-compact-icon.accelerator { background: linear-gradient(135deg, #0891b2, var(--accent)); }
        .program-compact-icon.forum { background: linear-gradient(135deg, #b45309, var(--gold)); }
        .program-compact-text {
            display: flex;
            flex-direction: column;
            gap: 1px;
            min-width: 0;
        }
        .program-compact-text strong {
            font-size: 12.5px;
            font-weight: 600;
            color: var(--up-text, #1d1d1f);
        }
        .program-compact-text span {
            font-size: 10.5px;
            color: var(--up-text-muted, var(--muted));
        }

        /* Programs Trio - 3 Equal Cards */
        .hub-programs-trio {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 16px;
        }

        .hub-program-tile {
            background: rgba(255, 255, 255, 0.8);
            backdrop-filter: blur(20px);
            border: 1px solid rgba(0, 0, 0, 0.06);
            border-radius: 16px;
            padding: 20px;
            display: flex;
            align-items: center;
            gap: 14px;
            cursor: pointer;
            transition: all 0.2s ease;
        }

        .hub-program-tile:hover {
            background: white;
            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
            transform: translateY(-2px);
        }

        [data-theme="dark"] .hub-program-tile {
            background: rgba(30, 30, 32, 0.8);
            border-color: rgba(255, 255, 255, 0.08);
        }

        [data-theme="dark"] .hub-program-tile:hover {
            background: rgba(40, 40, 44, 0.9);
            border-color: rgba(255, 255, 255, 0.12);
        }

        .hub-program-tile-icon {
            width: 44px;
            height: 44px;
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 18px;
            flex-shrink: 0;
        }

        .hub-program-tile-icon.plexus {
            background: linear-gradient(135deg, var(--emph-bg) 0%, var(--emph-bg-2) 100%);
            color: white;
        }

        .hub-program-tile-icon.accelerator {
            background: linear-gradient(135deg, #0891b2 0%, var(--accent) 100%);
            color: white;
        }

        .hub-program-tile-icon.forum {
            background: linear-gradient(135deg, var(--gold) 0%, #d4b876 100%);
            color: var(--ink);
        }

        .hub-program-tile-content {
            flex: 1;
            min-width: 0;
        }

        .hub-program-tile-content h4 {
            font-size: 14px;
            font-weight: 600;
            color: #1d1d1f;
            margin-bottom: 2px;
        }

        [data-theme="dark"] .hub-program-tile-content h4 {
            color: #f5f5f7;
        }

        .hub-program-tile-content p {
            font-size: 12px;
            color: #86868b;
        }

        .hub-program-tile-arrow {
            color: #c4c4c6;
            font-size: 12px;
            transition: transform 0.2s;
        }

        .hub-program-tile:hover .hub-program-tile-arrow {
            transform: translateX(3px);
            color: var(--up-gold);
        }

        /* What's Next - Clean Action Card */
        .hub-whats-next-clean {
            background: linear-gradient(135deg, rgba(201, 169, 98, 0.08) 0%, rgba(201, 169, 98, 0.03) 100%);
            border: 1px solid rgba(201, 169, 98, 0.2);
            border-radius: 16px;
            padding: 20px 24px;
            display: flex;
            align-items: center;
            gap: 16px;
        }

        [data-theme="dark"] .hub-whats-next-clean {
            background: linear-gradient(135deg, rgba(201, 169, 98, 0.12) 0%, rgba(201, 169, 98, 0.04) 100%);
        }

        .hub-whats-next-icon {
            width: 40px;
            height: 40px;
            border-radius: 10px;
            background: var(--up-gold);
            color: white;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 16px;
            flex-shrink: 0;
        }

        .hub-whats-next-content {
            flex: 1;
        }

        .hub-whats-next-content h4 {
            font-size: 14px;
            font-weight: 600;
            color: #1d1d1f;
            margin-bottom: 2px;
        }

        [data-theme="dark"] .hub-whats-next-content h4 {
            color: #f5f5f7;
        }

        .hub-whats-next-content p {
            font-size: 13px;
            color: #86868b;
        }

        .hub-whats-next-cta {
            background: var(--up-gold);
            color: white;
            border: none;
            padding: 10px 18px;
            border-radius: 8px;
            font-size: 13px;
            font-weight: 600;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 6px;
            transition: all 0.2s;
        }

        .hub-whats-next-cta:hover {
            background: #b8973d;
            transform: translateY(-1px);
        }

        /* Events List - Compact */
        .hub-events-list-clean {
            background: rgba(255, 255, 255, 0.8);
            backdrop-filter: blur(20px);
            border: 1px solid rgba(0, 0, 0, 0.06);
            border-radius: 12px;
            overflow: hidden;
        }

        [data-theme="dark"] .hub-events-list-clean {
            background: rgba(30, 30, 32, 0.8);
            border-color: rgba(255, 255, 255, 0.08);
        }

        .hub-event-row {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 10px 14px;
            cursor: pointer;
            transition: background 0.15s;
            border-bottom: 1px solid rgba(0, 0, 0, 0.04);
        }

        .hub-event-row:last-child {
            border-bottom: none;
        }

        .hub-event-row:hover {
            background: rgba(0, 0, 0, 0.02);
        }

        [data-theme="dark"] .hub-event-row {
            border-bottom-color: rgba(255, 255, 255, 0.04);
        }

        [data-theme="dark"] .hub-event-row:hover {
            background: rgba(255, 255, 255, 0.03);
        }

        .hub-event-row-icon {
            width: 28px;
            height: 28px;
            border-radius: 7px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            flex-shrink: 0;
        }

        .hub-event-row-icon.plexus {
            background: linear-gradient(135deg, var(--emph-bg) 0%, var(--emph-bg-2) 100%);
            color: white;
        }

        .hub-event-row-icon.gala {
            background: linear-gradient(135deg, var(--gold) 0%, #d4b876 100%);
            color: var(--ink);
        }

        .hub-event-row-icon.workshop {
            background: linear-gradient(135deg, #9b1b22 0%, var(--accent) 100%);
            color: white;
        }

        .hub-event-row-info {
            flex: 1;
            min-width: 0;
        }

        .hub-event-row-info h4 {
            font-size: 13px;
            font-weight: 600;
            color: #1d1d1f;
            margin-bottom: 0;
        }

        [data-theme="dark"] .hub-event-row-info h4 {
            color: #f5f5f7;
        }

        .hub-event-row-info span {
            font-size: 12px;
            color: #86868b;
        }

        .hub-event-row-status {
            display: flex;
            align-items: center;
            gap: 4px;
            font-size: 10px;
            font-weight: 600;
            padding: 3px 8px;
            border-radius: 14px;
            white-space: nowrap;
        }

        .hub-event-row-status.opportunity {
            background: rgba(47, 107, 58, 0.1);
            color: var(--success);
        }

        .hub-event-row-status.urgent {
            background: rgba(239, 68, 68, 0.1);
            color: var(--danger);
        }

        .hub-event-row-status.interested {
            background: rgba(201, 169, 98, 0.1);
            color: #b8973d;
        }

        .hub-event-row-status.registered {
            background: rgba(59, 130, 246, 0.1);
            color: var(--accent);
        }

        .hub-event-row-status.pending {
            background: rgba(245, 158, 11, 0.1);
            color: var(--warning);
        }

        .hub-event-row-status.confirmed {
            background: rgba(47, 107, 58, 0.1);
            color: var(--success);
        }

        .hub-event-row-action {
            background: transparent;
            border: 1px solid rgba(0, 0, 0, 0.1);
            color: #1d1d1f;
            padding: 4px 10px;
            border-radius: 6px;
            font-size: 11px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.15s;
            white-space: nowrap;
        }

        .hub-event-row-action:hover {
            background: #1d1d1f;
            color: white;
            border-color: #1d1d1f;
        }

        .hub-event-row-action.accent {
            background: var(--up-gold);
            color: white;
            border-color: var(--up-gold);
        }

        .hub-event-row-action.accent:hover {
            background: #b8973d;
            border-color: #b8973d;
        }

        [data-theme="dark"] .hub-event-row-action {
            border-color: rgba(255, 255, 255, 0.15);
            color: #f5f5f7;
        }

        [data-theme="dark"] .hub-event-row-action:hover {
            background: #f5f5f7;
            color: #1d1d1f;
        }

