        .hub-quick-links {
            display: flex;
            justify-content: center;
            gap: 32px;
            padding-top: 8px;
        }

        .hub-quick-link {
            color: #86868b;
            font-size: 13px;
            display: flex;
            align-items: center;
            gap: 6px;
            cursor: pointer;
            transition: color 0.15s;
            text-decoration: none;
        }

        .hub-quick-link:hover {
            color: var(--up-gold);
        }

        .hub-quick-link i {
            font-size: 14px;
        }

        /* Mobile Responsive */
        @media (max-width: 768px) {
            .hub-programs-trio {
                grid-template-columns: 1fr;
            }

            .hub-whats-next-clean {
                flex-direction: column;
                align-items: flex-start;
                text-align: left;
            }

            .hub-whats-next-cta {
                width: 100%;
                justify-content: center;
            }

            .hub-event-row {
                flex-wrap: wrap;
            }

            .hub-event-row-status {
                order: 3;
                width: 100%;
                justify-content: center;
                margin-top: 8px;
            }

            .hub-event-row-action {
                order: 4;
                width: 100%;
                margin-top: 8px;
                text-align: center;
            }

            .hub-status-bar {
                flex-wrap: wrap;
            }

            .hub-status-tier {
                width: 100%;
                justify-content: center;
            }

            .hub-status-points {
                flex: none;
                width: 50%;
            }

            .hub-status-view {
                flex: none;
                width: calc(50% - 8px);
                justify-content: center;
            }

            .hub-quick-links {
                flex-wrap: wrap;
                gap: 16px;
            }

            .hub-quick-link {
                width: calc(50% - 8px);
                justify-content: center;
            }
