        }

        .hub-card-header.navy .hub-card-title {
            color: white;
        }

        .hub-card-header.navy .hub-card-title i {
            color: var(--up-gold);
        }

        .hub-card-header.navy .hub-card-action {
            background: rgba(255, 255, 255, 0.1);
            color: white;
        }

        .hub-card-header.navy .hub-card-action:hover {
            background: var(--up-gold);
            color: var(--ink);
        }

        /* ===== Compact Collapsible Cards ===== */
        .hub-card-compact {
