        .hub-compact-icon {
            width: 40px;
            height: 40px;
            border-radius: 12px;
            background: rgba(201, 169, 98, 0.2);
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--up-gold);
            font-size: 16px;
        }

        .hub-compact-title h4 {
            font-size: 14px;
            font-weight: 600;
            color: white;
