            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 10px;
        }

        .hub-quick-dropdown-item {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 14px 16px;
            background: var(--up-bg-subtle, var(--paper));
            border-radius: 12px;
