            border-radius: 12px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .hub-message-compact:hover {
            background: rgba(201, 169, 98, 0.08);
        }

        .hub-message-compact.unread {
            background: rgba(201, 169, 98, 0.05);
            border-left: 3px solid var(--up-gold);
        }

        .hub-message-compact .hub-msg-avatar {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--up-gold) 0%, #d4af6a 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 13px;
            font-weight: 600;
            color: var(--ink);
            flex-shrink: 0;
        }

        .hub-message-compact .hub-msg-content {
            flex: 1;
            min-width: 0;
        }

        .hub-message-compact .hub-msg-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 4px;
        }

        .hub-message-compact .hub-msg-header h4 {
            font-size: 14px;
            font-weight: 600;
            color: var(--up-text, var(--emph-bg));
        }

        .hub-message-compact .hub-msg-header span {
            font-size: 11px;
            color: var(--up-text-muted, var(--muted));
        }

        .hub-message-compact .hub-msg-content p {
            font-size: 12px;
            color: var(--up-text-secondary, var(--muted));
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .hub-messages-all-btn {
            width: 100%;
            padding: 14px;
            background: linear-gradient(135deg, var(--emph-bg) 0%, var(--emph-bg-2) 100%);
            border: none;
            border-radius: 12px;
            color: white;
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            margin-top: 8px;
            transition: all 0.2s;
        }

        .hub-messages-all-btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 20px -6px rgba(20,15,12, 0.3);
        }

        .hub-messages-all-btn i {
            color: var(--up-gold);
        }

        /* Research Dropdown */
        .hub-research-dropdown {
            padding: 16px;
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .hub-article-compact {
            display: flex;
            align-items: center;
            gap: 14px;
            padding: 14px 16px;
            background: var(--up-bg-subtle, var(--paper));
            border-radius: 12px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .hub-article-compact:hover {
            background: rgba(201, 169, 98, 0.08);
            transform: translateX(4px);
        }

        .hub-article-compact .hub-article-source {
            padding: 6px 10px;
            border-radius: 8px;
            font-size: 11px;
            font-weight: 700;
            text-transform: uppercase;
            flex-shrink: 0;
        }

        .hub-article-compact .hub-article-source.nature {
            background: var(--danger);
            color: white;
        }

        .hub-article-compact .hub-article-source.science {
            background: var(--accent);
            color: white;
        }

        .hub-article-compact .hub-article-source.cell {
            background: #059669;
            color: white;
        }

        .hub-article-compact .hub-article-content {
            flex: 1;
            min-width: 0;
        }

        .hub-article-compact .hub-article-content h4 {
            font-size: 13px;
            font-weight: 600;
            color: var(--up-text, var(--emph-bg));
            margin-bottom: 4px;
            line-height: 1.4;
        }

        .hub-article-compact .hub-article-meta {
            font-size: 11px;
            color: var(--up-text-muted, var(--muted));
        }

        .hub-article-compact > i {
            color: var(--up-text-muted, var(--muted));
            font-size: 12px;
            transition: all 0.2s;
        }

        .hub-article-compact:hover > i {
            color: var(--up-gold);
        }

        /* ===== Regular Card Content Styles ===== */

        /* Card Badge */
        .hub-card-badge {
            padding: 4px 10px;
            background: rgba(201, 169, 98, 0.15);
            border-radius: 14px;
            font-size: 11px;
            font-weight: 600;
            color: var(--up-gold);
        }

        /* Updates Card */
        .hub-updates-card {
            grid-column: span 12;
            margin-bottom: 0;
        }

        .hub-updates-list {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        /* Programs Card */
        .hub-programs-card {
            grid-column: span 6;
        }

        .hub-programs-grid {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        /* Quick Actions Card */
        .hub-actions-card {
            grid-column: span 6;
        }

        .hub-actions-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 10px;
        }

        /* Community Card */
        .hub-community-card {
            grid-column: span 6;
        }

        .hub-community-stats {
            display: flex;
            gap: 12px;
        }

        .hub-stat-badge {
            font-size: 12px;
            color: var(--up-text-secondary, var(--muted));
            padding: 4px 10px;
            background: var(--up-bg-subtle, var(--paper));
            border-radius: 14px;
        }

        .hub-stat-badge strong {
            color: var(--up-text, var(--emph-bg));
            font-weight: 700;
        }

        .hub-stat-badge.online strong {
            color: var(--success);
        }

        .hub-community-regions {
            display: flex;
            flex-direction: column;
            gap: 8px;
            margin-bottom: 16px;
        }

        .hub-region-item {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 10px 14px;
            background: var(--up-bg-subtle, var(--paper));
            border-radius: 10px;
        }

        .hub-region-item .hub-region-flag {
            font-size: 18px;
        }

        .hub-region-item .hub-region-name {
            font-size: 13px;
            font-weight: 500;
            color: var(--up-text, var(--emph-bg));
            min-width: 120px;
        }

        .hub-region-item .hub-region-bar {
            flex: 1;
            height: 6px;
            background: var(--up-border, var(--line));
            border-radius: 3px;
            overflow: hidden;
        }

        .hub-region-item .hub-region-fill {
            height: 100%;
            background: linear-gradient(90deg, var(--up-gold), #d4af37);
            border-radius: 3px;
        }

        .hub-region-item .hub-region-count {
            font-size: 13px;
            font-weight: 600;
            color: var(--up-text, var(--emph-bg));
            min-width: 40px;
            text-align: right;
        }

        /* Research Card */
        .hub-research-card {
            grid-column: span 6;
        }

        .hub-research-list {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .hub-article-item {
            display: flex;
            align-items: center;
            gap: 14px;
            padding: 14px 16px;
            background: var(--up-bg-subtle, var(--paper));
            border-radius: 12px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .hub-article-item:hover {
            background: rgba(201, 169, 98, 0.08);
            transform: translateX(4px);
        }

        .hub-article-item .hub-article-source {
            padding: 6px 10px;
            border-radius: 8px;
            font-size: 10px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            flex-shrink: 0;
        }

        .hub-article-item .hub-article-source.nature {
            background: var(--danger);
            color: white;
        }

        .hub-article-item .hub-article-source.science {
            background: var(--accent);
            color: white;
        }

        .hub-article-item .hub-article-source.cell {
            background: #059669;
            color: white;
        }

        .hub-article-item .hub-article-content {
            flex: 1;
            min-width: 0;
        }

        .hub-article-item .hub-article-content h4 {
            font-size: 13px;
            font-weight: 600;
            color: var(--up-text, var(--emph-bg));
            margin-bottom: 4px;
            line-height: 1.4;
        }

        .hub-article-item .hub-article-meta {
            font-size: 11px;
            color: var(--up-text-muted, var(--muted));
        }

        .hub-article-item > i {
            color: var(--up-text-muted, var(--muted));
            font-size: 12px;
            transition: all 0.2s;
        }

        .hub-article-item:hover > i {
            color: var(--up-gold);
        }

        /* Responsive for regular cards */
        @media (max-width: 768px) {
            .hub-updates-card,
            .hub-programs-card,
            .hub-actions-card,
            .hub-community-card,
            .hub-research-card {
                grid-column: span 12;
            }

            .hub-actions-grid {
                grid-template-columns: 1fr;
            }

            .hub-community-stats {
                display: none;
            }
        }

        /* Compact Header Stats (for Global Community) */
        .hub-compact-stats {
            display: flex;
            gap: 16px;
            margin-right: 12px;
        }

        .hub-compact-stat {
            font-size: 12px;
            color: rgba(255, 255, 255, 0.7);
        }

        .hub-compact-stat strong {
            color: var(--up-gold);
            font-weight: 700;
        }

        .hub-compact-stat.active strong {
            color: var(--success);
        }

        /* Responsive for compact cards */
        @media (max-width: 768px) {
            .hub-actions-dropdown {
                grid-template-columns: 1fr;
            }

            .hub-compact-stats {
                display: none;
            }

            .hub-region-compact .hub-region-info {
                min-width: 120px;
            }

            .hub-program-card {
                padding: 14px 16px;
            }

            .hub-program-card-icon {
                width: 44px;
                height: 44px;
                font-size: 18px;
            }
        }

        /* Footer */
        .hub-footer {
            background: linear-gradient(135deg, var(--emph-bg) 0%, var(--emph-bg-2) 100%);
            padding: 40px 24px;
            margin-top: 32px;
            border-radius: 16px 24px 0 0;
        }

        .hub-footer-content {
            max-width: 1200px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 40px;
        }

        .hub-footer-brand {
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        .hub-footer-logo {
            font-size: 28px;
            font-weight: 700;
            color: white;
        }

        .hub-footer-logo span {
            color: var(--up-gold);
        }

        .hub-footer-tagline {
            font-size: 14px;
            color: rgba(255, 255, 255, 0.6);
            line-height: 1.6;
            max-width: 280px;
        }

        .hub-footer-socials {
            display: flex;
            gap: 12px;
            margin-top: 8px;
        }

        .hub-footer-social {
            width: 40px;
            height: 40px;
            border-radius: 10px;
            background: rgba(255, 255, 255, 0.1);
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            text-decoration: none;
            transition: all 0.2s;
        }

        .hub-footer-social:hover {
            background: var(--up-gold);
            color: var(--ink);
            transform: translateY(-2px);
        }

        .hub-footer-column h5 {
            font-size: 12px;
            font-weight: 600;
            color: var(--up-gold);
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 16px;
        }

        .hub-footer-links {
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .hub-footer-links a {
            font-size: 14px;
            color: rgba(255, 255, 255, 0.7);
            text-decoration: none;
            transition: all 0.2s;
        }

        .hub-footer-links a:hover {
            color: white;
            padding-left: 4px;
        }

        .hub-footer-contact {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .hub-footer-contact-item {
            display: flex;
            align-items: flex-start;
            gap: 10px;
            font-size: 13px;
            color: rgba(255, 255, 255, 0.7);
        }

        .hub-footer-contact-item i {
            color: var(--up-gold);
            margin-top: 2px;
        }

        .hub-footer-bottom {
            max-width: 1200px;
            margin: 32px auto 0;
            padding-top: 24px;
            border-top: 1px solid rgba(255, 255, 255, 0.1);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .hub-footer-copyright {
            font-size: 13px;
            color: rgba(255, 255, 255, 0.5);
        }

        .hub-footer-legal {
            display: flex;
            gap: 24px;
        }

        .hub-footer-legal a {
            font-size: 13px;
            color: rgba(255, 255, 255, 0.5);
            text-decoration: none;
            transition: color 0.2s;
        }

        .hub-footer-legal a:hover {
            color: white;
        }

        @media (max-width: 900px) {
            .hub-footer-content {
                grid-template-columns: 1fr 1fr;
                gap: 32px;
            }

            .hub-footer-brand {
                grid-column: span 2;
            }

            .hub-programs-dropdown {
                grid-template-columns: 1fr;
            }

            .hub-quick-dropdown {
                grid-template-columns: 1fr;
            }

            .hub-community-dropdown {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        @media (max-width: 640px) {
            .hub-footer-content {
                grid-template-columns: 1fr;
            }

            .hub-footer-brand {
                grid-column: span 1;
            }

            .hub-footer-bottom {
                flex-direction: column;
                gap: 16px;
                text-align: center;
            }

            .hub-compact-stats {
                display: none;
            }

            .hub-community-dropdown {
                grid-template-columns: 1fr;
            }
        }

        /* ===== Floating Messages Button ===== */
        .floating-messages-btn {
            position: fixed;
            bottom: 24px;
            right: 24px;
            width: 52px;
            height: 52px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--emph-bg) 0%, var(--emph-bg-2) 100%);
            box-shadow: 0 4px 20px -4px rgba(20,15,12, 0.4);
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            z-index: 1000;
            transition: all 0.3s ease;
        }

        .floating-messages-btn:hover {
            transform: scale(1.1);
            box-shadow: 0 8px 30px -6px rgba(20,15,12, 0.5);
        }

        .floating-messages-btn i {
            font-size: 20px;
            color: var(--up-gold);
        }

        .floating-messages-badge {
            position: absolute;
            top: -4px;
            right: -4px;
            width: 22px;
            height: 22px;
            border-radius: 50%;
            background: var(--danger);
            color: white;
            font-size: 11px;
            font-weight: 700;
            display: flex;
            align-items: center;
            justify-content: center;
            border: 2px solid white;
        }

        /* ===== Floating Profile Button ===== */
        .floating-profile-btn {
            display: none !important;
            position: fixed;
            bottom: 24px;
            right: 88px;
            width: 52px;
            height: 52px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--gold) 0%, #d4b876 100%);
            box-shadow: 0 4px 20px -4px rgba(201, 169, 98, 0.5);
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            z-index: 1000;
            transition: all 0.3s ease;
        }

        .floating-profile-btn:hover {
            transform: scale(1.1);
            box-shadow: 0 8px 30px -6px rgba(201, 169, 98, 0.6);
        }

        .floating-profile-avatar {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: var(--emph-bg);
            color: var(--gold);
            font-size: 16px;
            font-weight: 700;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        /* Profile Quick Panel */
        .profile-quick-panel {
            position: fixed;
            bottom: 90px;
            right: 88px;
            width: 280px;
            background: white;
            border-radius: 14px;
            box-shadow: 0 10px 50px rgba(0, 0, 0, 0.15);
            z-index: 1001;
            display: none;
            flex-direction: column;
            overflow: hidden;
            transform: scale(0.9) translateY(20px);
            opacity: 0;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .profile-quick-panel.active {
            display: flex;
            transform: scale(1) translateY(0);
            opacity: 1;
        }

        [data-theme="dark"] .profile-quick-panel {
            background: var(--emph-bg-2);
        }

        .profile-quick-header {
            display: flex;
            align-items: center;
            gap: 14px;
            padding: 20px;
            background: linear-gradient(135deg, var(--emph-bg) 0%, var(--emph-bg-2) 100%);
        }

        .profile-quick-avatar {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--gold) 0%, #d4b876 100%);
            color: var(--ink);
            font-size: 20px;
            font-weight: 700;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }

        .profile-quick-info h4 {
            font-size: 16px;
            font-weight: 600;
            color: white;
            margin: 0 0 2px 0;
        }

        .profile-quick-info p {
            font-size: 12px;
            color: rgba(255, 255, 255, 0.6);
            margin: 0;
        }

        .profile-quick-stats {
            display: flex;
            justify-content: space-around;
            padding: 16px;
            border-bottom: 1px solid var(--up-border, var(--line));
        }

        .profile-quick-stat {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 2px;
        }

        .profile-quick-stat .value {
            font-size: 18px;
            font-weight: 700;
            color: var(--up-text, var(--emph-bg));
        }

        .profile-quick-stat .label {
            font-size: 10px;
            color: var(--up-text-secondary, var(--muted));
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .profile-quick-actions {
            display: flex;
            flex-direction: column;
            padding: 12px;
            gap: 4px;
        }

        .profile-quick-actions button {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 12px 16px;
            background: transparent;
            border: none;
            border-radius: 10px;
            color: var(--up-text, var(--emph-bg));
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s ease;
            text-align: left;
        }

        .profile-quick-actions button:hover {
            background: var(--up-hover, var(--paper-2));
        }

        .profile-quick-actions button i {
            width: 20px;
            color: var(--gold);
            font-size: 14px;
        }

        @media (max-width: 768px) {
            .floating-profile-btn {
                bottom: 16px;
                right: 80px;
                width: 46px;
                height: 46px;
            }

            .floating-profile-avatar {
                width: 36px;
                height: 36px;
                font-size: 14px;
            }

            .profile-quick-panel {
                right: 16px;
                bottom: 80px;
                width: calc(100vw - 32px);
                max-width: 320px;
            }
        }

        /* ===== Dashboard Header with Customize Button ===== */
        .hub-dashboard-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 20px;
        }

        .hub-dashboard-header h2 {
            font-size: 13px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: var(--up-text-secondary, #86868b);
        }

        .hub-customize-btn {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 10px 18px;
            background: linear-gradient(135deg, var(--up-gold, var(--gold)) 0%, #d4b876 100%);
            border: none;
            border-radius: 12px;
            color: var(--ink);
            font-size: 13px;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
            box-shadow: 0 4px 16px -4px rgba(201, 169, 98, 0.4);
        }

        .hub-customize-btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 24px -6px rgba(201, 169, 98, 0.5);
        }

        .hub-customize-btn:active {
            transform: translateY(0);
        }

        .hub-customize-btn i {
            font-size: 12px;
        }

        /* ===== Card Picker Modal ===== */
        .card-picker-overlay {
            position: fixed;
            inset: 0;
            background: rgba(0, 0, 0, 0.6);
            backdrop-filter: blur(8px);
            -webkit-backdrop-filter: blur(8px);
            z-index: 10000;
            display: none;
            align-items: center;
            justify-content: center;
            padding: 24px;
            opacity: 0;
            transition: opacity 0.3s ease;
        }

        .card-picker-overlay.active {
            display: flex;
            opacity: 1;
        }

        .card-picker-modal {
            background: var(--emph-bg);
            border-radius: 16px;
            max-width: 800px;
            width: 100%;
            max-height: 85vh;
            overflow: hidden;
            display: flex;
            flex-direction: column;
            box-shadow: 0 25px 80px -12px rgba(0, 0, 0, 0.5);
            transform: scale(0.95) translateY(20px);
            transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
            border: 1px solid var(--emph-line);
        }

        .card-picker-overlay.active .card-picker-modal {
            transform: scale(1) translateY(0);
        }

        .card-picker-header {
            padding: 24px 28px;
            border-bottom: 1px solid var(--emph-line);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .card-picker-header h2 {
            font-size: 20px;
            font-weight: 600;
            color: var(--paper-2);
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .card-picker-header h2 i {
            color: var(--up-gold, var(--gold));
        }

        .card-picker-close {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            border: none;
            background: var(--emph-bg-2);
            color: var(--muted);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s;
        }

        .card-picker-close:hover {
            background: var(--danger);
            color: white;
        }

        .card-picker-body {
            padding: 24px 28px;
            overflow-y: auto;
            flex: 1;
        }

        .card-picker-section {
            margin-bottom: 28px;
        }

        .card-picker-section:last-child {
            margin-bottom: 0;
        }

        .card-picker-section-title {
            font-size: 13px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: var(--gold);
            margin-bottom: 16px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .card-picker-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
            gap: 16px;
        }

        .card-picker-item {
            background: var(--emph-bg-2);
            border-radius: 16px;
            padding: 20px;
            cursor: pointer;
            transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
            border: 2px solid var(--emph-line);
            position: relative;
            overflow: hidden;
        }

        .card-picker-item:hover {
            transform: translateY(-4px);
            box-shadow: 0 8px 25px rgba(0, 0, 0, 0.12);
            border-color: var(--ink-soft);
        }

        .card-picker-item.selected {
            border-color: var(--up-gold, var(--gold));
            background: var(--emph-bg-2);
            box-shadow: 0 0 20px rgba(201, 169, 98, 0.2);
        }

        .card-picker-item.selected::after {
            content: '';
            position: absolute;
            top: 12px;
            right: 12px;
            width: 24px;
            height: 24px;
            background: var(--up-gold, var(--gold));
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .card-picker-item.selected::before {
            content: '✓';
            position: absolute;
            top: 14px;
            right: 18px;
            color: white;
            font-size: 12px;
            font-weight: 700;
            z-index: 1;
        }

        .card-picker-preview {
            height: 120px;
            background: var(--emph-bg);
            border-radius: 12px;
            margin-bottom: 14px;
            position: relative;
            overflow: hidden;
            border: 1px solid var(--emph-line);
            padding: 12px;
        }

        /* Programs Preview - 3 small tiles */
        .card-picker-preview.programs {
            display: flex;
            gap: 6px;
            align-items: stretch;
            padding: 10px;
        }
        .card-picker-preview.programs .preview-tile {
            flex: 1;
            background: var(--emph-bg-2);
            border-radius: 8px;
            padding: 8px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 4px;
        }
        .card-picker-preview.programs .preview-tile i {
            width: 24px;
            height: 24px;
            border-radius: 6px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            color: white;
        }
        .card-picker-preview.programs .preview-tile:nth-child(1) i { background: var(--emph-bg); }
        .card-picker-preview.programs .preview-tile:nth-child(2) i { background: var(--gold); color: var(--ink); }
        .card-picker-preview.programs .preview-tile:nth-child(3) i { background: var(--emph-bg-2); }
        .card-picker-preview.programs .preview-tile span {
            font-size: 7px;
            color: var(--muted);
            text-align: center;
        }

        /* What's Next Preview - Action card */
        .card-picker-preview.whatsnext {
            background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%);
            display: flex;
            align-items: center;
            gap: 10px;
        }
        .card-picker-preview.whatsnext .preview-icon {
            width: 32px;
            height: 32px;
            background: var(--warning);
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            font-size: 12px;
        }
        .card-picker-preview.whatsnext .preview-content {
            flex: 1;
        }
        .card-picker-preview.whatsnext .preview-title {
            font-size: 10px;
            font-weight: 600;
            color: #92400e;
            margin-bottom: 2px;
        }
        .card-picker-preview.whatsnext .preview-subtitle {
            font-size: 7px;
            color: #b45309;
        }
        .card-picker-preview.whatsnext .preview-btn {
            background: var(--warning);
            color: white;
            border: none;
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 7px;
            font-weight: 600;
        }

        /* Events Preview - List style */
        .card-picker-preview.events {
            display: flex;
            flex-direction: column;
            gap: 6px;
            padding: 10px;
        }
        .card-picker-preview.events .preview-event {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 6px 8px;
            background: var(--up-bg-secondary, #f5f5f7);
            border-radius: 6px;
        }
        .card-picker-preview.events .preview-event-icon {
            width: 20px;
            height: 20px;
            border-radius: 5px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            color: white;
        }
        .card-picker-preview.events .preview-event:nth-child(1) .preview-event-icon { background: var(--emph-bg); }
        .card-picker-preview.events .preview-event:nth-child(2) .preview-event-icon { background: var(--gold); }
        .card-picker-preview.events .preview-event:nth-child(3) .preview-event-icon { background: #9b1b22; }
        .card-picker-preview.events .preview-event-info {
            flex: 1;
        }
        .card-picker-preview.events .preview-event-name {
            font-size: 10px;
            font-weight: 600;
            color: var(--up-text, #1d1d1f);
        }
        .card-picker-preview.events .preview-event-date {
            font-size: 6px;
            color: var(--up-text-secondary, #86868b);
        }
        .card-picker-preview.events .preview-event-badge {
            font-size: 6px;
            padding: 2px 4px;
            border-radius: 3px;
            background: #dcfce7;
            color: #166534;
        }

        /* Rewards Preview - Status bar */
        .card-picker-preview.rewards {
            background: linear-gradient(135deg, var(--emph-bg) 0%, var(--emph-bg-2) 100%);
            display: flex;
            align-items: center;
            justify-content: space-between;
        }
        .card-picker-preview.rewards .preview-tier {
            display: flex;
            align-items: center;
            gap: 6px;
        }
        .card-picker-preview.rewards .preview-tier i {
            color: var(--gold);
            font-size: 14px;
        }
        .card-picker-preview.rewards .preview-tier span {
            color: white;
            font-size: 10px;
            font-weight: 600;
        }
        .card-picker-preview.rewards .preview-points {
            text-align: right;
        }
        .card-picker-preview.rewards .preview-points-value {
            color: var(--gold);
            font-size: 14px;
            font-weight: 700;
        }
        .card-picker-preview.rewards .preview-points-label {
            color: rgba(255,255,255,0.6);
            font-size: 7px;
        }

        /* Network Preview - Avatar grid */
        .card-picker-preview.network {
            display: flex;
            flex-direction: column;
            gap: 8px;
            background: linear-gradient(135deg, #e0f2fe 0%, #bae6fd 100%);
        }
        .card-picker-preview.network .preview-avatars {
            display: flex;
            gap: -6px;
        }
        .card-picker-preview.network .preview-avatar {
            width: 28px;
            height: 28px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--ink), #38bdf8);
            border: 2px solid white;
            margin-left: -8px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            font-weight: 600;
            color: white;
        }
        .card-picker-preview.network .preview-avatar:first-child {
            margin-left: 0;
        }
        .card-picker-preview.network .preview-avatar:nth-child(2) { background: linear-gradient(135deg, var(--success), #34d399); }
        .card-picker-preview.network .preview-avatar:nth-child(3) { background: linear-gradient(135deg, var(--warning), #fbbf24); }
        .card-picker-preview.network .preview-avatar:nth-child(4) { background: linear-gradient(135deg, var(--accent), var(--accent)); }
        .card-picker-preview.network .preview-avatar.more { background: var(--up-bg-secondary, #f5f5f7); color: var(--up-text-secondary, #86868b); }
        .card-picker-preview.network .preview-text {
            font-size: 10px;
            color: var(--up-text-secondary, #86868b);
        }
        .card-picker-preview.network .preview-text strong {
            color: var(--up-text, #1d1d1f);
        }

        /* Messages Preview */
        .card-picker-preview.messages {
            display: flex;
            flex-direction: column;
            gap: 6px;
            background: linear-gradient(135deg, #eef2ff 0%, #e0e7ff 100%);
        }
        .card-picker-preview.messages .preview-msg {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 6px;
            background: var(--up-bg-secondary, #f5f5f7);
            border-radius: 6px;
        }
        .card-picker-preview.messages .preview-msg-avatar {
            width: 22px;
            height: 22px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--accent), var(--accent));
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            font-weight: 600;
            color: white;
        }
        .card-picker-preview.messages .preview-msg:nth-child(2) .preview-msg-avatar { background: linear-gradient(135deg, var(--success), #34d399); }
        .card-picker-preview.messages .preview-msg-content {
            flex: 1;
        }
        .card-picker-preview.messages .preview-msg-name {
            font-size: 10px;
            font-weight: 600;
            color: var(--up-text, #1d1d1f);
        }
        .card-picker-preview.messages .preview-msg-text {
            font-size: 7px;
            color: var(--up-text-secondary, #86868b);
        }
        .card-picker-preview.messages .preview-msg-dot {
            width: 6px;
            height: 6px;
            background: var(--accent);
            border-radius: 50%;
        }

        /* For You Preview */
        .card-picker-preview.foryou {
            background: linear-gradient(135deg, #fdf2f8 0%, #fce7f3 100%);
            display: flex;
            flex-direction: column;
            gap: 8px;
        }
        .card-picker-preview.foryou .preview-header {
            display: flex;
            align-items: center;
            gap: 6px;
        }
        .card-picker-preview.foryou .preview-header i {
            color: var(--accent);
            font-size: 10px;
        }
        .card-picker-preview.foryou .preview-header span {
            font-size: 10px;
            font-weight: 600;
            color: #9d174d;
        }
        .card-picker-preview.foryou .preview-suggestion {
            background: white;
            padding: 8px;
            border-radius: 6px;
            font-size: 10px;
            color: var(--up-text, #1d1d1f);
        }

        /* Achievements Preview */
        .card-picker-preview.achievements {
            display: flex;
            align-items: center;
            gap: 10px;
            background: linear-gradient(135deg, #fef3c7 0%, #fde68a 100%);
        }
        .card-picker-preview.achievements .preview-badges {
            display: flex;
            gap: 4px;
        }
        .card-picker-preview.achievements .preview-badge {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
        }
        .card-picker-preview.achievements .preview-badge:nth-child(1) { background: linear-gradient(135deg, #fbbf24, var(--warning)); color: white; }
        .card-picker-preview.achievements .preview-badge:nth-child(2) { background: linear-gradient(135deg, var(--accent), #9b1b22); color: white; }
        .card-picker-preview.achievements .preview-badge:nth-child(3) { background: linear-gradient(135deg, #34d399, var(--success)); color: white; }
        .card-picker-preview.achievements .preview-stats {
            flex: 1;
        }
        .card-picker-preview.achievements .preview-stat-row {
            display: flex;
            justify-content: space-between;
            margin-bottom: 4px;
        }
        .card-picker-preview.achievements .preview-stat-label {
            font-size: 7px;
            color: var(--up-text-secondary, #86868b);
        }
        .card-picker-preview.achievements .preview-stat-value {
            font-size: 10px;
            font-weight: 600;
            color: var(--up-text, #1d1d1f);
        }
        .card-picker-preview.achievements .preview-progress {
            height: 4px;
            background: var(--up-bg-secondary, #e5e5e5);
            border-radius: 2px;
            overflow: hidden;
        }
        .card-picker-preview.achievements .preview-progress-bar {
            height: 100%;
            width: 65%;
            background: linear-gradient(90deg, var(--gold), #d4b876);
            border-radius: 2px;
        }

        /* Profile Preview */
        .card-picker-preview.profile {
            display: flex;
            align-items: center;
            gap: 12px;
            background: linear-gradient(135deg, #d1fae5 0%, #a7f3d0 100%);
        }
        .card-picker-preview.profile .preview-circle {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            background: conic-gradient(var(--success) 0% 75%, #e5e5e5 75% 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
        }
        .card-picker-preview.profile .preview-circle-inner {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: var(--up-bg, white);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            font-weight: 700;
            color: var(--success);
        }
        .card-picker-preview.profile .preview-info {
            flex: 1;
        }
        .card-picker-preview.profile .preview-label {
            font-size: 10px;
            color: var(--up-text-secondary, #86868b);
            margin-bottom: 2px;
        }
        .card-picker-preview.profile .preview-title {
            font-size: 10px;
            font-weight: 600;
            color: var(--up-text, #1d1d1f);
        }

        .card-picker-name {
            font-size: 15px;
            font-weight: 600;
            color: var(--paper-2);
            margin-bottom: 6px;
        }

        .card-picker-desc {
            font-size: 12px;
            color: var(--muted);
            line-height: 1.4;
        }

        .card-picker-footer {
            padding: 20px 28px;
            border-top: 1px solid var(--emph-line);
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: var(--emph-bg);
        }

        .card-picker-count {
            font-size: 13px;
            color: var(--muted);
        }

        .card-picker-count strong {
            color: var(--up-gold, var(--gold));
        }

        .card-picker-actions {
            display: flex;
            gap: 12px;
        }

        .card-picker-btn {
            padding: 12px 24px;
            border-radius: 12px;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s;
            border: none;
        }

        .card-picker-btn.secondary {
            background: var(--up-bg, #fff);
            color: var(--up-text-secondary, #86868b);
            border: 1px solid var(--up-border, #e5e5e5);
        }

        .card-picker-btn.secondary:hover {
            background: var(--up-bg-secondary, #f5f5f7);
        }

        .card-picker-btn.primary {
            background: linear-gradient(135deg, var(--up-gold, var(--gold)) 0%, #d4b876 100%);
            color: var(--ink);
        }

        .card-picker-btn.primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 6px 20px -4px rgba(201, 169, 98, 0.5);
        }

        @media (max-width: 768px) {
            .hub-add-card-btn {
                bottom: 80px;
                right: 16px;
                width: 44px;
                height: 44px;
            }

            .card-picker-modal {
                max-height: 90vh;
                border-radius: 14px 20px 0 0;
                position: fixed;
                bottom: 0;
                left: 0;
                right: 0;
                max-width: 100%;
            }

            .card-picker-grid {
                grid-template-columns: 1fr 1fr;
            }

            .card-picker-item {
                padding: 16px;
            }

            .card-picker-preview {
                height: 70px;
            }
        }

        /* ===== Messages Panel ===== */
        .messages-panel {
            position: fixed;
            bottom: 90px;
            right: 24px;
            width: 360px;
            max-height: 480px;
            background: var(--up-bg, white);
            border-radius: 14px;
            box-shadow: 0 20px 60px -12px rgba(20,15,12, 0.25);
            z-index: 999;
            opacity: 0;
            visibility: hidden;
            transform: translateY(20px) scale(0.95);
            transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
            overflow: hidden;
        }

        .messages-panel.open {
            opacity: 1;
            visibility: visible;
            transform: translateY(0) scale(1);
        }

        .messages-panel-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 16px 20px;
            background: linear-gradient(135deg, var(--emph-bg) 0%, var(--emph-bg-2) 100%);
        }

        .messages-panel-header h4 {
            color: white;
            font-size: 15px;
            font-weight: 600;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .messages-panel-header h4 i {
            color: var(--up-gold);
        }

        .messages-panel-close {
            width: 36px;
            height: 36px;
            border-radius: 9px;
            background: rgba(255, 255, 255, 0.1);
            border: none;
            color: rgba(255, 255, 255, 0.7);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s;
        }

        .messages-panel-close:hover {
            background: rgba(255, 255, 255, 0.2);
            color: white;
        }

        .messages-panel-list {
            padding: 16px;
            max-height: 340px;
            overflow-y: auto;
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .messages-panel-all {
            width: calc(100% - 32px);
            margin: 0 16px 16px;
            padding: 14px;
            background: linear-gradient(135deg, var(--emph-bg) 0%, var(--emph-bg-2) 100%);
            border: none;
            border-radius: 12px;
            color: white;
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            transition: all 0.2s;
        }

        .messages-panel-all:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 20px -6px rgba(20,15,12, 0.3);
        }

        .messages-panel-all i {
            color: var(--up-gold);
        }

        @media (max-width: 480px) {
            .messages-panel {
                right: 16px;
                left: 16px;
                width: auto;
                bottom: 80px;
            }

            .floating-messages-btn {
                bottom: 16px;
                right: 16px;
            }
        }

        /* ===== Simple Footer - Minimal ===== */
        .hub-footer-simple {
            padding: 48px 0 32px;
            margin-top: 80px;
            border-top: 1px solid #d2d2d7;
        }

        [data-theme="dark"] .hub-footer-simple {
            border-top-color: #424245;
        }

        .hub-footer-simple-content {
            max-width: 1200px;
            margin: 0 auto;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 20px;
        }

        .hub-footer-simple-brand {
            font-size: 15px;
            font-weight: 500;
            color: #1d1d1f;
            letter-spacing: -0.01em;
        }

        .hub-footer-simple-brand span {
            color: #1d1d1f;
        }

        [data-theme="dark"] .hub-footer-simple-brand,
        [data-theme="dark"] .hub-footer-simple-brand span {
            color: #f5f5f7;
        }

        .hub-footer-simple-socials {
            display: flex;
            gap: 24px;
        }

        .hub-footer-simple-socials a {
            color: #86868b;
            font-size: 18px;
            text-decoration: none;
            transition: color 0.2s ease;
        }

        .hub-footer-simple-socials a:hover {
            color: #1d1d1f;
        }

        [data-theme="dark"] .hub-footer-simple-socials a:hover {
            color: #f5f5f7;
        }

        .hub-footer-simple-copy {
            font-size: 12px;
            color: #86868b;
        }

        .hub-footer-simple-divider {
            display: none;
        }

        /* Light card text */
        .hub-card h3, .hub-card h4, .hub-card h5 {
            color: var(--ink);
        }

        .hub-card p {
            color: var(--muted);
        }

        /* Card Sizes - 2 column grid */
        .hub-card.span-12 { grid-column: span 2; }
        .hub-card.span-6 { grid-column: span 1; }
        .hub-card.span-8,
        .hub-card.span-4,
        .hub-card.span-3 { grid-column: span 1; }

        /* More Section - Collapsible */
        .hub-more-section {
            grid-column: span 2;
            margin-top: 16px;
        }

        .hub-more-toggle {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            width: 100%;
            padding: 16px 24px;
            background: transparent;
            border: none;
            border-radius: 12px;
            color: #86868b;
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            transition: color 0.2s ease;
            font-family: inherit;
        }

        .hub-more-toggle:hover {
            color: #1d1d1f;
        }

        [data-theme="dark"] .hub-more-toggle:hover {
            color: #f5f5f7;
        }

        .hub-more-toggle i {
            transition: transform 0.2s ease;
        }

        .hub-more-toggle.expanded i {
            transform: rotate(180deg);
        }

        .hub-more-content {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 16px;
            max-height: 0;
            overflow: hidden;
            opacity: 0;
            transition: all 0.3s ease;
            margin-top: 0;
        }

        .hub-more-content.expanded {
            max-height: 500px;
            opacity: 1;
            margin-top: 16px;
        }

        @media (max-width: 768px) {
            .hub-bento {
                grid-template-columns: 1fr;
                gap: 12px;
            }
            .hub-card {
                padding: 18px;
                border-radius: 14px;
            }
            .hub-card.span-12,
            .hub-card.span-8,
            .hub-card.span-6,
            .hub-card.span-4,
            .hub-card.span-3 { grid-column: span 1; }
            .hub-more-section { grid-column: span 1; }
            .hub-more-content { grid-template-columns: 1fr; }
            .hub-container { padding: 20px 16px 120px; }
            .hub-hero-card { padding: 24px 18px; border-radius: 14px; margin-bottom: 20px; }
            .hub-updates-card { margin-bottom: 0; }
        }

        @media (max-width: 480px) {
            .hub-container { padding: 16px 12px 120px; }
            .hub-card { padding: 16px; border-radius: 18px; }
            .hub-bento { gap: 10px; }
            .hub-hero-card { padding: 20px 16px; border-radius: 18px; }
            .hub-hero-title { font-size: 22px; }
            .hub-hero-desc { font-size: 13px; }

            /* Ensure all cards fit on mobile */
            .hub-card,
            .hub-card-compact,
            .whats-next-card,
            .hub-quiz-card,
            .hub-community-card,
            .hub-progress-card {
                max-width: 100%;
                box-sizing: border-box;
                overflow: hidden;
            }

            /* Program items fit better on small screens */
            .hub-program-item {
                padding: 12px;
                gap: 10px;
            }

            .hub-program-icon {
                width: 38px;
                height: 38px;
                font-size: 16px;
            }

            .hub-program-info h4 {
                font-size: 14px;
            }

            .hub-program-info p {
                font-size: 11px;
            }

            /* What's Next card mobile adjustments */
            .next-recommendation {
                flex-direction: column;
                text-align: center;
                gap: 12px;
                padding: 12px 0;
            }

            .next-icon {
                width: 48px;
                height: 48px;
                font-size: 20px;
            }

            .next-content h4 {
                font-size: 15px;
            }

            .next-content p {
                font-size: 12px;
            }

            /* Achievement badges grid mobile */
            .badges-grid {
                grid-template-columns: repeat(auto-fill, minmax(60px, 1fr));
                gap: 10px;
            }

            .badge-icon {
                width: 44px;
                height: 44px;
                font-size: 18px;
            }

            .badge-name {
                font-size: 10px;
            }

            /* Stats card mobile */
            .hub-stats {
                gap: 16px;
            }

            .hub-stat-value {
                font-size: 28px;
            }

            .hub-stat-label {
                font-size: 11px;
            }

            /* Card headers mobile */
            .hub-card-header {
                flex-wrap: wrap;
                gap: 8px;
            }

            .hub-card-title {
                font-size: 14px;
            }

            /* Upcoming events mobile */
            .hub-event {
                padding: 10px;
            }

            .hub-event-date {
                min-width: 40px;
                padding: 6px 8px;
            }

            .hub-event-day {
                font-size: 16px;
            }

            .hub-event-month {
                font-size: 10px;
            }

            .hub-event-info h4 {
                font-size: 13px;
            }

            .hub-event-info p {
                font-size: 11px;
            }
        }

        /* Programs Card */
        .hub-programs {
            display: flex;
            flex-direction: column;
            gap: 10px;
            position: relative;
            z-index: 1;
        }

        .hub-program-item {
            display: flex;
            align-items: center;
            gap: 14px;
            padding: 14px;
            background: rgba(20,15,12, 0.02);
            border: none;
            border-radius: 14px;
            cursor: pointer;
            transition: all 0.25s ease;
        }

        .hub-program-item:hover {
            background: rgba(201, 169, 98, 0.08);
            transform: translateX(4px);
        }

        .hub-program-icon {
            width: 44px;
            height: 44px;
            border-radius: 10px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 18px;
            flex-shrink: 0;
        }

        .hub-program-icon.gold {
            background: rgba(201, 169, 98, 0.2);
            color: var(--up-gold);
        }

        .hub-program-info h4 {
            font-size: 15px;
            font-weight: 600;
            color: var(--ink);
            margin-bottom: 2px;
        }

        .hub-program-info p {
            font-size: 12px;
            color: var(--muted);
        }

        .hub-program-arrow {
            margin-left: auto;
            color: #cbd5e1;
            opacity: 0;
            transform: translateX(-8px);
            transition: all 0.2s;
        }

        .hub-program-item:hover .hub-program-arrow {
            opacity: 1;
            transform: translateX(0);
            color: var(--up-gold);
        }

        /* Stats Card */
        .hub-stats {
            display: flex;
            gap: 32px;
            position: relative;
            z-index: 1;
        }

        .hub-stat {
            flex: 1;
            text-align: center;
        }

        .hub-stat-value {
            font-size: 42px;
            font-weight: 700;
            color: var(--up-gold);
            line-height: 1;
            margin-bottom: 8px;
        }

        .hub-stat-label {
            font-size: 13px;
            color: var(--up-text-secondary, var(--muted));
        }

        /* Upcoming Card */
        .hub-upcoming {
            display: flex;
            flex-direction: column;
            gap: 12px;
            position: relative;
            z-index: 1;
        }

        .hub-event {
            display: flex;
            gap: 14px;
            padding: 14px;
            background: var(--up-bg-subtle, var(--paper));
            border: 1px solid var(--up-border, var(--line));
            border-radius: 12px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .hub-event:hover {
            background: rgba(201, 169, 98, 0.1);
            border-color: rgba(201, 169, 98, 0.3);
        }

        .hub-event-date {
            width: 48px;
            height: 48px;
            background: rgba(201, 169, 98, 0.12);
            border: none;
            border-radius: 10px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }

        .hub-event-month {
            font-size: 10px;
            font-weight: 600;
            color: var(--up-gold);
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .hub-event-day {
            font-size: 18px;
            font-weight: 700;
            color: var(--up-gold);
            line-height: 1;
        }

        .hub-event-info h4 {
            font-size: 13px;
            font-weight: 600;
            color: var(--up-text, var(--emph-bg));
            margin-bottom: 4px;
        }

        .hub-event-info p {
            font-size: 12px;
            color: var(--up-text-secondary, var(--muted));
        }

        /* Notes Card */
        .hub-notes-area {
            width: 100%;
            min-height: 140px;
            padding: 16px;
            background: rgba(20,15,12, 0.02);
            border: none;
            border-radius: 12px;
            color: var(--ink);
            font-size: 14px;
            line-height: 1.6;
            resize: none;
            font-family: inherit;
            transition: all 0.2s;
            position: relative;
            z-index: 1;
        }

        .hub-notes-area:focus {
            outline: none;
            background: rgba(201, 169, 98, 0.05);
            box-shadow: 0 0 0 2px rgba(201, 169, 98, 0.2);
        }

        .hub-notes-area::placeholder {
            color: var(--muted);
        }

        /* Quick Links Card */
        .hub-links {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 10px;
            position: relative;
            z-index: 1;
        }

        .hub-link {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 10px;
            padding: 16px 12px;
            background: rgba(20,15,12, 0.02);
            border: none;
            border-radius: 12px;
            cursor: pointer;
            transition: all 0.25s ease;
            text-align: center;
        }

        .hub-link:hover {
            background: rgba(201, 169, 98, 0.08);
            transform: translateY(-2px);
        }

        .hub-link-icon {
            width: 40px;
            height: 40px;
            border-radius: 10px;
            background: rgba(201, 169, 98, 0.12);
            color: var(--up-gold);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 16px;
        }

        .hub-link span {
            font-size: 12px;
            font-weight: 500;
            color: var(--muted);
        }

        /* Connect Card - Legacy */
        .hub-connect-cta {
            text-align: center;
            padding: 20px 0;
            position: relative;
            z-index: 1;
        }

        .hub-connect-avatars {
            display: flex;
            justify-content: center;
            margin-bottom: 20px;
        }

        .hub-connect-avatar {
            width: 44px;
            height: 44px;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.1);
            border: 2px solid rgba(20,15,12, 0.8);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 13px;
            font-weight: 600;
            color: white;
            margin-left: -10px;
        }

        .hub-connect-avatar:first-child {
            margin-left: 0;
        }

        .hub-connect-avatar.more {
            background: var(--up-gold);
            color: var(--ink);
        }

        .hub-connect-cta h3 {
            font-size: 18px;
            font-weight: 600;
            color: white;
            margin-bottom: 8px;
        }

        .hub-connect-cta p {
            font-size: 14px;
            color: rgba(255, 255, 255, 0.5);
            margin-bottom: 20px;
        }

        .hub-connect-btn {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 12px 24px;
            background: var(--up-gold);
            color: var(--ink);
            border: none;
            border-radius: 10px;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s;
        }

        .hub-connect-btn:hover {
            opacity: 0.9;
            transform: translateY(-2px);
        }

        /* Journal Feed Card */
        .hub-journal {
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        .hub-article {
            display: flex;
            gap: 16px;
            padding-bottom: 16px;
            border-bottom: 1px solid var(--up-border);
            cursor: pointer;
            transition: all 0.2s;
        }

        .hub-article:last-child {
            padding-bottom: 0;
            border-bottom: none;
        }

        .hub-article:hover {
            opacity: 0.8;
        }

        .hub-article-source {
            width: 40px;
            height: 40px;
            border-radius: 10px;
            background: rgba(255, 255, 255, 0.1);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 11px;
            font-weight: 700;
            color: rgba(255, 255, 255, 0.6);
            flex-shrink: 0;
        }

        .hub-article-source.nature { background: rgba(47, 107, 58, 0.2); color: #4ade80; }
        .hub-article-source.science { background: rgba(20,15,12, 0.2); color: var(--ink); }
        .hub-article-source.cell { background: rgba(59, 130, 246, 0.2); color: var(--accent); }

        .hub-article-content h4 {
            font-size: 13px;
            font-weight: 600;
            color: var(--up-text, var(--emph-bg));
            line-height: 1.4;
            margin-bottom: 4px;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
        }

        .hub-article-meta {
            font-size: 11px;
            color: var(--up-text-muted, var(--muted));
        }

        /* Legacy dash-member-avatar needed for other sections */
        .dash-member-avatar {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            background: var(--up-gold);
            color: var(--up-navy);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 11px;
            font-weight: 600;
        }

        .dash-new-member span {
            font-size: 13px;
            color: var(--up-text);
        }

        /* ===== Quiz Card ===== */
        .hub-quiz-card .hub-card-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .hub-quiz-card .hub-quiz-content {
            position: relative;
            z-index: 1;
        }

        .hub-quiz-streak {
            font-size: 12px;
            font-weight: 600;
            color: #fbbf24;
            display: flex;
            align-items: center;
            gap: 4px;
            background: rgba(251, 191, 36, 0.2);
            padding: 4px 10px;
            border-radius: 14px;
        }

        .hub-quiz-streak i {
            font-size: 14px;
            color: #fbbf24;
        }

        .hub-quiz-question {
            font-size: 15px;
            font-weight: 500;
            color: var(--ink);
            line-height: 1.5;
            margin-bottom: 16px;
        }

        .hub-quiz-options {
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        .hub-quiz-option {
            padding: 12px 16px;
            background: rgba(20,15,12, 0.02);
            border: none;
            border-radius: 10px;
            font-size: 13px;
            color: var(--emph-line);
            cursor: pointer;
            text-align: left;
            transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
        }

        .hub-quiz-option:hover:not(.answered) {
            background: rgba(201, 169, 98, 0.15);
            color: var(--ink);
            transform: translateX(4px);
        }

        .hub-quiz-option:active:not(.answered) {
            transform: translateX(0) scale(0.98);
            transition: all 0.1s ease;
        }

        .hub-quiz-option.correct {
            background: rgba(47, 107, 58, 0.2) !important;
            color: var(--success) !important;
            transform: scale(1.02);
            opacity: 1 !important;
            border: 2px solid var(--success) !important;
        }

        .hub-quiz-option.incorrect {
            background: rgba(239, 68, 68, 0.2) !important;
            color: var(--danger) !important;
            opacity: 1 !important;
            border: 2px solid var(--danger) !important;
        }

        .hub-quiz-option.answered {
            pointer-events: none;
            opacity: 0.6;
        }

        .hub-quiz-option.answered.correct {
            opacity: 1 !important;
        }

        .hub-quiz-result {
            margin-top: 14px;
            padding: 12px;
            border-radius: 10px;
            font-size: 13px;
            font-weight: 500;
            text-align: center;
        }

        .hub-quiz-result.correct {
            background: rgba(47, 107, 58, 0.1);
            color: var(--success);
        }

        .hub-quiz-result.incorrect {
            background: rgba(239, 68, 68, 0.1);
            color: var(--danger);
        }

        /* Quiz Progress */
        .hub-quiz-progress {
            margin-bottom: 16px;
            text-align: center;
        }

        .hub-quiz-progress span {
            font-size: 12px;
            font-weight: 600;
            color: var(--muted);
            display: block;
            margin-bottom: 8px;
        }

        .quiz-progress-bar {
            height: 4px;
            background: #e5e7eb;
            border-radius: 2px;
            overflow: hidden;
        }

        .quiz-progress-fill {
            height: 100%;
            background: linear-gradient(90deg, var(--up-gold) 0%, #d4b876 100%);
            border-radius: 2px;
            transition: width 0.5s ease;
        }

        /* Quiz Complete */
        .quiz-complete {
            text-align: center;
            padding: 24px 0;
        }

        .quiz-complete-icon {
            width: 64px;
            height: 64px;
            margin: 0 auto 16px;
            background: linear-gradient(135deg, var(--up-gold) 0%, #d4b876 100%);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 28px;
            color: var(--ink);
            animation: bounceIn 0.6s ease;
        }

        @keyframes bounceIn {
            0% { transform: scale(0); }
            50% { transform: scale(1.2); }
            100% { transform: scale(1); }
        }

        .quiz-complete h3 {
            font-size: 20px;
            font-weight: 700;
            color: var(--ink);
            margin-bottom: 8px;
        }

        .quiz-complete-score {
            font-size: 16px;
            color: var(--ink-soft);
            margin-bottom: 12px;
        }

        .quiz-complete-streak {
            display: inline-flex;
            align-items: center;
            gap: 6px;
            padding: 8px 16px;
            background: rgba(251, 146, 60, 0.1);
            border-radius: 14px;
            font-size: 14px;
            font-weight: 600;
            color: #f97316;
        }

        .quiz-complete-streak i {
            color: #f97316;
        }

        [data-theme="dark"] .quiz-complete h3 {
            color: #f5f5f7;
        }

        [data-theme="dark"] .quiz-complete-score {
            color: #a1a1aa;
        }

        [data-theme="dark"] .quiz-progress-bar {
            background: var(--emph-bg-2);
        }

        .hub-quiz-footer {
            margin-top: 16px;
            padding-top: 16px;
            border-top: 1px solid rgba(20,15,12, 0.06);
            position: relative;
            z-index: 1;
        }

        .hub-quiz-leaderboard {
            width: 100%;
            padding: 10px 16px;
            background: var(--up-bg-subtle, var(--paper));
            border: 1px solid var(--up-border, var(--line));
            border-radius: 10px;
            color: var(--up-text-secondary, var(--muted));
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            transition: all 0.2s;
        }

        .hub-quiz-leaderboard:hover {
            background: rgba(201, 169, 98, 0.08);
            border-color: rgba(201, 169, 98, 0.3);
            color: var(--up-gold);
        }

        .hub-quiz-leaderboard i {
            color: var(--warning);
        }

        /* Expandable Leaderboard Panel */
        .hub-quiz-leaderboard-panel {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1), margin 0.3s ease, opacity 0.3s ease;
            opacity: 0;
            margin-top: 0;
        }

        .hub-quiz-leaderboard-panel.expanded {
            max-height: 400px;
            opacity: 1;
            margin-top: 16px;
        }

        .hub-quiz-leaderboard-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 12px;
        }

        .hub-quiz-leaderboard-header h5 {
            font-size: 13px;
            font-weight: 600;
            color: var(--ink);
        }

        .hub-quiz-leaderboard-close {
            width: 24px;
            height: 24px;
            border-radius: 6px;
            background: rgba(20,15,12, 0.04);
            border: none;
            color: var(--muted);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            transition: all 0.2s;
        }

        .hub-quiz-leaderboard-close:hover {
            background: rgba(239, 68, 68, 0.1);
            color: var(--danger);
        }

        .hub-quiz-leaderboard-list {
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        .hub-quiz-leader-item {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 10px 12px;
            background: rgba(20,15,12, 0.02);
            border-radius: 10px;
        }

        .hub-quiz-leader-item.top-3 {
            background: rgba(201, 169, 98, 0.08);
        }

        .hub-quiz-leader-rank {
            width: 24px;
            height: 24px;
            border-radius: 50%;
            background: rgba(20,15,12, 0.06);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 11px;
            font-weight: 700;
            color: var(--muted);
        }

        .hub-quiz-leader-item.top-3 .hub-quiz-leader-rank {
            background: linear-gradient(135deg, var(--gold), #a78847);
            color: white;
        }

        .hub-quiz-leader-avatar {
            width: 32px;
            height: 32px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--muted), var(--ink-soft));
            color: white;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 11px;
            font-weight: 600;
        }

        .hub-quiz-leader-info {
            flex: 1;
        }

        .hub-quiz-leader-info h6 {
            font-size: 13px;
            font-weight: 600;
            color: var(--ink);
            margin-bottom: 2px;
        }

        .hub-quiz-leader-info span {
            font-size: 11px;
            color: var(--muted);
        }

        .hub-quiz-leader-score {
            font-size: 14px;
            font-weight: 700;
            color: var(--up-gold);
        }

        /* ===== Expandable Quiz Leaderboard ===== */
        .hub-quiz-leaderboard-expand {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.4s ease, padding 0.3s ease;
            border-top: 0 solid var(--up-border, var(--line));
        }

        .hub-quiz-leaderboard-expand.expanded {
            max-height: 400px;
            padding-top: 16px;
            border-top-width: 1px;
            margin-top: 16px;
        }

        .hub-quiz-lb-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 12px;
        }

        .hub-quiz-lb-header h4 {
            font-size: 14px;
            font-weight: 600;
            color: var(--up-text, var(--emph-bg));
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .hub-quiz-lb-header h4 i {
            color: var(--up-gold);
        }

        .hub-quiz-lb-list {
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        .hub-quiz-lb-item {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 10px 12px;
            background: var(--up-bg-subtle, var(--paper));
            border-radius: 10px;
            transition: all 0.2s;
        }

        .hub-quiz-lb-item:hover {
            background: rgba(201, 169, 98, 0.08);
        }

        .hub-quiz-lb-item.rank-1 {
            background: linear-gradient(135deg, rgba(255, 215, 0, 0.15) 0%, rgba(255, 215, 0, 0.05) 100%);
        }

        .hub-quiz-lb-item.rank-2 {
            background: linear-gradient(135deg, rgba(192, 192, 192, 0.15) 0%, rgba(192, 192, 192, 0.05) 100%);
        }

        .hub-quiz-lb-item.rank-3 {
            background: linear-gradient(135deg, rgba(205, 127, 50, 0.15) 0%, rgba(205, 127, 50, 0.05) 100%);
        }

        .lb-rank {
            width: 24px;
            height: 24px;
            border-radius: 50%;
            background: var(--up-text-muted, var(--muted));
            color: white;
            font-size: 12px;
            font-weight: 700;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .hub-quiz-lb-item.rank-1 .lb-rank {
            background: linear-gradient(135deg, #ffd700 0%, #ffb700 100%);
            color: var(--ink);
        }

        .hub-quiz-lb-item.rank-2 .lb-rank {
            background: linear-gradient(135deg, #c0c0c0 0%, #a0a0a0 100%);
            color: var(--ink);
        }

        .hub-quiz-lb-item.rank-3 .lb-rank {
            background: linear-gradient(135deg, #cd7f32 0%, #b5651d 100%);
            color: white;
        }

        .lb-avatar {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            background: var(--up-gold);
            color: var(--ink);
            font-size: 13px;
            font-weight: 600;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .lb-info {
            flex: 1;
            min-width: 0;
        }

        .lb-info h5 {
            font-size: 13px;
            font-weight: 600;
            color: var(--up-text, var(--emph-bg));
            margin-bottom: 2px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .lb-info span {
            font-size: 11px;
            color: var(--up-text-muted, var(--muted));
        }

        .lb-score {
            font-size: 13px;
            font-weight: 700;
            color: var(--up-gold);
            white-space: nowrap;
        }

        /* ===== Draggable Cards ===== */
        .draggable-card {
            cursor: grab;
            position: relative;
        }

        .draggable-card::before {
            content: '\f58e';
            font-family: 'Font Awesome 5 Free';
            font-weight: 900;
            position: absolute;
            top: 8px;
            right: 8px;
            font-size: 10px;
            color: var(--up-text-muted, var(--muted));
            opacity: 0;
            transition: opacity 0.2s;
        }

        .draggable-card:hover::before {
            opacity: 0.5;
        }

        .draggable-card.dragging {
            opacity: 0.5;
            cursor: grabbing;
            transform: scale(1.02);
            box-shadow: 0 20px 40px -10px rgba(0, 0, 0, 0.2);
        }

        .draggable-card.drag-over {
            border: 2px dashed var(--up-gold);
            background: rgba(201, 169, 98, 0.05);
        }

        .hub-bento {
            position: relative;
        }

        .drag-placeholder {
            border: 2px dashed var(--up-gold);
            border-radius: 14px;
            background: rgba(201, 169, 98, 0.05);
            min-height: 200px;
        }

        /* ===== Quick Actions Card ===== */
        .hub-quick-actions {
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        .hub-quick-btn {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 12px 14px;
            background: rgba(20,15,12, 0.02);
            border: none;
            border-radius: 12px;
            cursor: pointer;
            transition: all 0.25s ease;
        }

        .hub-quick-btn:hover {
            background: rgba(201, 169, 98, 0.08);
            transform: translateX(4px);
        }

        .hub-quick-btn i {
            width: 32px;
            height: 32px;
            border-radius: 10px;
            background: rgba(201, 169, 98, 0.12);
            color: var(--up-gold);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
        }

        .hub-quick-btn span {
            font-size: 13px;
            font-weight: 500;
            color: var(--up-text, var(--emph-bg));
        }

        /* ===== My Events Card ===== */
        .hub-my-events-list {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .hub-my-event {
            display: flex;
            align-items: center;
            gap: 14px;
            padding: 16px;
            background: rgba(20,15,12, 0.02);
            border: none;
            border-radius: 14px;
            cursor: pointer;
            transition: all 0.25s ease;
        }

        .hub-my-event:hover {
            background: rgba(201, 169, 98, 0.08);
            transform: translateX(4px);
        }

        .hub-my-event-badge {
            padding: 4px 10px;
            border-radius: 14px;
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            flex-shrink: 0;
        }

        .hub-my-event-badge.registered {
            background: rgba(47, 107, 58, 0.15);
            color: var(--success);
        }

        .hub-my-event-badge.pending {
            background: rgba(245, 158, 11, 0.15);
            color: var(--warning);
        }

        .hub-my-event-details {
            flex: 1;
            min-width: 0;
        }

        .hub-my-event-details h4 {
            font-size: 14px;
            font-weight: 600;
            color: var(--up-text, var(--emph-bg));
            margin-bottom: 4px;
        }

        .hub-my-event-details p {
            font-size: 12px;
            color: var(--up-text-muted, var(--muted));
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .hub-my-event-countdown {
            text-align: right;
            flex-shrink: 0;
        }

        .hub-my-event-countdown .countdown-value {
            font-size: 14px;
            font-weight: 600;
            color: var(--up-gold);
        }

        .hub-no-events {
            text-align: center;
            padding: 40px 20px;
            color: var(--muted);
            position: relative;
            z-index: 1;
        }

        .hub-no-events i {
            font-size: 40px;
            margin-bottom: 12px;
            color: #cbd5e1;
        }

        .hub-no-events p {
            margin-bottom: 16px;
            color: var(--muted);
        }

        .hub-no-events button {
            padding: 10px 20px;
            background: var(--up-gold);
            color: white;
            border: none;
            border-radius: 10px;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s;
        }

        .hub-no-events button:hover {
            background: #b8954d;
            transform: translateY(-2px);
        }

        /* ===== Prominent My Events Section ===== */
        .hub-my-events-prominent {
            grid-column: span 2;
        }

        .hub-events-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 16px;
            margin-bottom: 20px;
        }

        @media (max-width: 900px) {
            .hub-events-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        @media (max-width: 600px) {
            .hub-events-grid {
                grid-template-columns: 1fr;
            }
        }

        .hub-event-card {
            background: rgba(255, 255, 255, 0.6);
            backdrop-filter: blur(12px);
            -webkit-backdrop-filter: blur(12px);
            border: 1px solid rgba(255, 255, 255, 0.3);
            border-radius: 18px;
            padding: 20px;
            cursor: pointer;
            transition: all 0.3s ease;
            display: flex;
            flex-direction: column;
        }

        .hub-event-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 12px 32px rgba(0, 0, 0, 0.1);
        }

        [data-theme="dark"] .hub-event-card {
            background: rgba(30, 30, 32, 0.7);
            border-color: rgba(255, 255, 255, 0.08);
        }

        .hub-event-card-header {
            display: flex;
            justify-content: space-between;
            align-items: flex-start;
            margin-bottom: 16px;
        }

        .hub-event-icon {
            width: 44px;
            height: 44px;
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 18px;
            color: white;
        }

        .hub-event-card.plexus .hub-event-icon {
            background: linear-gradient(135deg, var(--crimson-deep) 0%, var(--accent) 100%);
        }

        .hub-event-card.gala .hub-event-icon {
            background: linear-gradient(135deg, var(--gold) 0%, #a38a4f 100%);
        }

        .hub-event-card.workshop .hub-event-icon {
            background: linear-gradient(135deg, var(--accent) 0%, #9b1b22 100%);
        }

        .hub-event-status {
            display: flex;
            align-items: center;
            gap: 5px;
            padding: 5px 10px;
            border-radius: 14px;
            font-size: 11px;
            font-weight: 600;
        }

        .hub-event-status.paid {
            background: rgba(47, 107, 58, 0.15);
            color: var(--success);
        }

        .hub-event-status.interested {
            background: rgba(201, 169, 98, 0.15);
            color: var(--up-gold, var(--gold));
        }

        .hub-event-status.pending {
            background: rgba(245, 158, 11, 0.15);
            color: var(--warning);
        }

        .hub-event-status.interest {
            background: rgba(155, 27, 34, 0.15);
            color: #9b1b22;
        }

        .hub-event-card-body {
            flex: 1;
            margin-bottom: 16px;
        }

        .hub-event-card-body h4 {
            font-size: 16px;
            font-weight: 600;
            color: var(--up-text, #1d1d1f);
            margin-bottom: 8px;
        }

        .hub-event-card-body p {
            font-size: 13px;
            color: var(--up-text-muted, #86868b);
            display: flex;
            align-items: center;
            gap: 6px;
            margin-bottom: 4px;
        }

        .hub-event-card-body p i {
            width: 14px;
            font-size: 11px;
        }

        .hub-event-card-footer {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding-top: 16px;
            border-top: 1px solid rgba(0, 0, 0, 0.05);
        }

        [data-theme="dark"] .hub-event-card-footer {
            border-top-color: rgba(255, 255, 255, 0.05);
        }

        .hub-event-countdown {
            display: flex;
            flex-direction: column;
        }

        .hub-event-countdown .countdown-num {
            font-size: 24px;
            font-weight: 700;
            color: var(--up-gold);
            line-height: 1;
        }

        .hub-event-countdown .countdown-label {
            font-size: 11px;
            color: var(--up-text-muted, #86868b);
            text-transform: uppercase;
            letter-spacing: 0.5px;
        }

        .hub-event-view-btn {
            display: flex;
            align-items: center;
            gap: 6px;
            padding: 8px 14px;
            background: transparent;
            border: 1px solid rgba(0, 0, 0, 0.1);
            border-radius: 10px;
            font-size: 12px;
            font-weight: 500;
            color: var(--up-text, #1d1d1f);
            cursor: pointer;
            transition: all 0.2s;
        }

        .hub-event-view-btn:hover {
            background: rgba(0, 0, 0, 0.05);
        }

        .hub-event-view-btn.accent {
            background: var(--up-gold);
            border-color: var(--up-gold);
            color: white;
        }

        .hub-event-view-btn.accent:hover {
            background: #b8954d;
        }

        [data-theme="dark"] .hub-event-view-btn {
            border-color: rgba(255, 255, 255, 0.1);
            color: var(--up-text);
        }

        [data-theme="dark"] .hub-event-view-btn:hover {
            background: rgba(255, 255, 255, 0.1);
        }

        .hub-events-footer {
            text-align: center;
        }

        .hub-events-browse-btn {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 12px 24px;
            background: transparent;
            border: 1px solid rgba(0, 0, 0, 0.1);
            border-radius: 12px;
            font-size: 14px;
            font-weight: 500;
            color: var(--up-text-secondary, #6e6e73);
            cursor: pointer;
            transition: all 0.2s;
        }

        .hub-events-browse-btn:hover {
            background: rgba(0, 0, 0, 0.03);
            color: var(--up-text, #1d1d1f);
        }

        [data-theme="dark"] .hub-events-browse-btn {
            border-color: rgba(255, 255, 255, 0.1);
        }

        [data-theme="dark"] .hub-events-browse-btn:hover {
            background: rgba(255, 255, 255, 0.05);
            color: var(--up-text);
        }

        /* ===== Global Community Card ===== */
        .hub-community-card .hub-card-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .hub-community-explore {
            padding: 6px 14px;
            background: rgba(201, 169, 98, 0.15);
            border: 1px solid rgba(201, 169, 98, 0.25);
            border-radius: 14px;
            color: var(--up-gold);
            font-size: 12px;
            font-weight: 500;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 6px;
            transition: all 0.2s;
        }

        .hub-community-explore:hover {
            background: rgba(201, 169, 98, 0.25);
            border-color: var(--up-gold);
        }

        .hub-community-hero {
            display: flex;
            align-items: flex-end;
            justify-content: space-between;
            padding: 20px 0;
            margin-bottom: 20px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.08);
            position: relative;
            z-index: 1;
        }

        .hub-community-stat-big .stat-value {
            display: block;
            font-size: 56px;
            font-weight: 700;
            color: var(--up-gold);
            line-height: 1;
        }

        .hub-community-stat-big .stat-label {
            font-size: 13px;
            color: rgba(255, 255, 255, 0.5);
            margin-top: 4px;
        }

        .hub-community-stat-small {
            text-align: right;
        }

        .hub-community-stat-small div {
            font-size: 13px;
            color: rgba(255, 255, 255, 0.5);
            margin-bottom: 4px;
        }

        .hub-community-stat-small div:last-child {
            margin-bottom: 0;
        }

        .hub-community-stat-small span {
            font-size: 18px;
            font-weight: 700;
            color: white;
            margin-right: 4px;
        }

        .hub-community-regions {
            display: flex;
            flex-direction: column;
            gap: 12px;
            position: relative;
            z-index: 1;
        }

        .hub-region {
            display: flex;
            flex-direction: column;
            gap: 6px;
        }

        .hub-region-info {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .hub-region-name {
            font-size: 13px;
            color: rgba(255, 255, 255, 0.7);
        }

        .hub-region-count {
            font-size: 13px;
            font-weight: 600;
            color: var(--up-gold);
        }

        .hub-region-bar {
            height: 6px;
            background: rgba(255, 255, 255, 0.08);
            border-radius: 3px;
            overflow: hidden;
        }

        .hub-region-fill {
            height: 100%;
            background: linear-gradient(90deg, var(--up-gold), #d4b978);
            border-radius: 3px;
            transition: width 0.8s ease-out;
        }

        /* ===== My Network Card ===== */
        .hub-network-card {
            background: linear-gradient(135deg, var(--emph-bg) 0%, var(--emph-bg-2) 100%) !important;
            border: none !important;
        }

        .hub-network-card .hub-card-title {
            color: white;
        }

        .hub-network-card .hub-card-action {
            color: var(--up-gold);
        }

        .hub-network-stats {
            display: flex;
            gap: 24px;
            margin-bottom: 16px;
            padding-bottom: 16px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        }

        .hub-network-stat {
            text-align: center;
        }

        .hub-network-stat .stat-num {
            display: block;
            font-size: 28px;
            font-weight: 700;
            color: var(--up-gold);
        }

        .hub-network-stat .stat-lbl {
            font-size: 12px;
            color: rgba(255, 255, 255, 0.6);
        }

        .hub-network-pending h5 {
            font-size: 12px;
            font-weight: 600;
            color: rgba(255, 255, 255, 0.5);
            text-transform: uppercase;
            letter-spacing: 0.5px;
            margin-bottom: 12px;
        }

        .hub-network-card .hub-conn-request {
            background: rgba(255, 255, 255, 0.05);
            margin-bottom: 8px;
        }

        .hub-network-card .hub-conn-info h4 {
            color: white;
        }

        .hub-network-card .hub-conn-info p {
            color: rgba(255, 255, 255, 0.5);
        }

        .hub-network-actions {
            display: flex;
            gap: 8px;
            margin-top: 12px;
        }

        .hub-network-btn {
            flex: 1;
            padding: 10px;
            background: var(--up-gold);
            border: none;
            border-radius: 8px;
            color: var(--ink);
            font-size: 12px;
            font-weight: 600;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
            transition: all 0.2s;
        }

        .hub-network-btn:hover {
            opacity: 0.9;
        }

        .hub-network-btn.secondary {
            background: rgba(255, 255, 255, 0.1);
            color: white;
        }

        .hub-network-btn.secondary:hover {
            background: rgba(255, 255, 255, 0.2);
        }

        .hub-conn-request {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 12px;
            background: var(--up-bg-subtle);
            border-radius: 12px;
        }

        .hub-conn-avatar {
            width: 38px;
            height: 38px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--up-gold) 0%, #a78847 100%);
            color: white;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            font-weight: 600;
            flex-shrink: 0;
        }

        .hub-conn-info {
            flex: 1;
            min-width: 0;
        }

        .hub-conn-info h4 {
            font-size: 13px;
            font-weight: 600;
            color: var(--up-text);
            margin-bottom: 2px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .hub-conn-info p {
            font-size: 11px;
            color: var(--up-text-muted);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .hub-conn-actions {
            display: flex;
            gap: 6px;
        }

        .hub-conn-accept,
        .hub-conn-decline {
            width: 36px;
            height: 36px;
            border-radius: 8px;
            border: none;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            transition: all 0.2s;
        }

        .hub-conn-accept {
            background: rgba(47, 107, 58, 0.2);
            color: var(--success);
        }

        .hub-conn-accept:hover {
            background: var(--success);
            color: white;
        }

        .hub-conn-decline {
            background: rgba(255, 255, 255, 0.1);
            color: rgba(255, 255, 255, 0.5);
        }

        .hub-conn-decline:hover {
            background: var(--danger);
            color: white;
        }

        /* ===== Messages Card ===== */
        .hub-messages-card .hub-card-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .hub-msg-badge {
            font-size: 11px;
            font-weight: 600;
            color: white;
            background: var(--danger);
            padding: 4px 10px;
            border-radius: 12px;
        }

        .hub-messages-list {
            display: flex;
            flex-direction: column;
            gap: 8px;
            margin-bottom: 12px;
        }

        .hub-message-item {
            display: flex;
            gap: 12px;
            padding: 12px;
            background: var(--up-bg-subtle, var(--paper));
            border: 1px solid var(--up-border, var(--line));
            border-radius: 12px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .hub-message-item:hover {
            background: rgba(201, 169, 98, 0.1);
            border-color: rgba(201, 169, 98, 0.3);
        }

        .hub-message-item.unread {
            background: rgba(201, 169, 98, 0.08);
            border-left: 3px solid var(--up-gold);
        }

        .hub-msg-avatar {
            width: 38px;
            height: 38px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--muted) 0%, var(--ink-soft) 100%);
            color: white;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            font-weight: 600;
            flex-shrink: 0;
        }

        .hub-msg-content {
            flex: 1;
            min-width: 0;
        }

        .hub-msg-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 4px;
        }

        .hub-msg-header h4 {
            font-size: 13px;
            font-weight: 600;
            color: var(--up-text, var(--emph-bg));
        }

        .hub-msg-header span {
            font-size: 11px;
            color: var(--up-text-muted, var(--muted));
        }

        .hub-msg-content p {
            font-size: 12px;
            color: var(--up-text-secondary, var(--muted));
            line-height: 1.4;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
