            box-shadow: 0 4px 12px rgba(201, 169, 98, 0.3);
        }

        .badge-item.locked .badge-icon {
            background: var(--paper-2);
            color: #cbd5e1;
            position: relative;
        }

        .badge-item.locked .badge-icon::after {
            content: '\f023';
            font-family: 'Font Awesome 6 Free';
            font-weight: 900;
            position: absolute;
            bottom: -4px;
            right: -4px;
