        .badge-name {
            font-size: 10px;
            font-weight: 500;
            color: var(--muted);
            text-align: center;
            line-height: 1.3;
        }

        .badge-item.earned .badge-name {
            color: var(--ink);
        }

        .badge-progress {
            width: 100%;
            height: 3px;
            background: #e5e7eb;
            border-radius: 2px;
            overflow: hidden;
            margin-top: 4px;
