        .view-all-badges-btn:hover {
            background: rgba(201, 169, 98, 0.2);
            transform: translateY(-2px);
        }

        /* Dark mode for badges */
        [data-theme="dark"] .badge-item.locked .badge-icon {
            background: var(--emph-bg-2);
            color: #4a4a4c;
        }

        [data-theme="dark"] .badge-name {
