        .px-city-hero {
            background: linear-gradient(135deg, rgba(20,15,12, 0.9) 0%, rgba(30, 58, 95, 0.9) 100%),
                        url('https://images.unsplash.com/photo-1555990538-1e7b53d2d6e6?w=1200') center/cover;
            border-radius: 16px;
            padding: 48px;
            text-align: center;
            color: white;
            margin-bottom: 32px;
