            background: var(--up-bg);
            border: 1px solid var(--up-border);
            border-radius: 16px;
            overflow: hidden;
            transition: all 0.3s ease;
        }

        .px-city-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 12px 32px rgba(0, 0, 0, 0.12);
        }

        .px-city-card-image {
