            color: var(--up-gold);
        }

        /* Live Header */
        .px-live-header {
            background: linear-gradient(135deg, var(--emph-bg) 0%, var(--emph-bg-2) 100%);
            border-radius: 14px;
            padding: 32px;
            text-align: center;
            margin-bottom: 24px;
            border: 1px solid rgba(47, 107, 58, 0.3);
        }

        .px-live-badge {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 8px 16px;
            background: rgba(47, 107, 58, 0.2);
