        .px-live-header p {
            font-size: 14px;
            color: rgba(255, 255, 255, 0.6);
        }

        /* Day Toggle */
        .px-live-day-toggle {
            display: flex;
            gap: 8px;
        }

        .px-day-btn {
            padding: 8px 16px;
            font-size: 13px;
            font-weight: 500;
            background: var(--up-bg-subtle);
            border: none;
            border-radius: 8px;
            color: var(--up-text-muted);
            cursor: pointer;
            transition: all 0.2s;
            font-family: inherit;
        }

        .px-day-btn.active {
            background: var(--up-gold);
            color: var(--ink);
        }

        /* Live Schedule */
        .px-live-schedule {
            display: flex;
            flex-direction: column;
        }

        .px-live-session {
            display: flex;
            gap: 16px;
            padding: 16px 0;
            border-bottom: 1px solid var(--up-border);
        }

        .px-live-session:last-child {
            border-bottom: none;
        }

        .px-session-time {
            font-size: 14px;
            font-weight: 600;
            color: var(--up-text-muted);
            width: 50px;
            flex-shrink: 0;
        }

        .px-session-content {
            display: flex;
            gap: 12px;
            flex: 1;
        }

        .px-session-status {
            width: 32px;
            height: 32px;
            border-radius: 8px;
            background: var(--up-bg-subtle);
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--up-text-muted);
            font-size: 12px;
            flex-shrink: 0;
        }

        .px-session-status.completed {
            background: rgba(47, 107, 58, 0.15);
            color: var(--success);
        }

        .px-session-status.live {
            background: rgba(239, 68, 68, 0.15);
            color: var(--danger);
            animation: livePulse 1.5s infinite;
        }

        .px-session-info h4 {
            font-size: 14px;
            font-weight: 600;
            color: var(--up-text);
            margin-bottom: 4px;
        }

        .px-session-info p {
