            border-radius: 14px;
            padding: 32px;
            display: flex;
            align-items: flex-start;
            gap: 24px;
        }

        .px-contact-icon,
        .ax-contact-icon {
            width: 56px;
            height: 56px;
            background: linear-gradient(135deg, var(--gold) 0%, #b49650 100%);
            border-radius: 16px;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }

        .px-contact-icon i,
        .ax-contact-icon i {
