            height: 32px;
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 16px;
        }

        .calendar-option-icon.google {
            background: #4285f4;
            color: #fff;
        }

        .calendar-option-icon.apple {
            background: #333;
            color: #fff;
        }

        .calendar-option-icon.outlook {
            background: #0078d4;
            color: #fff;
        }

        .calendar-option-icon.ics {
