        .certificate-card {
            background: linear-gradient(135deg, var(--emph-bg-2), var(--emph-line));
            border: 2px solid var(--up-gold);
            border-radius: 16px;
            padding: 24px;
            display: flex;
            align-items: center;
            gap: 20px;
        }

        .certificate-preview {
            width: 120px;
            height: 80px;
            background: #fff;
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
        }

        .certificate-preview i {
            font-size: 32px;
            color: var(--up-gold);
        }

        .certificate-info {
            flex: 1;
        }

        .certificate-info h4 {
            font-size: 16px;
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 4px;
        }

        .certificate-info p {
            font-size: 13px;
            color: var(--text-secondary);
        }

        .certificate-download-btn {
            padding: 12px 24px;
            background: var(--up-gold);
            color: #000;
            border: none;
            border-radius: 8px;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 8px;
            transition: all 0.2s;
        }

        .certificate-download-btn:hover {
            background: #d4b876;
            transform: scale(1.02);
        }

        /* Attendee Count Badge */
        .attendee-count {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 8px 14px;
            background: var(--bg-tertiary);
            border-radius: 14px;
            font-size: 13px;
            color: var(--text-secondary);
        }

        .attendee-count i {
            color: var(--up-gold);
        }

        .attendee-count.live {
            background: rgba(239, 68, 68, 0.15);
            color: #fff;
        }

        .attendee-count.live i {
            color: var(--danger);
        }

        /* Responsive */
        @media (max-width: 768px) {
            .my-schedule-container {
                flex-direction: column;
            }

            .schedule-sidebar {
                width: 100%;
            }

            .certificate-card {
                flex-direction: column;
                text-align: center;
            }

            .live-event-banner {
                flex-direction: column;
                text-align: center;
            }
        }


        /* Smart Networking Hub */
        .networking-hub {
            padding: 0;
        }

        .networking-tabs {
            display: flex;
            gap: 4px;
            padding: 16px 20px;
            border-bottom: 1px solid var(--border);
            background: var(--bg-secondary);
            overflow-x: auto;
        }

        .networking-tab {
            padding: 8px 16px;
            border-radius: 14px;
            background: transparent;
            border: 1px solid var(--border);
            color: var(--text-secondary);
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s;
            white-space: nowrap;
        }

        .networking-tab:hover {
            background: var(--bg-tertiary);
            color: var(--text-primary);
        }

        .networking-tab.active {
            background: var(--up-gold);
            border-color: var(--up-gold);
            color: #000;
        }

        .networking-tab .tab-count {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            min-width: 18px;
            height: 18px;
            padding: 0 6px;
            margin-left: 6px;
            border-radius: 9px;
            background: rgba(255,255,255,0.2);
            font-size: 11px;
        }

        .networking-tab.active .tab-count {
            background: rgba(0,0,0,0.2);
        }

        .networking-content {
            padding: 20px;
        }

        /* People Suggestions Grid */
        .people-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
            gap: 16px;
        }

        .person-card {
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 16px;
            padding: 20px;
            transition: all 0.2s;
            position: relative;
        }

        .person-card:hover {
            border-color: var(--up-gold);
            transform: translateY(-2px);
            box-shadow: 0 8px 24px rgba(0,0,0,0.2);
        }

        .person-card-header {
            display: flex;
            gap: 12px;
            margin-bottom: 12px;
        }

        .person-avatar {
            width: 56px;
            height: 56px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--up-gold), #d4b876);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 20px;
            font-weight: 600;
            color: #000;
            flex-shrink: 0;
        }

        .person-avatar img {
            width: 100%;
            height: 100%;
            border-radius: 50%;
            object-fit: cover;
        }

        .person-info {
            flex: 1;
            min-width: 0;
        }

        .person-name {
            font-size: 16px;
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 2px;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .person-verified {
            color: var(--up-gold);
            font-size: 12px;
        }

        .person-title {
            font-size: 13px;
            color: var(--text-secondary);
            margin-bottom: 4px;
        }

        .person-location {
            font-size: 12px;
            color: var(--text-muted);
            display: flex;
            align-items: center;
            gap: 4px;
        }

        .person-match {
            position: absolute;
            top: 12px;
            right: 12px;
            background: rgba(201, 169, 98, 0.15);
            color: var(--up-gold);
            padding: 4px 10px;
            border-radius: 12px;
            font-size: 11px;
            font-weight: 600;
        }

        .person-tags {
            display: flex;
            flex-wrap: wrap;
            gap: 6px;
            margin-bottom: 12px;
        }

        .person-tag {
            padding: 4px 10px;
            background: var(--bg-tertiary);
            border-radius: 12px;
            font-size: 11px;
            color: var(--text-secondary);
        }

        .person-tag.shared {
            background: rgba(47, 107, 58, 0.15);
            color: var(--success);
        }

        .person-mutual {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 10px 0;
            border-top: 1px solid var(--border);
            margin-top: 12px;
        }

        .mutual-avatars {
            display: flex;
        }

        .mutual-avatar {
            width: 24px;
            height: 24px;
            border-radius: 50%;
            background: var(--bg-tertiary);
            border: 2px solid var(--bg-secondary);
            margin-left: -8px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            color: var(--text-secondary);
        }

        .mutual-avatar:first-child {
            margin-left: 0;
        }

        .mutual-text {
            font-size: 12px;
            color: var(--text-muted);
        }

        .person-actions {
            display: flex;
            gap: 8px;
            margin-top: 12px;
        }

        .person-action {
            flex: 1;
            padding: 10px;
            border-radius: 8px;
            border: none;
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
        }

        .person-action.primary {
            background: var(--up-gold);
            color: #000;
        }

        .person-action.primary:hover {
            background: #d4b876;
        }

        .person-action.secondary {
            background: var(--bg-tertiary);
            color: var(--text-primary);
        }

        .person-action.secondary:hover {
            background: var(--bg-hover);
        }

        .person-action.connected {
            background: rgba(47, 107, 58, 0.15);
            color: var(--success);
        }

        /* Connection Requests */
        .requests-list {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }

        .request-card {
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 16px;
            display: flex;
            align-items: flex-start;
            gap: 12px;
        }

        .request-card.new {
            border-color: var(--up-gold);
            background: rgba(201, 169, 98, 0.05);
        }

        .request-content {
            flex: 1;
        }

        .request-header {
            display: flex;
            align-items: center;
            gap: 8px;
            margin-bottom: 4px;
        }

        .request-name {
            font-weight: 600;
            color: var(--text-primary);
        }

        .request-time {
            font-size: 12px;
            color: var(--text-muted);
        }

        .request-message {
            font-size: 13px;
            color: var(--text-secondary);
            margin-bottom: 12px;
            padding: 10px;
            background: var(--bg-tertiary);
            border-radius: 8px;
            font-style: italic;
        }

        .request-actions {
            display: flex;
            gap: 8px;
        }

        .request-action {
            padding: 8px 16px;
            border-radius: 6px;
            border: none;
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s;
        }

        .request-action.accept {
            background: var(--up-gold);
            color: #000;
        }

        .request-action.decline {
            background: var(--bg-tertiary);
            color: var(--text-secondary);
        }

        /* Community Activity Feed */
        .activity-feed {
            display: flex;
            flex-direction: column;
            gap: 16px;
        }

        .activity-item {
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 12px;
            padding: 16px;
            transition: all 0.2s;
        }

        .activity-item:hover {
            border-color: var(--border-light);
        }

        .activity-header {
            display: flex;
            align-items: center;
            gap: 12px;
            margin-bottom: 12px;
        }

        .activity-avatar {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--up-gold), #d4b876);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            font-weight: 600;
            color: #000;
        }

        .activity-meta {
            flex: 1;
        }

        .activity-author {
            font-weight: 600;
            color: var(--text-primary);
            cursor: pointer;
        }

        .activity-author:hover {
            color: var(--up-gold);
        }

        .activity-action {
            font-size: 13px;
            color: var(--text-secondary);
        }

        .activity-time {
            font-size: 12px;
            color: var(--text-muted);
        }

        .activity-body {
            margin-bottom: 12px;
        }

        .activity-text {
            font-size: 14px;
            color: var(--text-primary);
            line-height: 1.5;
        }

        .activity-attachment {
            margin-top: 12px;
            padding: 12px;
            background: var(--bg-tertiary);
            border-radius: 8px;
            display: flex;
            align-items: center;
            gap: 12px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .activity-attachment:hover {
            background: var(--bg-hover);
        }

        .activity-attachment-icon {
            width: 40px;
            height: 40px;
            border-radius: 8px;
            background: rgba(201, 169, 98, 0.15);
            color: var(--up-gold);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 16px;
        }

        .activity-attachment-info h5 {
            font-size: 13px;
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 2px;
        }

        .activity-attachment-info p {
            font-size: 12px;
            color: var(--text-muted);
        }

        .activity-footer {
            display: flex;
            align-items: center;
            gap: 16px;
            padding-top: 12px;
            border-top: 1px solid var(--border);
        }

        .activity-stat {
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: 13px;
            color: var(--text-muted);
            cursor: pointer;
            padding: 6px 10px;
            border-radius: 6px;
            transition: all 0.2s;
        }

        .activity-stat:hover {
            background: var(--bg-tertiary);
            color: var(--text-primary);
        }

        .activity-stat.liked {
            color: var(--danger);
        }

        .activity-stat.liked i {
            animation: heartPop 0.3s ease;
        }

        @keyframes heartPop {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.3); }
        }

        /* Member Profile Panel */
        .member-profile-panel {
            position: fixed;
            top: 0;
            right: 0;
            width: 100%;
            max-width: 480px;
            transform: translateX(100%);
            height: 100vh;
            background: var(--bg-primary);
            border-left: 1px solid var(--border);
            z-index: 10000;
            transition: transform 0.3s ease;
            overflow-y: auto;
            box-shadow: -8px 0 32px rgba(0,0,0,0.3);
        }

        .member-profile-panel.active {
            transform: translateX(0);
        }

        .member-profile-backdrop {
            position: fixed;
            inset: 0;
            background: rgba(0,0,0,0.5);
            z-index: 9999;
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s;
        }

        .member-profile-backdrop.active {
            opacity: 1;
            visibility: visible;
        }

        .profile-panel-header {
            position: relative;
            padding: 60px 24px 24px;
            background: linear-gradient(135deg, var(--bg-secondary), var(--bg-tertiary));
            text-align: center;
        }

        .profile-panel-close {
            position: absolute;
            top: 16px;
            right: 16px;
            width: 36px;
            height: 36px;
            border-radius: 50%;
            background: var(--bg-tertiary);
            border: none;
            color: var(--text-secondary);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s;
        }

        .profile-panel-close:hover {
            background: var(--bg-hover);
            color: var(--text-primary);
        }

        .profile-panel-avatar {
            width: 100px;
            height: 100px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--up-gold), #d4b876);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 36px;
            font-weight: 600;
            color: #000;
            margin: 0 auto 16px;
            border: 4px solid var(--bg-primary);
        }

        .profile-panel-name {
            font-size: 24px;
            font-weight: 700;
            color: var(--text-primary);
            margin-bottom: 4px;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
        }

        .profile-panel-title {
            font-size: 14px;
            color: var(--text-secondary);
            margin-bottom: 8px;
        }

        .profile-panel-location {
            font-size: 13px;
            color: var(--text-muted);
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 6px;
        }

        .profile-panel-stats {
            display: flex;
            justify-content: center;
            gap: 32px;
            margin-top: 20px;
            padding-top: 20px;
            border-top: 1px solid var(--border);
        }

        .profile-stat {
            text-align: center;
        }

        .profile-stat-value {
            font-size: 20px;
            font-weight: 700;
            color: var(--text-primary);
        }

        .profile-stat-label {
            font-size: 12px;
            color: var(--text-muted);
        }

        .profile-panel-actions {
            display: flex;
            gap: 12px;
            padding: 20px 24px;
            border-bottom: 1px solid var(--border);
        }

        .profile-panel-action {
            flex: 1;
            padding: 12px;
            border-radius: 8px;
            border: none;
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s;
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
        }

        .profile-panel-action.primary {
            background: var(--up-gold);
            color: #000;
        }

        .profile-panel-action.secondary {
            background: var(--bg-tertiary);
            color: var(--text-primary);
        }

        .profile-panel-section {
            padding: 20px 24px;
            border-bottom: 1px solid var(--border);
        }

        .profile-panel-section h4 {
            font-size: 12px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            color: var(--text-muted);
            margin-bottom: 12px;
        }

        .profile-bio {
            font-size: 14px;
            color: var(--text-secondary);
            line-height: 1.6;
        }

        .profile-interests {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
        }

        .profile-interest {
            padding: 6px 12px;
            background: var(--bg-tertiary);
            border-radius: 16px;
            font-size: 12px;
            color: var(--text-secondary);
        }

        .profile-interest.match {
            background: rgba(201, 169, 98, 0.15);
            color: var(--up-gold);
        }

        .profile-achievements {
            display: flex;
            gap: 12px;
            overflow-x: auto;
            padding-bottom: 8px;
        }

        .profile-achievement {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 6px;
            padding: 12px;
            background: var(--bg-tertiary);
            border-radius: 12px;
            min-width: 80px;
        }

        .profile-achievement i {
            font-size: 20px;
            color: var(--up-gold);
        }

        .profile-achievement span {
            font-size: 11px;
            color: var(--text-muted);
            text-align: center;
        }

        .profile-shared-connections {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
        }

        .shared-connection {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 8px 12px;
            background: var(--bg-tertiary);
            border-radius: 14px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .shared-connection:hover {
            background: var(--bg-hover);
        }

        .shared-connection-avatar {
            width: 24px;
            height: 24px;
            border-radius: 50%;
            background: var(--up-gold);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            color: #000;
        }

        .shared-connection-name {
            font-size: 12px;
            color: var(--text-primary);
        }

        /* Networking Events */
        .events-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
            gap: 16px;
        }

        .network-event-card {
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 16px;
            overflow: hidden;
            transition: all 0.2s;
        }

        .network-event-card:hover {
            border-color: var(--up-gold);
            transform: translateY(-2px);
        }

        .event-card-banner {
            height: 100px;
            background: linear-gradient(135deg, var(--up-gold), #d4b876);
            display: flex;
            align-items: center;
            justify-content: center;
            position: relative;
        }

        .event-card-banner i {
            font-size: 32px;
            color: rgba(0,0,0,0.3);
        }

        .event-card-type {
            position: absolute;
            top: 12px;
            left: 12px;
            padding: 4px 10px;
            background: rgba(0,0,0,0.3);
            border-radius: 12px;
            font-size: 11px;
            font-weight: 500;
            color: #fff;
        }

        .event-card-body {
            padding: 16px;
        }

        .event-card-date {
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: 12px;
            color: var(--up-gold);
            margin-bottom: 8px;
        }

        .event-card-title {
            font-size: 16px;
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 6px;
        }

        .event-card-desc {
            font-size: 13px;
            color: var(--text-secondary);
            margin-bottom: 12px;
            line-height: 1.5;
        }

        .event-card-attendees {
            display: flex;
            align-items: center;
            gap: 8px;
            margin-bottom: 16px;
        }

        .event-attendee-avatars {
            display: flex;
        }

        .event-attendee-avatar {
            width: 28px;
            height: 28px;
            border-radius: 50%;
            background: var(--bg-tertiary);
            border: 2px solid var(--bg-secondary);
            margin-left: -8px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 10px;
            color: var(--text-secondary);
        }

        .event-attendee-avatar:first-child {
            margin-left: 0;
        }

        .event-attendee-count {
            font-size: 12px;
            color: var(--text-muted);
        }

        .event-card-action {
            width: 100%;
            padding: 12px;
            border-radius: 8px;
            border: none;
            background: var(--up-gold);
            color: #000;
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s;
        }

        .event-card-action:hover {
            background: #d4b876;
        }

        .event-card-action.joined {
            background: rgba(47, 107, 58, 0.15);
            color: var(--success);
        }

        /* Virtual Coffee Matching */
        .coffee-match-banner {
            background: linear-gradient(135deg, #9b1b22, var(--accent));
            border-radius: 16px;
            padding: 24px;
            display: flex;
            align-items: center;
            gap: 20px;
            margin-bottom: 20px;
        }

        .coffee-match-icon {
            width: 64px;
            height: 64px;
            background: rgba(255,255,255,0.2);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 28px;
        }

        .coffee-match-content {
            flex: 1;
        }

        .coffee-match-content h3 {
            font-size: 18px;
            font-weight: 600;
            color: #fff;
            margin-bottom: 4px;
        }

        .coffee-match-content p {
            font-size: 13px;
            color: rgba(255,255,255,0.8);
        }

        .coffee-match-btn {
            padding: 12px 24px;
            background: #fff;
            color: #9b1b22;
            border: none;
            border-radius: 8px;
            font-size: 14px;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s;
        }

        .coffee-match-btn:hover {
            transform: scale(1.05);
        }

        /* Connection Request Modal */
        .connect-modal {
            position: fixed;
            inset: 0;
            background: rgba(0,0,0,0.6);
            backdrop-filter: blur(4px);
            z-index: 100001;
            display: flex;
            align-items: center;
            justify-content: center;
            opacity: 0;
            visibility: hidden;
            transition: all 0.3s;
        }

        .connect-modal.active {
            opacity: 1;
            visibility: visible;
        }

        .connect-modal-content {
            background: var(--bg-secondary);
            border: 1px solid var(--border);
            border-radius: 16px;
            width: 100%;
            max-width: 440px;
            padding: 24px;
            margin: 20px;
        }

        .connect-modal-header {
            display: flex;
            align-items: center;
            gap: 12px;
            margin-bottom: 20px;
        }

        .connect-modal-avatar {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--up-gold), #d4b876);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 18px;
            font-weight: 600;
            color: #000;
        }

        .connect-modal-info h3 {
            font-size: 16px;
            font-weight: 600;
            color: var(--text-primary);
        }

        .connect-modal-info p {
            font-size: 13px;
            color: var(--text-secondary);
        }

        .connect-modal-body {
            margin-bottom: 20px;
        }

        .connect-modal-body label {
            display: block;
            font-size: 13px;
            font-weight: 500;
            color: var(--text-secondary);
            margin-bottom: 8px;
        }

        .connect-modal-body textarea {
            width: 100%;
            padding: 12px;
            background: var(--bg-tertiary);
            border: 1px solid var(--border);
            border-radius: 8px;
            color: var(--text-primary);
            font-size: 14px;
            font-family: inherit;
            resize: vertical;
            min-height: 100px;
        }

        .connect-modal-body textarea:focus {
            outline: none;
            border-color: var(--up-gold);
        }

        .connect-modal-footer {
            display: flex;
            gap: 12px;
        }

        .connect-modal-btn {
            flex: 1;
            padding: 12px;
            border-radius: 8px;
            border: none;
            font-size: 14px;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.2s;
        }

        .connect-modal-btn.cancel {
            background: var(--bg-tertiary);
            color: var(--text-secondary);
        }

        .connect-modal-btn.send {
            background: var(--up-gold);
            color: #000;
        }

        /* Empty States */
        .networking-empty {
            text-align: center;
            padding: 60px 20px;
        }

        .networking-empty i {
            font-size: 48px;
            color: var(--text-muted);
            margin-bottom: 16px;
        }

        .networking-empty h3 {
            font-size: 18px;
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 8px;
        }

        .networking-empty p {
            font-size: 14px;
            color: var(--text-secondary);
            margin-bottom: 20px;
        }

        /* Responsive */
        @media (max-width: 768px) {
            .member-profile-panel {
                max-width: 100%;
            }

            .people-grid {
                grid-template-columns: 1fr;
            }

            .events-grid {
                grid-template-columns: 1fr;
            }

            .coffee-match-banner {
                flex-direction: column;
                text-align: center;
            }
        }


        /* Confetti Animations */
        @keyframes confettiFall {
            0% { transform: translateY(0) rotate(0deg); opacity: 1; }
            100% { transform: translateY(300px) rotate(720deg); opacity: 0; }
        }

        @keyframes confettiExplode {
            0% { transform: scale(0) translate(0, 0); opacity: 1; }
            100% { transform: scale(1) translate(var(--tx, 50px), var(--ty, -100px)); opacity: 0; }
        }

/* ===== WELCOME TOUR ===== */
.welcome-tour-overlay {
    position: fixed;
    inset: 0;
    z-index: 100000;
    display: none;
    background: var(--emph-bg);
}
.welcome-tour-overlay.active { display: block; }
.welcome-tour-step { display: none; position: absolute; inset: 0; overflow-y: auto; -webkit-overflow-scrolling: touch; }
.welcome-tour-step.active { display: flex; align-items: center; justify-content: center; z-index: 1; animation: wtEnter 0.55s cubic-bezier(0.22, 0.61, 0.36, 1); }
.welcome-tour-step.wt-leaving { display: flex; align-items: center; justify-content: center; z-index: 0; pointer-events: none; animation: wtLeave 0.45s cubic-bezier(0.4, 0, 0.2, 1) forwards; }
@keyframes wtFadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes wtEnter { from { opacity: 0; transform: scale(0.99); } to { opacity: 1; transform: scale(1); } }
@keyframes wtLeave { from { opacity: 1; transform: scale(1); } to { opacity: 0; transform: scale(0.985); } }
@media (prefers-reduced-motion: reduce) { .welcome-tour-step.active, .welcome-tour-step.wt-leaving { animation: wtFadeIn 0.2s ease; } }

/* Step 0: Welcome Splash */
.welcome-splash { position: relative; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; overflow: hidden; }
.welcome-splash-bg { position: absolute; inset: 0; background: linear-gradient(135deg, var(--emph-bg) 0%, #1a1a2e 50%, var(--emph-bg) 100%); }
.splash-orb { position: absolute; border-radius: 50%; filter: blur(80px); opacity: 0.4; animation: orbFloat 8s ease-in-out infinite; }
.splash-orb-1 { width: 400px; height: 400px; background: radial-gradient(circle, var(--gold), transparent); top: -100px; right: -100px; animation-delay: 0s; }
.splash-orb-2 { width: 300px; height: 300px; background: radial-gradient(circle, var(--accent), transparent); bottom: -50px; left: -50px; animation-delay: 2s; }
.splash-orb-3 { width: 250px; height: 250px; background: radial-gradient(circle, var(--accent), transparent); top: 50%; left: 50%; transform: translate(-50%, -50%); animation-delay: 4s; }
@keyframes orbFloat { 0%, 100% { transform: translate(0, 0) scale(1); } 50% { transform: translate(20px, -20px) scale(1.1); } }
.splash-particles { position: absolute; inset: 0; pointer-events: none; }
.splash-particle { position: absolute; width: 4px; height: 4px; background: rgba(201, 169, 98, 0.6); border-radius: 50%; animation: particleFloat 10s linear infinite; }
@keyframes particleFloat { 0% { transform: translateY(100vh) rotate(0deg); opacity: 0; } 10% { opacity: 1; } 90% { opacity: 1; } 100% { transform: translateY(-100px) rotate(720deg); opacity: 0; } }
.welcome-splash-content { position: relative; z-index: 1; text-align: center; padding: 40px; }
.welcome-logo-anim { margin-bottom: 32px; animation: logoReveal 1s ease forwards; }
.welcome-logo-img { height: 80px; width: auto; object-fit: contain; filter: brightness(0) invert(1) drop-shadow(0 4px 20px rgba(201, 169, 98, 0.4)); }
.logo-med { color: #fff; }
.logo-amp { color: var(--crimson); display: inline-block; }
.logo-x { color: #fff; }
@keyframes logoReveal { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
.welcome-splash-title { font-size: 56px; font-weight: 700; color: #fff; margin: 0 0 16px 0; animation: titleSlide 0.8s ease 0.3s forwards; opacity: 0; transform: translateY(20px); }
/* comma is added by JS when setting welcomeUserName */
@keyframes titleSlide { to { opacity: 1; transform: translateY(0); } }
.welcome-splash-subtitle { font-size: 20px; color: rgba(255, 255, 255, 0.6); margin: 0 0 48px 0; animation: subtitleFade 0.8s ease 0.5s forwards; opacity: 0; }
@keyframes subtitleFade { to { opacity: 1; } }
.welcome-splash-btn { display: inline-flex; align-items: center; gap: 12px; padding: 18px 40px; background: linear-gradient(135deg, var(--gold), #b8943d); color: var(--emph-bg); font-size: 18px; font-weight: 700; border: none; border-radius: 16px; cursor: pointer; transition: all 0.3s ease; animation: btnBounce 0.8s ease 0.7s forwards; opacity: 0; transform: translateY(20px); }
.welcome-splash-btn:hover { transform: translateY(-4px) scale(1.02); box-shadow: 0 20px 40px rgba(201, 169, 98, 0.4); }
@keyframes btnBounce { to { opacity: 1; transform: translateY(0); } }

/* Tour Container & Progress */
.welcome-tour-container { width: 100%; max-width: 580px; padding: 24px; animation: cardSlideUp 0.5s ease; max-height: 100vh; overflow-y: auto; -webkit-overflow-scrolling: touch; }
@keyframes cardSlideUp { from { opacity: 0; transform: translateY(40px); } to { opacity: 1; transform: translateY(0); } }
.welcome-tour-progress { margin-bottom: 24px; }
.wt-progress-bar { height: 4px; background: rgba(255, 255, 255, 0.1); border-radius: 2px; overflow: hidden; margin-bottom: 8px; }
.wt-progress-fill { height: 100%; background: linear-gradient(90deg, var(--gold), #daa520); border-radius: 2px; transition: width 0.5s ease; }
.wt-progress-text { font-size: 13px; color: rgba(255, 255, 255, 0.5); }

/* Tour Card */
.welcome-tour-card { background: linear-gradient(135deg, rgba(26, 26, 36, 0.95), rgba(18, 18, 26, 0.98)); border: 1px solid rgba(201, 169, 98, 0.15); border-radius: 16px; padding: 40px; backdrop-filter: blur(20px); }
.wt-card-icon { width: 72px; height: 72px; background: linear-gradient(135deg, var(--gold), #b8943d); border-radius: 14px; display: flex; align-items: center; justify-content: center; font-size: 28px; color: var(--emph-bg); margin: 0 auto 24px; }
.wt-card-icon.purple { background: linear-gradient(135deg, var(--accent), var(--accent)); }
.wt-card-icon.pink { background: linear-gradient(135deg, var(--accent), var(--accent)); }
.wt-card-icon.cyan { background: linear-gradient(135deg, var(--accent), var(--accent)); }
.welcome-tour-card h2 { font-size: 28px; font-weight: 700; color: #fff; text-align: center; margin: 0 0 12px 0; }
.welcome-tour-card > p { font-size: 15px; color: rgba(255, 255, 255, 0.6); text-align: center; margin: 0 0 32px 0; line-height: 1.6; }

/* Form Styles */
.wt-form { display: flex; flex-direction: column; gap: 20px; margin-bottom: 32px; }
.wt-form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.wt-form-group { display: flex; flex-direction: column; gap: 8px; }
.wt-form-group label { font-size: 13px; font-weight: 600; color: rgba(255, 255, 255, 0.7); text-transform: uppercase; letter-spacing: 0.5px; }
.wt-form-group input, .wt-form-group select { padding: 14px 16px; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 12px; color: #fff; font-size: 15px; transition: all 0.2s ease; }
.wt-form-group input::placeholder { color: rgba(255, 255, 255, 0.3); }
.wt-form-group input:focus, .wt-form-group select:focus { outline: none; border-color: var(--gold); background: rgba(201, 169, 98, 0.05); }
.wt-form-group select { cursor: pointer; }
.wt-form-group select option { background: #1a1a2e; color: #fff; }

/* Action Buttons */
.wt-actions { display: flex; justify-content: space-between; align-items: center; gap: 16px; }
.wt-btn { padding: 14px 28px; border-radius: 12px; font-size: 15px; font-weight: 600; cursor: pointer; transition: all 0.2s ease; border: none; display: inline-flex; align-items: center; gap: 8px; }
.wt-btn.secondary { background: rgba(255, 255, 255, 0.05); color: rgba(255, 255, 255, 0.6); border: 1px solid rgba(255, 255, 255, 0.1); }
.wt-btn.secondary:hover { background: rgba(255, 255, 255, 0.1); color: #fff; }
.wt-btn.primary { background: linear-gradient(135deg, var(--gold), #b8943d); color: var(--emph-bg); box-shadow: 0 4px 20px rgba(201, 169, 98, 0.3); }
.wt-btn.primary:hover { transform: translateY(-2px); box-shadow: 0 8px 30px rgba(201, 169, 98, 0.4); }

/* Role Selection */
.wt-role-grid { display: flex; flex-direction: column; gap: 12px; margin-bottom: 32px; }
.wt-role-option { display: flex; align-items: center; gap: 16px; padding: 16px 20px; background: rgba(255, 255, 255, 0.03); border: 2px solid rgba(255, 255, 255, 0.08); border-radius: 16px; cursor: pointer; transition: all 0.2s ease; }
.wt-role-option:hover { background: rgba(255, 255, 255, 0.06); border-color: rgba(255, 255, 255, 0.15); }
.wt-role-option.selected { background: rgba(201, 169, 98, 0.1); border-color: var(--gold); }
.wt-role-icon { width: 48px; height: 48px; border-radius: 14px; display: flex; align-items: center; justify-content: center; font-size: 20px; }
.wt-role-icon.student { background: rgba(155, 27, 34, 0.15); color: #9b1b22; }
.wt-role-icon.researcher { background: rgba(155, 27, 34, 0.15); color: var(--accent); }
.wt-role-icon.clinician { background: rgba(47, 107, 58, 0.15); color: var(--success); }
.wt-role-icon.industry { background: rgba(249, 115, 22, 0.15); color: #f97316; }
.wt-role-info { flex: 1; }
.wt-role-info h4 { font-size: 16px; font-weight: 600; color: #fff; margin: 0 0 4px 0; }
.wt-role-info p { font-size: 13px; color: rgba(255, 255, 255, 0.5); margin: 0; }
.wt-role-check { width: 24px; height: 24px; border: 2px solid rgba(255, 255, 255, 0.2); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: transparent; transition: all 0.2s ease; }
.wt-role-option.selected .wt-role-check { background: var(--gold); border-color: var(--gold); color: var(--emph-bg); }

/* Interests Grid */
.wt-interests-grid { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 32px; }
.wt-interest-chip { display: inline-flex; align-items: center; gap: 8px; padding: 12px 20px; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 25px; font-size: 14px; cursor: pointer; color: rgba(255, 255, 255, 0.7); transition: all 0.2s ease; }
.wt-interest-chip i { font-size: 12px; opacity: 0.7; }
.wt-interest-chip:hover { background: rgba(255, 255, 255, 0.1); color: #fff; border-color: rgba(255, 255, 255, 0.2); transform: translateY(-2px); }
.wt-interest-chip.selected { background: rgba(201, 169, 98, 0.15); border-color: var(--gold); color: var(--gold); }
.wt-interest-chip.selected i { opacity: 1; }

/* Programs List */
.wt-programs-list { display: flex; flex-direction: column; gap: 16px; margin-bottom: 32px; }
.wt-program-card { display: flex; gap: 16px; padding: 20px; background: rgba(255, 255, 255, 0.03); border: 2px solid rgba(255, 255, 255, 0.08); border-radius: 14px; cursor: pointer; transition: all 0.2s ease; }
.wt-program-card:hover { background: rgba(255, 255, 255, 0.06); border-color: rgba(255, 255, 255, 0.15); transform: translateY(-2px); }
.wt-program-card.selected { background: rgba(201, 169, 98, 0.08); border-color: rgba(201, 169, 98, 0.4); }
.wt-program-visual { width: 56px; height: 56px; border-radius: 16px; display: flex; align-items: center; justify-content: center; font-size: 24px; flex-shrink: 0; }
.wt-program-visual.plexus { background: rgba(155, 27, 34, 0.15); color: var(--accent); }
.wt-program-visual.accelerator { background: rgba(176, 106, 31, 0.15); color: var(--accent); }
.wt-program-visual.forum { background: rgba(107,98,88, 0.12); color: var(--muted); }
.wt-program-content { flex: 1; }
.wt-program-content h4 { font-size: 16px; font-weight: 600; color: #fff; margin: 0 0 6px 0; }
.wt-program-content p { font-size: 13px; color: rgba(255, 255, 255, 0.5); margin: 0 0 10px 0; line-height: 1.5; }
.wt-program-tags { display: flex; gap: 8px; }
.wt-program-tags span { font-size: 11px; padding: 4px 10px; background: rgba(255, 255, 255, 0.05); border-radius: 14px; color: rgba(255, 255, 255, 0.5); }
.wt-program-visual.bridges { background: rgba(201, 169, 98, 0.15); color: var(--gold); }
.wt-programs-note { display: flex; align-items: center; justify-content: center; gap: 8px; font-size: 12.5px; color: rgba(255, 255, 255, 0.55); text-align: center; margin: -18px 0 28px; }
.wt-programs-note i { color: var(--gold); font-size: 12px; }
.wt-program-check { width: 28px; height: 28px; border: 2px solid rgba(255, 255, 255, 0.15); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: transparent; transition: all 0.2s ease; font-size: 14px; flex-shrink: 0; align-self: center; }
.wt-program-card.selected .wt-program-check { background: var(--gold); border-color: var(--gold); color: var(--emph-bg); }

/* Site Tour (Step 5) */
.wt-site-tour { position: absolute; inset: 0; }
.wt-tour-overlay { position: absolute; inset: 0; background: rgba(0, 0, 0, 0.85); transition: opacity 0.3s ease; }
.wt-tour-spotlight { position: absolute; border-radius: 16px; box-shadow: 0 0 0 9999px rgba(0, 0, 0, 0.85), 0 0 30px rgba(201, 169, 98, 0.5); transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1); pointer-events: none; }
.wt-tour-tooltip { position: absolute; width: 320px; background: linear-gradient(135deg, #1a1a2e, var(--emph-bg)); border: 1px solid rgba(201, 169, 98, 0.3); border-radius: 16px; padding: 24px; box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5); transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1); z-index: 10; }
.wt-tooltip-content h4 { font-size: 18px; font-weight: 700; color: #fff; margin: 0 0 8px 0; }
.wt-tooltip-content p { font-size: 14px; color: rgba(255, 255, 255, 0.6); margin: 0; line-height: 1.6; }
.wt-tooltip-nav { display: flex; justify-content: space-between; align-items: center; margin-top: 20px; padding-top: 16px; border-top: 1px solid rgba(255, 255, 255, 0.1); }
.wt-tooltip-dots { display: flex; gap: 6px; }
.wt-tooltip-dots .dot { width: 8px; height: 8px; border-radius: 50%; background: rgba(255, 255, 255, 0.2); transition: all 0.2s ease; }
.wt-tooltip-dots .dot.active { background: var(--gold); width: 20px; border-radius: 4px; }
.wt-tooltip-actions { display: flex; gap: 12px; }
.wt-tooltip-skip { background: none; border: none; color: rgba(255, 255, 255, 0.5); font-size: 13px; cursor: pointer; padding: 8px 12px; }
.wt-tooltip-skip:hover { color: #fff; }
.wt-tooltip-next { padding: 10px 20px; background: var(--gold); color: var(--emph-bg); border: none; border-radius: 10px; font-size: 14px; font-weight: 600; cursor: pointer; display: flex; align-items: center; gap: 6px; transition: all 0.2s ease; }
.wt-tooltip-next:hover { transform: translateY(-2px); box-shadow: 0 4px 15px rgba(201, 169, 98, 0.4); }

/* Celebration (Step 6) */
.wt-celebration { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; background: linear-gradient(135deg, var(--emph-bg) 0%, #1a1a2e 50%, var(--emph-bg) 100%); overflow: hidden; }
.wt-confetti { position: absolute; inset: 0; pointer-events: none; }
.wt-confetti-piece { position: absolute; width: 12px; height: 12px; animation: confettiFall 4s ease-out forwards; }
@keyframes confettiFall { 0% { transform: translateY(-100px) rotate(0deg); opacity: 1; } 100% { transform: translateY(100vh) rotate(1080deg); opacity: 0; } }
.wt-celebration-content { position: relative; z-index: 1; text-align: center; padding: 40px; animation: celebrationPop 0.6s ease; }
@keyframes celebrationPop { from { opacity: 0; transform: scale(0.8); } to { opacity: 1; transform: scale(1); } }
.wt-celebration-badge { width: 120px; height: 120px; background: linear-gradient(135deg, var(--gold), #daa520); border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 32px; font-size: 48px; color: var(--emph-bg); position: relative; animation: badgeGlow 2s ease-in-out infinite; }
.wt-badge-glow { position: absolute; inset: -20px; background: radial-gradient(circle, rgba(201, 169, 98, 0.4), transparent 70%); border-radius: 50%; animation: glowPulse 2s ease-in-out infinite; }
@keyframes badgeGlow { 0%, 100% { box-shadow: 0 0 40px rgba(201, 169, 98, 0.4); } 50% { box-shadow: 0 0 80px rgba(201, 169, 98, 0.6); } }
@keyframes glowPulse { 0%, 100% { transform: scale(1); opacity: 0.5; } 50% { transform: scale(1.2); opacity: 0.8; } }
.wt-celebration-content h1 { font-size: 48px; font-weight: 700; color: #fff; margin: 0 0 16px 0; }
.wt-celebration-content > p { font-size: 18px; color: rgba(255, 255, 255, 0.6); margin: 0 0 40px 0; }
.wt-achievement-card { display: flex; align-items: center; gap: 16px; background: rgba(201, 169, 98, 0.1); border: 1px solid rgba(201, 169, 98, 0.25); border-radius: 16px; padding: 20px 24px; margin-bottom: 40px; text-align: left; }
.wt-achievement-icon { width: 52px; height: 52px; background: linear-gradient(135deg, var(--gold), #b8943d); border-radius: 14px; display: flex; align-items: center; justify-content: center; font-size: 22px; color: var(--emph-bg); }
.wt-achievement-info { flex: 1; display: flex; flex-direction: column; gap: 4px; }
.wt-achievement-label { font-size: 12px; text-transform: uppercase; letter-spacing: 1px; color: var(--gold); font-weight: 600; }
.wt-achievement-name { font-size: 18px; font-weight: 600; color: #fff; }
.wt-achievement-points { font-size: 16px; font-weight: 700; color: var(--gold); }
.wt-celebration-btn { display: inline-flex; align-items: center; gap: 12px; padding: 18px 40px; background: linear-gradient(135deg, var(--gold), #b8943d); color: var(--emph-bg); font-size: 18px; font-weight: 700; border: none; border-radius: 16px; cursor: pointer; transition: all 0.3s ease; }
.wt-celebration-btn:hover { transform: translateY(-4px) scale(1.02); box-shadow: 0 20px 40px rgba(201, 169, 98, 0.4); }

/* Feature Showcase (Step 5) */
.wt-features-showcase { position: relative; min-height: 280px; margin-bottom: 24px; }
.wt-feature-slide { display: none; text-align: center; animation: featureSlideIn 0.4s ease; }
.wt-feature-slide.active { display: block; }
@keyframes featureSlideIn { from { opacity: 0; transform: translateX(20px); } to { opacity: 1; transform: translateX(0); } }
.wt-feature-visual { height: 160px; display: flex; align-items: center; justify-content: center; margin-bottom: 20px; }
.wt-feature-mockup { position: relative; }
.wt-feature-mockup.dashboard { display: flex; gap: 8px; padding: 16px; background: rgba(255,255,255,0.03); border-radius: 16px; border: 1px solid rgba(255,255,255,0.1); }
.mockup-sidebar { width: 50px; display: flex; flex-direction: column; gap: 8px; }
.mockup-nav-item { height: 10px; background: rgba(255,255,255,0.1); border-radius: 4px; }
.mockup-nav-item.active { background: var(--gold); }
.mockup-content { width: 180px; display: flex; flex-direction: column; gap: 8px; }
.mockup-card { height: 40px; background: rgba(255,255,255,0.05); border-radius: 8px; border: 1px solid rgba(255,255,255,0.08); }
.wt-feature-mockup.programs { display: flex; gap: 16px; }
.mockup-program { width: 64px; height: 64px; border-radius: 16px; display: flex; align-items: center; justify-content: center; font-size: 24px; animation: programPop 0.5s ease backwards; }
.mockup-program.plexus { background: rgba(155, 27, 34, 0.2); color: var(--accent); animation-delay: 0s; }
.mockup-program.accelerator { background: rgba(176, 106, 31, 0.2); color: var(--accent); animation-delay: 0.1s; }
.mockup-program.forum { background: rgba(107,98,88, 0.15); color: var(--muted); animation-delay: 0.2s; }
@keyframes programPop { from { transform: scale(0); } to { transform: scale(1); } }
.wt-feature-mockup.network { position: relative; width: 200px; height: 120px; }
.mockup-avatar { position: absolute; width: 40px; height: 40px; background: linear-gradient(135deg, var(--gold), #b8943d); border-radius: 50%; animation: avatarFloat 3s ease-in-out infinite; animation-delay: var(--delay); }
.mockup-avatar:nth-child(1) { top: 10px; left: 30px; }
.mockup-avatar:nth-child(2) { top: 10px; right: 30px; }
.mockup-avatar:nth-child(3) { bottom: 10px; left: 50px; }
.mockup-avatar:nth-child(4) { bottom: 10px; right: 50px; }
@keyframes avatarFloat { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }
.mockup-lines { position: absolute; inset: 20px; border: 2px dashed rgba(201, 169, 98, 0.3); border-radius: 50%; }
.wt-feature-mockup.rewards { text-align: center; }
.mockup-badge { width: 72px; height: 72px; background: linear-gradient(135deg, var(--gold), #daa520); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 32px; color: var(--emph-bg); margin: 0 auto 12px; animation: badgeShine 2s ease-in-out infinite; }
@keyframes badgeShine { 0%, 100% { box-shadow: 0 0 20px rgba(201, 169, 98, 0.3); } 50% { box-shadow: 0 0 40px rgba(201, 169, 98, 0.6); } }
.mockup-points { font-size: 24px; font-weight: 700; color: var(--success); margin-bottom: 8px; animation: pointsPop 0.6s ease; }
@keyframes pointsPop { from { transform: scale(0); } 50% { transform: scale(1.2); } to { transform: scale(1); } }
.mockup-progress { width: 120px; height: 8px; background: rgba(255,255,255,0.1); border-radius: 4px; margin: 0 auto; overflow: hidden; }
.mockup-progress::after { content: ''; display: block; width: 60%; height: 100%; background: linear-gradient(90deg, var(--gold), #daa520); border-radius: 4px; animation: progressGrow 1s ease forwards; }
@keyframes progressGrow { from { width: 0; } to { width: 60%; } }
.wt-feature-slide h4 { font-size: 18px; font-weight: 700; color: #fff; margin: 0 0 8px 0; display: flex; align-items: center; justify-content: center; gap: 10px; }
.wt-feature-slide h4 i { color: var(--gold); }
.wt-feature-slide p { font-size: 14px; color: rgba(255,255,255,0.6); margin: 0; line-height: 1.6; }
.wt-feature-nav { margin-bottom: 24px; }
.wt-feature-dots { display: flex; justify-content: center; gap: 8px; }
.wt-fdot { width: 10px; height: 10px; border-radius: 50%; background: rgba(255,255,255,0.2); cursor: pointer; transition: all 0.2s ease; }
.wt-fdot:hover { background: rgba(255,255,255,0.4); }
.wt-fdot.active { background: var(--gold); width: 28px; border-radius: 5px; }

/* Condensed capabilities grid (Step 5) — replaces the auto-advancing carousel */
.wt-capabilities { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 28px; text-align: left; }
.wt-capability { display: flex; gap: 14px; align-items: flex-start; padding: 18px; background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 14px; transition: border-color 0.2s ease, transform 0.2s ease; }
.wt-capability:hover { border-color: rgba(201,169,98,0.35); transform: translateY(-2px); }
.wt-capability-icon { flex-shrink: 0; width: 42px; height: 42px; border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 18px; background: rgba(201,169,98,0.14); color: var(--gold); }
.wt-capability-text h4 { font-size: 15px; font-weight: 700; color: #fff; margin: 0 0 5px; }
.wt-capability-text p { font-size: 12.5px; line-height: 1.5; color: rgba(255,255,255,0.6); margin: 0; }
@media (max-width: 600px) { .wt-capabilities { grid-template-columns: 1fr; } }

/* Rewards Explainer (Step 6) */
.wt-rewards-explainer {
    background: rgba(201, 169, 98, 0.08);
    border: 1px solid rgba(201, 169, 98, 0.2);
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 32px;
    text-align: center;
}
.wt-rewards-title {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    font-size: 16px;
    font-weight: 600;
    color: var(--gold);
    margin-bottom: 12px;
}
.wt-rewards-title i {
    font-size: 18px;
}
.wt-rewards-desc {
    font-size: 14px;
    color: rgba(255, 255, 255, 0.7);
    line-height: 1.6;
    margin: 0 0 20px 0;
}
.wt-rewards-tiers {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    margin-bottom: 16px;
}
.wt-tier {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
}
.wt-tier-icon {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
}
.wt-tier-icon.bronze {
    background: linear-gradient(135deg, #cd7f32, #a0522d);
    color: #fff;
    box-shadow: 0 4px 15px rgba(205, 127, 50, 0.3);
}
.wt-tier-icon.silver {
    background: linear-gradient(135deg, #c0c0c0, #808080);
    color: #fff;
    box-shadow: 0 4px 15px rgba(192, 192, 192, 0.3);
}
.wt-tier-icon.gold {
    background: linear-gradient(135deg, #ffd700, var(--gold));
    color: var(--emph-bg);
    box-shadow: 0 4px 15px rgba(201, 169, 98, 0.4);
}
.wt-tier span {
    font-size: 12px;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.6);
}
.wt-tier-arrow {
