}

/* Mobile Responsive */
@media (max-width: 600px) {
    .welcome-splash-title { font-size: 36px; }
    .welcome-splash-subtitle { font-size: 16px; }
    .welcome-tour-card { padding: 28px 20px; }
    .welcome-tour-card h2 { font-size: 22px; }
    .wt-form-row { grid-template-columns: 1fr; }
    .wt-celebration-content h1 { font-size: 32px; }
