    #welcomeTourStep1 .wt-form { display: grid; grid-template-columns: 1fr 1fr; gap: 20px 24px; }
    #welcomeTourStep1 .wt-form-row { display: contents; }
    #welcomeTourStep1 .wt-form-group.wt-fullwidth { grid-column: 1 / -1; }
    #welcomeTourStep1 .wt-actions { margin-top: 8px; }
}

/* ===== DASHBOARD CUSTOMIZER ===== */
.dashboard-customizer-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(10, 10, 15, 0.9);
    z-index: 100001;
    display: none;
    align-items: center;
    justify-content: center;
    backdrop-filter: blur(12px);
    padding: 20px;
}
.dashboard-customizer-overlay.active { display: flex; }

.dashboard-customizer {
    width: 100%;
    max-width: 800px;
    max-height: 90vh;
    background: linear-gradient(135deg, var(--emph-bg-2) 0%, var(--emph-bg) 100%);
    border-radius: 16px;
    border: 1px solid rgba(201, 169, 98, 0.2);
    overflow: hidden;
    box-shadow: 0 30px 100px rgba(0, 0, 0, 0.6), 0 0 60px rgba(201, 169, 98, 0.1);
    animation: customizerSlide 0.4s ease;
    display: flex;
    flex-direction: column;
}
@keyframes customizerSlide {
    from { opacity: 0; transform: translateY(40px) scale(0.95); }
    to { opacity: 1; transform: translateY(0) scale(1); }
}

.customizer-header {
    padding: 32px;
    text-align: center;
    background: linear-gradient(180deg, rgba(201, 169, 98, 0.08) 0%, transparent 100%);
    border-bottom: 1px solid rgba(201, 169, 98, 0.1);
}
.customizer-icon {
    width: 72px;
    height: 72px;
    background: linear-gradient(135deg, var(--gold) 0%, #daa520 100%);
    border-radius: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 20px;
    font-size: 28px;
    color: var(--ink);
    box-shadow: 0 10px 40px rgba(201, 169, 98, 0.3);
}
.customizer-header h2 {
    font-size: 26px;
    font-weight: 700;
    color: #fff;
    margin-bottom: 8px;
}
.customizer-header p {
    font-size: 15px;
    color: var(--muted);
    max-width: 500px;
    margin: 0 auto;
}

.customizer-body {
    flex: 1;
    overflow-y: auto;
    padding: 24px 32px;
}

.customizer-section-title {
    font-size: 13px;
    font-weight: 600;
    color: var(--gold);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    gap: 8px;
}
.customizer-section-title::after {
    content: '';
    flex: 1;
    height: 1px;
    background: linear-gradient(90deg, rgba(201, 169, 98, 0.3), transparent);
}

.customizer-widgets {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 16px;
    margin-bottom: 32px;
}

.customizer-widget {
    background: rgba(30, 30, 40, 0.6);
    border: 2px solid rgba(100, 100, 120, 0.2);
    border-radius: 16px;
    padding: 20px;
    cursor: pointer;
    transition: all 0.25s ease;
    position: relative;
    overflow: hidden;
}
.customizer-widget::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(90deg, transparent, rgba(201, 169, 98, 0.5), transparent);
    opacity: 0;
    transition: opacity 0.3s;
}
.customizer-widget:hover {
    background: rgba(40, 40, 55, 0.8);
    border-color: rgba(201, 169, 98, 0.3);
    transform: translateY(-2px);
}
.customizer-widget:hover::before { opacity: 1; }

.customizer-widget.selected {
    border-color: var(--gold);
    background: rgba(201, 169, 98, 0.08);
}
.customizer-widget.selected::before {
    opacity: 1;
    background: linear-gradient(90deg, var(--gold), #daa520);
}

.customizer-widget-icon {
    width: 48px;
    height: 48px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    margin-bottom: 14px;
    transition: transform 0.3s;
}
.customizer-widget:hover .customizer-widget-icon { transform: scale(1.1); }

.customizer-widget-icon.programs { background: rgba(155, 27, 34, 0.15); color: var(--accent); }
.customizer-widget-icon.foryou { background: rgba(155, 27, 34, 0.15); color: var(--accent); }
.customizer-widget-icon.achievements { background: rgba(251, 191, 36, 0.15); color: #fbbf24; }
.customizer-widget-icon.whatsnext { background: rgba(176, 106, 31, 0.15); color: var(--accent); }
.customizer-widget-icon.rewards { background: rgba(201, 169, 98, 0.15); color: var(--gold); }
.customizer-widget-icon.profile { background: rgba(47, 107, 58, 0.15); color: var(--success); }
.customizer-widget-icon.network { background: rgba(155, 27, 34, 0.15); color: var(--accent); }
.customizer-widget-icon.events { background: rgba(249, 115, 22, 0.15); color: #fb923c; }

.customizer-widget-name {
    font-size: 15px;
    font-weight: 600;
    color: #fff;
    margin-bottom: 4px;
}
.customizer-widget-desc {
    font-size: 12px;
    color: var(--muted);
    line-height: 1.4;
}

.customizer-widget-toggle {
    position: absolute;
    top: 16px;
    right: 16px;
    width: 24px;
    height: 24px;
    border-radius: 50%;
    border: 2px solid var(--ink-soft);
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
}
.customizer-widget.selected .customizer-widget-toggle {
    background: var(--gold);
    border-color: var(--gold);
    color: var(--ink);
}
.customizer-widget-toggle i { font-size: 12px; opacity: 0; }
.customizer-widget.selected .customizer-widget-toggle i { opacity: 1; }

.customizer-footer {
    padding: 24px 32px;
    border-top: 1px solid rgba(201, 169, 98, 0.1);
    background: rgba(15, 15, 20, 0.5);
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 16px;
}

.customizer-default-btn {
    padding: 14px 24px;
    background: transparent;
    border: 1px solid var(--ink-soft);
    border-radius: 12px;
    color: var(--muted);
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
    display: flex;
    align-items: center;
    gap: 8px;
}
.customizer-default-btn:hover {
    border-color: var(--muted);
    color: #fff;
    background: rgba(107,98,88, 0.1);
}

.customizer-save-btn {
    padding: 14px 32px;
    background: linear-gradient(135deg, var(--gold) 0%, #daa520 100%);
    border: none;
    border-radius: 12px;
    color: var(--ink);
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
    display: flex;
    align-items: center;
    gap: 8px;
    box-shadow: 0 4px 20px rgba(201, 169, 98, 0.3);
}
.customizer-save-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 30px rgba(201, 169, 98, 0.4);
}

.customizer-preview-text {
    font-size: 13px;
    color: var(--muted);
}
.customizer-preview-text strong { color: var(--gold); }

@media (max-width: 640px) {
    .customizer-header { padding: 24px 20px; }
    .customizer-body { padding: 20px; }
    .customizer-widgets { grid-template-columns: 1fr 1fr; gap: 12px; }
    .customizer-widget { padding: 16px; }
    .customizer-footer { flex-direction: column; padding: 20px; }
    .customizer-default-btn, .customizer-save-btn { width: 100%; justify-content: center; }
}

/* ===== MY NETWORK CARD COMPACT ===== */
.my-network-card-compact {
    background: var(--up-bg-subtle, #f5f5f7);
    border: 1px solid var(--up-border, #d2d2d7);
    border-radius: 16px;
    padding: 16px 20px;
    margin-bottom: 20px;
    position: relative;
    overflow: hidden;
}
[data-theme="dark"] .my-network-card-compact {
    background: linear-gradient(135deg, var(--emph-bg-2) 0%, var(--emph-bg) 100%);
    border-color: rgba(201, 169, 98, 0.2);
}
.my-network-card-compact::before {
    content: '';
    position: absolute;
    top: -50%;
    right: -20%;
