    background: linear-gradient(135deg, var(--gold), #b8943d);
    color: var(--ink);
    font-size: 10px;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    margin-left: 4px;
}
.my-network-btn .points-badge {
    background: rgba(255, 255, 255, 0.25);
    color: inherit;
}
.my-network-btn.connect .points-badge {
    background: rgba(16, 185, 129, 0.2);
    color: var(--success);
}

/* Points Earned Animation */
.points-earned-float {
    position: fixed;
    font-size: 16px;
    font-weight: 700;
    color: var(--gold);
    text-shadow: 0 2px 8px rgba(201, 169, 98, 0.5);
    z-index: 10000;
    pointer-events: none;
    animation: pointsFloat 1.5s ease-out forwards;
}
@keyframes pointsFloat {
    0% { opacity: 1; transform: translateY(0) scale(1); }
