}

/* ===== FOR YOU FEED ===== */
.for-you-section { margin-bottom: 24px; }
.for-you-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }
.for-you-title { display: flex; align-items: center; gap: 10px; font-size: 18px; font-weight: 600; }
.for-you-title i { color: var(--gold); }
.for-you-subtitle { font-size: 12px; color: var(--muted); background: var(--bg-tertiary, var(--emph-line)); padding: 4px 12px; border-radius: 14px; }
.for-you-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; }
