.for-you-card-badge.trending { background: rgba(239, 68, 68, 0.15); color: var(--danger); }
.for-you-card-badge.deadline { background: rgba(249, 115, 22, 0.15); color: #f97316; }
.for-you-card-badge.new { background: rgba(47, 107, 58, 0.15); color: var(--success); }
.for-you-card-icon { width: 48px; height: 48px; border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 20px; margin-bottom: 16px; }
.for-you-card-icon.plexus { background: rgba(155, 27, 34, 0.15); color: var(--accent); }
.for-you-card-icon.accelerator { background: rgba(201, 169, 98, 0.15); color: var(--gold); }
.for-you-card-icon.forum { background: rgba(107,98,88, 0.12); color: var(--muted); }
.for-you-card-icon.network { background: rgba(47, 107, 58, 0.15); color: var(--success); }
.for-you-card-title { font-size: 16px; font-weight: 600; margin-bottom: 6px; }
.for-you-card-desc { font-size: 13px; color: var(--muted); margin-bottom: 16px; line-height: 1.5; }
.for-you-card-reason { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--muted); }
.for-you-card-reason i { color: var(--gold); font-size: 11px; }

/* For You Card Structure */
.for-you-card-header { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 12px; }
.for-you-card-match { display: flex; flex-direction: column; align-items: center; padding: 6px 12px; background: rgba(47, 107, 58, 0.1); border-radius: 10px; }
.for-you-card-match .match-score { font-size: 18px; font-weight: 700; color: var(--success); line-height: 1; }
.for-you-card-match .match-label { font-size: 10px; color: rgba(47, 107, 58, 0.8); text-transform: uppercase; letter-spacing: 0.5px; }
.for-you-card-body { margin-bottom: 16px; }
.for-you-card-body h4 { font-size: 16px; font-weight: 600; margin: 0 0 6px 0; color: #fff; }
.for-you-card-body .for-you-subtitle { display: inline-block; font-size: 12px; color: var(--muted); margin-bottom: 8px; }
.for-you-card-body .for-you-desc { font-size: 13px; color: var(--muted); line-height: 1.5; margin: 0; }
.for-you-card-footer { display: flex; align-items: center; justify-content: space-between; padding-top: 16px; border-top: 1px solid rgba(255, 255, 255, 0.05); }

/* For You Filter Tabs */
.for-you-filters { display: flex; gap: 6px; }
.for-you-filter {
