}
.for-you-filter.active {
    background: linear-gradient(135deg, var(--gold), #b8943d);
    border-color: transparent;
    color: var(--emph-bg);
    font-weight: 600;
    box-shadow: 0 4px 12px rgba(201, 169, 98, 0.3);
