.for-you-refresh-btn:active {
    transform: translateY(0);
}
.for-you-refresh-btn i {
    transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}
.for-you-refresh-btn:hover i {
    transform: rotate(180deg);
}

/* ===== FOR YOU SECTION - PROMINENT PLACEMENT ===== */
.for-you-section {
