    border-radius: 16px;
    padding: 20px;
    margin-bottom: 20px;
}

.quiz-widget-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 16px;
}

.quiz-widget-title {
    display: flex;
    align-items: center;
