.quiz-daily-progress {
    margin-bottom: 16px;
}

.quiz-progress-bar-wrapper {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    background: var(--bg-tertiary);
    border-radius: 10px;
}

.quiz-progress-bar {
    flex: 1;
    height: 8px;
    background: var(--border);
    border-radius: 4px;
    overflow: hidden;
}

.quiz-progress-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--success), var(--success));
    border-radius: 4px;
    transition: width 0.3s ease;
    width: 0%;
}

.quiz-daily-dots {
    display: flex;
    gap: 6px;
}

.quiz-daily-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: var(--border);
    transition: all 0.3s ease;
}

.quiz-daily-dot.completed { background: var(--success); }
.quiz-daily-dot.current { background: var(--accent-gold); animation: pulse 1.5s infinite; }
.quiz-daily-dot.wrong { background: var(--danger); }

@keyframes pulse {
    0%, 100% { transform: scale(1); opacity: 1; }
    50% { transform: scale(1.2); opacity: 0.7; }
}

.quiz-daily-text {
    font-size: 12px;
    color: var(--text-secondary);
    display: flex;
    align-items: center;
    gap: 6px;
    white-space: nowrap;
}

.quiz-points-badge {
    background: linear-gradient(135deg, var(--gold), #b8943d);
    color: var(--ink);
    font-size: 10px;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
}

.quiz-question-card {
    background: var(--bg-tertiary);
    border-radius: 12px;
    padding: 16px;
    margin-bottom: 12px;
}

.quiz-category-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 4px 10px;
    background: rgba(155, 27, 34, 0.15);
    border-radius: 12px;
    font-size: 10px;
    font-weight: 600;
    color: var(--accent);
    margin-bottom: 12px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.quiz-question-text {
    font-size: 15px;
    font-weight: 500;
    color: var(--text-primary);
    line-height: 1.5;
    margin-bottom: 16px;
}

.quiz-options {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.quiz-option {
    position: relative;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 14px;
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 10px;
    font-size: 13px;
    color: var(--text-primary);
    cursor: pointer;
    transition: all 0.2s ease;
}

.quiz-option:hover:not(.answered) {
    background: var(--bg-hover);
    border-color: var(--accent-gold);
    transform: translateX(4px);
}

.quiz-option-letter {
    width: 24px;
    height: 24px;
    background: var(--bg-tertiary);
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 11px;
    font-weight: 600;
    color: var(--text-secondary);
    flex-shrink: 0;
}

.quiz-option.correct {
    background: rgba(47, 107, 58, 0.15);
    border-color: var(--success);
}

.quiz-option.correct .quiz-option-letter {
    background: var(--success);
    color: #fff;
}

.quiz-option.incorrect {
    background: rgba(239, 68, 68, 0.15);
    border-color: var(--danger);
}

.quiz-option.incorrect .quiz-option-letter {
    background: var(--danger);
    color: #fff;
}

.quiz-option.answered {
    pointer-events: none;
    opacity: 0.6;
}

.quiz-option.answered.correct,
.quiz-option.answered.incorrect {
    opacity: 1;
}

.quiz-result {
    margin-top: 12px;
    padding: 14px;
    border-radius: 10px;
    display: none;
}

.quiz-result.show { display: block; }

.quiz-result.correct {
    background: rgba(47, 107, 58, 0.1);
    border: 1px solid rgba(47, 107, 58, 0.3);
}

.quiz-result.incorrect {
    background: rgba(239, 68, 68, 0.1);
    border: 1px solid rgba(239, 68, 68, 0.3);
}

.quiz-result-header {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 8px;
}

.quiz-result-header i {
    font-size: 18px;
}

.quiz-result.correct .quiz-result-header i { color: var(--success); }
.quiz-result.incorrect .quiz-result-header i { color: var(--danger); }

.quiz-result-header span {
