/* ===== GLOBAL BUTTON ANIMATIONS ===== */
button, .btn, [class*="-btn"], [class*="-action"] {
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Enhanced Button Hover Effects */
button:not(:disabled):active,
.btn:not(:disabled):active,
[class*="-btn"]:not(:disabled):active,
[class*="-action"]:not(:disabled):active {
    transform: scale(0.97);
}

/* Gold Primary Button Style */
.btn-gold, .up-btn-primary {
    background: linear-gradient(135deg, var(--gold) 0%, #b8943d 100%);
    color: var(--emph-bg);
    border: none;
    font-weight: 600;
    box-shadow: 0 4px 15px rgba(201, 169, 98, 0.25);
}
.btn-gold:hover, .up-btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 25px rgba(201, 169, 98, 0.35);
}
.btn-gold:active, .up-btn-primary:active {
    transform: translateY(0) scale(0.98);
}

/* Ghost/Outline Button Style */
.btn-ghost, .up-btn-secondary {
    background: transparent;
    border: 1px solid rgba(255, 255, 255, 0.2);
    color: rgba(255, 255, 255, 0.8);
}
.btn-ghost:hover, .up-btn-secondary:hover {
    background: rgba(255, 255, 255, 0.08);
    border-color: rgba(255, 255, 255, 0.3);
    color: #fff;
    transform: translateY(-1px);
}

/* Page Transitions — instant switch, no fade delay */
.up-section {
    opacity: 1;
}
.up-section.active {
    opacity: 1;
}
@keyframes sectionEnter {
    from {
        opacity: 0;
        transform: translateY(16px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
@keyframes sectionExit {
    from {
        opacity: 1;
        transform: translateY(0);
    }
    to {
        opacity: 0;
        transform: translateY(-8px);
    }
}
@keyframes fadeIn {
    from { opacity: 0; transform: translateY(12px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Card Hover Transitions */
.hub-card, .for-you-card, [class*="-card"] {
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1),
                box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1),
                border-color 0.3s ease;
}

/* Ripple Effect for Interactive Elements */
@keyframes ripple {
    0% { transform: scale(0); opacity: 0.5; }
    100% { transform: scale(2.5); opacity: 0; }
}

/* Focus States for Accessibility */
button:focus-visible, .btn:focus-visible, [class*="-btn"]:focus-visible {
    outline: 2px solid var(--gold);
    outline-offset: 2px;
}

/* Card Match Percentage Styling */
.for-you-match {
    font-size: 14px;
    font-weight: 700;
    color: var(--success);
    margin-bottom: 8px;
}

/* Card Meta Info (Date, Location) */
.for-you-card-meta {
    display: inline-block;
    padding: 4px 12px;
    background: rgba(255, 255, 255, 0.08);
    border-radius: 6px;
    font-size: 12px;
    color: rgba(255, 255, 255, 0.5);
    margin-bottom: 12px;
}

/* ===== ACHIEVEMENTS ===== */
.achievements-showcase { margin-bottom: 24px; }
.achievements-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }
.achievements-title { display: flex; align-items: center; gap: 10px; font-size: 18px; font-weight: 600; }
