.achievements-grid { display: flex; gap: 12px; overflow-x: auto; padding-bottom: 8px; }
.achievement-card { flex-shrink: 0; width: 140px; padding: 20px 16px; background: var(--bg-secondary, var(--emph-bg-2)); border: 1px solid var(--border, var(--emph-line)); border-radius: 16px; text-align: center; cursor: pointer; transition: all 0.2s; position: relative; }
.achievement-card:hover { transform: translateY(-4px); border-color: var(--gold); }
