@keyframes achGlow { 0%, 100% { box-shadow: 0 0 0 0 rgba(201, 169, 98, 0.4); } 50% { box-shadow: 0 0 20px 5px rgba(201, 169, 98, 0.4); } }
.achievement-card-new { position: absolute; top: -8px; right: -8px; width: 24px; height: 24px; background: var(--danger); border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 10px; color: white; }
.achievement-icon { width: 56px; height: 56px; border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 12px; font-size: 24px; background: var(--emph-line); color: var(--muted); }
.achievement-card.unlocked .achievement-icon { background: linear-gradient(135deg, #ffd700, #daa520); color: var(--ink); }
.achievement-card.unlocked .achievement-icon.bronze { background: linear-gradient(135deg, #cd7f32, #b87333); }
