.achievement-points { display: inline-flex; align-items: center; gap: 4px; margin-top: 8px; padding: 4px 10px; background: rgba(201, 169, 98, 0.15); border-radius: 12px; font-size: 11px; font-weight: 600; color: var(--gold); }
.achievement-card.locked .achievement-points { background: var(--emph-line); color: var(--muted); }
.achievement-unlock-modal { position: fixed; inset: 0; background: rgba(21, 17, 15, 0.55); z-index: 100001; display: none; align-items: center; justify-content: center; backdrop-filter: blur(10px); padding: 24px; }
.achievement-unlock-modal.active { display: flex; }
.achievement-unlock-content { position: relative; text-align: center; background: var(--surface); border: 1px solid var(--line); border-radius: 24px; padding: 48px 44px 36px; max-width: 400px; width: 100%; box-shadow: 0 30px 90px rgba(21, 17, 15, 0.28); animation: unlockPop 0.55s cubic-bezier(0.22, 0.61, 0.36, 1); }
