.achievement-unlock-desc { font-size: 14.5px; color: var(--muted); line-height: 1.5; margin-bottom: 22px; }
.achievement-unlock-reward { display: inline-flex; align-items: center; gap: 8px; padding: 11px 22px; background: rgba(201, 169, 98, 0.14); border: 1px solid rgba(201, 169, 98, 0.3); border-radius: 999px; font-size: 16px; font-weight: 700; color: #a8842f; }
