.achievement-unlock-points { display: inline-flex; align-items: center; gap: 8px; padding: 11px 22px; background: rgba(201, 169, 98, 0.14); border: 1px solid rgba(201, 169, 98, 0.3); border-radius: 999px; font-size: 16px; font-weight: 700; color: #a8842f; }
.achievement-unlock-btn { margin-top: 30px; width: 100%; padding: 15px 28px; background: var(--crimson); border: none; border-radius: 14px; color: #fff; font-size: 15px; font-weight: 700; cursor: pointer; transition: transform 0.2s ease, box-shadow 0.2s ease; box-shadow: 0 10px 26px rgba(155, 27, 34, 0.24); }
