/* Achievements Section Additional Styles */
.achievements-section { background: linear-gradient(135deg, var(--emph-bg-2) 0%, #15151f 100%); }
.achievements-summary { display: flex; justify-content: space-around; padding: 20px 0; margin-bottom: 20px; border-bottom: 1px solid rgba(255, 255, 255, 0.05); }
.achievements-summary .achievements-stat { display: flex; flex-direction: column; align-items: center; gap: 4px; }
.achievements-stat-value { font-size: 28px; font-weight: 700; color: var(--gold); }
.achievements-stat-label { font-size: 12px; color: rgba(255, 255, 255, 0.5); text-transform: uppercase; letter-spacing: 1px; }
.achievements-streak { display: flex; align-items: center; gap: 6px; padding: 6px 12px; background: linear-gradient(135deg, rgba(249, 115, 22, 0.15), rgba(239, 68, 68, 0.15)); border-radius: 14px; font-size: 13px; font-weight: 600; color: #f97316; }
.achievements-streak i { color: var(--danger); }
.achievements-footer { display: flex; justify-content: center; padding-top: 20px; margin-top: 20px; border-top: 1px solid rgba(255, 255, 255, 0.05); }
.achievements-view-all { display: inline-flex; align-items: center; gap: 10px; padding: 12px 28px; background: transparent; border: 1px solid rgba(201, 169, 98, 0.3); border-radius: 12px; font-size: 14px; font-weight: 600; color: var(--gold); cursor: pointer; transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); }
.achievements-view-all:hover { background: rgba(201, 169, 98, 0.1); border-color: var(--gold); transform: translateY(-2px); box-shadow: 0 4px 20px rgba(201, 169, 98, 0.15); }
.achievements-view-all:active { transform: translateY(0); }
.achievements-view-all i { transition: transform 0.3s ease; }
.achievements-view-all:hover i { transform: translateX(4px); }

/* PWA Elements - Hidden by Default */
.pwa-install-banner { display: none; position: fixed; bottom: 20px; left: 20px; right: 20px; max-width: 400px; margin: 0 auto; background: var(--emph-bg-2); border: 1px solid rgba(201, 169, 98, 0.3); border-radius: 16px; padding: 16px 20px; z-index: 99999; box-shadow: 0 10px 40px rgba(0,0,0,0.5); }
.pwa-install-banner.active { display: flex; align-items: center; gap: 16px; }
.pwa-install-icon { width: 48px; height: 48px; background: linear-gradient(135deg, var(--gold), #b8943d); border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 20px; color: var(--emph-bg); }
.pwa-install-content { flex: 1; }
.pwa-install-content h4 { font-size: 15px; font-weight: 600; color: #fff; margin: 0 0 4px 0; }
.pwa-install-content p { font-size: 13px; color: rgba(255,255,255,0.6); margin: 0; }
.pwa-install-actions { display: flex; gap: 8px; }
.pwa-install-btn { padding: 8px 16px; border-radius: 8px; font-size: 13px; font-weight: 600; cursor: pointer; border: none; }
.pwa-install-btn.secondary { background: transparent; color: rgba(255,255,255,0.6); }
.pwa-install-btn.primary { background: var(--gold); color: var(--emph-bg); }
.offline-banner { display: none; position: fixed; top: 0; left: 0; right: 0; background: var(--danger); color: white; padding: 12px 20px; text-align: center; font-size: 14px; z-index: 99999; }
