.online-toast { display: none; position: fixed; top: 20px; left: 50%; transform: translateX(-50%); background: var(--success); color: white; padding: 12px 24px; border-radius: 8px; font-size: 14px; z-index: 99999; }
.online-toast.active { display: flex; align-items: center; gap: 8px; }
.pull-to-refresh { display: none; }
.swipe-indicator { display: none; }
.update-banner { display: none; position: fixed; bottom: 20px; left: 20px; right: 20px; max-width: 400px; margin: 0 auto; background: var(--emph-bg-2); border: 1px solid rgba(155, 27, 34, 0.3); border-radius: 16px; padding: 16px 20px; z-index: 99999; }
.update-banner.active { display: flex; align-items: center; gap: 16px; }

/* Notification Center - Hidden by Default */
.notification-center { display: none; position: fixed; top: 80px; right: 20px; width: 380px; max-height: calc(100vh - 120px); background: var(--emph-bg-2); border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 16px; box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4); z-index: 10001; overflow: hidden; }
.notification-center.active { display: block; }
.notification-center-header { display: flex; justify-content: space-between; align-items: center; padding: 16px 20px; border-bottom: 1px solid rgba(255, 255, 255, 0.1); }
.notification-center-header h3 { margin: 0; font-size: 16px; font-weight: 600; color: #fff; }
.notification-center-actions { display: flex; gap: 8px; }
.notification-center-btn { background: transparent; border: none; color: rgba(255, 255, 255, 0.6); font-size: 13px; cursor: pointer; padding: 6px 10px; border-radius: 6px; transition: all 0.2s; }
.notification-center-btn:hover { background: rgba(255, 255, 255, 0.1); color: #fff; }
.notification-list { max-height: 400px; overflow-y: auto; }

/* Bottom Sheet - Hidden by Default */
.bottom-sheet-overlay { display: none; position: fixed; inset: 0; background: rgba(0, 0, 0, 0.5); z-index: 10000; opacity: 0; transition: opacity 0.3s; }
.bottom-sheet-overlay.active { display: block; opacity: 1; }
.bottom-sheet { display: none; position: fixed; bottom: 0; left: 0; right: 0; background: var(--emph-bg-2); border-radius: 14px 20px 0 0; z-index: 10001; transform: translateY(100%); transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1); max-height: 80vh; overflow: hidden; }
.bottom-sheet.active { display: block; transform: translateY(0); }
.bottom-sheet-handle { width: 40px; height: 4px; background: rgba(255, 255, 255, 0.2); border-radius: 2px; margin: 12px auto; }
.bottom-sheet-header { display: flex; justify-content: space-between; align-items: center; padding: 0 20px 16px; border-bottom: 1px solid rgba(255, 255, 255, 0.1); }
.bottom-sheet-header h3 { margin: 0; font-size: 18px; font-weight: 600; color: #fff; }
.bottom-sheet-close { background: transparent; border: none; color: rgba(255, 255, 255, 0.6); font-size: 18px; cursor: pointer; padding: 8px; border-radius: 8px; transition: all 0.2s; }
.bottom-sheet-close:hover { background: rgba(255, 255, 255, 0.1); color: #fff; }
.bottom-sheet-body { padding: 20px; overflow-y: auto; max-height: calc(80vh - 100px); }

.streak-card { display: flex; align-items: center; gap: 16px; padding: 16px 20px; background: linear-gradient(135deg, rgba(249, 115, 22, 0.1), rgba(239, 68, 68, 0.1)); border: 1px solid rgba(249, 115, 22, 0.3); border-radius: 12px; margin-bottom: 16px; }
.streak-icon { width: 48px; height: 48px; background: linear-gradient(135deg, #f97316, var(--danger)); border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 24px; color: white; }
.streak-info { flex: 1; }
.streak-count { font-size: 24px; font-weight: 700; }
.streak-count span { font-size: 14px; color: var(--muted); font-weight: 400; }
.streak-progress { display: flex; gap: 4px; }
.streak-day { width: 28px; height: 28px; border-radius: 6px; background: var(--emph-line); display: flex; align-items: center; justify-content: center; font-size: 10px; color: var(--muted); }
.streak-day.completed { background: linear-gradient(135deg, #f97316, var(--danger)); color: white; }
.streak-day.today { border: 2px solid #f97316; }
.profile-completion-prompt { display: flex; align-items: center; gap: 16px; padding: 16px 20px; background: linear-gradient(135deg, rgba(155, 27, 34, 0.1), rgba(155, 27, 34, 0.1)); border: 1px solid rgba(155, 27, 34, 0.3); border-radius: 12px; margin-bottom: 16px; cursor: pointer; }
.profile-completion-prompt:hover { transform: translateX(4px); }
.profile-completion-icon { width: 48px; height: 48px; background: linear-gradient(135deg, var(--accent), #9b1b22); border-radius: 12px; display: flex; align-items: center; justify-content: center; font-size: 20px; color: white; }
.profile-completion-info { flex: 1; }
.profile-completion-title { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.profile-completion-desc { font-size: 13px; color: var(--muted); }
.profile-completion-progress { width: 100px; height: 8px; background: var(--emph-line); border-radius: 4px; overflow: hidden; }
.profile-completion-progress-fill { height: 100%; background: linear-gradient(90deg, var(--accent), #9b1b22); border-radius: 4px; }
.profile-completion-percent { font-size: 14px; font-weight: 600; color: var(--accent); }

/* ========== ADMIN POWER FEATURES ========== */

/* Bulk Actions Bar */
.bulk-actions-bar {
    position: fixed;
    bottom: -80px;
    left: 50%;
    transform: translateX(-50%);
    background: linear-gradient(135deg, var(--emph-bg-2) 0%, var(--emph-bg) 100%);
    border: 1px solid rgba(201, 169, 98, 0.3);
    border-radius: 16px;
    padding: 12px 24px;
    display: flex;
    align-items: center;
    gap: 16px;
    box-shadow: 0 -4px 30px rgba(0, 0, 0, 0.3), 0 0 0 1px rgba(255, 255, 255, 0.05);
    z-index: 9999;
    transition: bottom 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.bulk-actions-bar.active {
    bottom: 24px;
}

.bulk-actions-count {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 16px;
    background: rgba(201, 169, 98, 0.15);
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    color: var(--gold);
}

.bulk-actions-count i {
    font-size: 12px;
}

.bulk-actions-divider {
    width: 1px;
    height: 32px;
    background: rgba(255, 255, 255, 0.1);
}

.bulk-action-btn {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 16px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 8px;
    color: var(--line);
    font-size: 13px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.bulk-action-btn:hover {
    background: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.2);
}

.bulk-action-btn.primary {
    background: linear-gradient(135deg, var(--gold), #b8943d);
    border-color: transparent;
    color: var(--emph-bg);
}

.bulk-action-btn.primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 15px rgba(201, 169, 98, 0.4);
}

.bulk-action-btn.success {
    background: rgba(47, 107, 58, 0.1);
    border-color: rgba(47, 107, 58, 0.3);
    color: var(--success);
}

.bulk-action-btn.success:hover {
    background: rgba(47, 107, 58, 0.2);
}

.bulk-action-btn.warning {
    background: rgba(245, 158, 11, 0.1);
    border-color: rgba(245, 158, 11, 0.3);
    color: var(--warning);
}

.bulk-action-btn.warning:hover {
    background: rgba(245, 158, 11, 0.2);
}

.bulk-action-btn.danger {
    background: rgba(239, 68, 68, 0.1);
    border-color: rgba(239, 68, 68, 0.3);
    color: var(--danger);
}

.bulk-action-btn.danger:hover {
    background: rgba(239, 68, 68, 0.2);
}

.bulk-actions-close {
    padding: 8px;
    background: transparent;
    border: none;
    color: var(--muted);
    cursor: pointer;
    border-radius: 6px;
    transition: all 0.2s;
}

.bulk-actions-close:hover {
    background: rgba(255, 255, 255, 0.1);
    color: var(--line);
}

/* Table Row Selection */
.data-table .row-checkbox {
    width: 18px;
    height: 18px;
    accent-color: var(--gold);
    cursor: pointer;
}

.data-table tr.selected {
    background: rgba(201, 169, 98, 0.1) !important;
}

.data-table tr.selected td {
    border-color: rgba(201, 169, 98, 0.2);
}

/* Keyboard Shortcuts Modal */
.shortcuts-modal {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(8px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 99999;
    opacity: 0;
    visibility: hidden;
    transition: all 0.2s;
}

.shortcuts-modal.active {
    opacity: 1;
    visibility: visible;
}

.shortcuts-modal-content {
    background: linear-gradient(135deg, var(--emph-bg-2) 0%, var(--emph-bg) 100%);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px;
    padding: 32px;
    max-width: 600px;
    width: 90%;
    max-height: 80vh;
    overflow-y: auto;
    transform: scale(0.9);
    transition: transform 0.2s;
}

.shortcuts-modal.active .shortcuts-modal-content {
    transform: scale(1);
}

.shortcuts-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 24px;
    padding-bottom: 16px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.shortcuts-modal-header h2 {
    font-size: 20px;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 12px;
}

.shortcuts-modal-header h2 i {
    color: var(--gold);
}

.shortcuts-modal-close {
    padding: 8px;
    background: transparent;
    border: none;
    color: var(--muted);
    cursor: pointer;
    border-radius: 6px;
    font-size: 18px;
}

.shortcuts-modal-close:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.shortcuts-section {
    margin-bottom: 24px;
}

.shortcuts-section:last-child {
    margin-bottom: 0;
}

.shortcuts-section-title {
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--muted);
    margin-bottom: 12px;
}

.shortcut-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.shortcut-row:last-child {
    border-bottom: none;
}

.shortcut-desc {
    font-size: 14px;
    color: var(--line);
}

.shortcut-keys {
    display: flex;
    align-items: center;
    gap: 6px;
}

.shortcut-key {
    padding: 4px 10px;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.15);
    border-radius: 6px;
    font-size: 12px;
    font-weight: 600;
    color: var(--gold);
    font-family: monospace;
}

.shortcut-plus {
    color: var(--muted);
    font-size: 12px;
}

/* Export Modal */
.export-modal {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.8);
    backdrop-filter: blur(8px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 99999;
    opacity: 0;
    visibility: hidden;
    transition: all 0.2s;
}

.export-modal.active {
    opacity: 1;
    visibility: visible;
}

.export-modal-content {
    background: linear-gradient(135deg, var(--emph-bg-2) 0%, var(--emph-bg) 100%);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 14px;
    padding: 32px;
    max-width: 500px;
    width: 90%;
}

.export-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 24px;
}

.export-modal-header h3 {
    font-size: 18px;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 10px;
}

.export-modal-header h3 i {
    color: var(--success);
}

.export-columns {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
    margin-bottom: 24px;
    max-height: 250px;
    overflow-y: auto;
    padding: 16px;
    background: rgba(0, 0, 0, 0.2);
    border-radius: 12px;
}

.export-column-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 12px;
    background: rgba(255, 255, 255, 0.05);
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s;
}

.export-column-item:hover {
    background: rgba(255, 255, 255, 0.1);
}

.export-column-item input {
    accent-color: var(--gold);
}

.export-column-item label {
    font-size: 13px;
    cursor: pointer;
}

.export-actions {
    display: flex;
    gap: 12px;
    justify-content: flex-end;
}

.export-btn {
    padding: 10px 20px;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.export-btn.secondary {
    background: transparent;
    border: 1px solid rgba(255, 255, 255, 0.2);
    color: var(--muted);
}

.export-btn.primary {
    background: linear-gradient(135deg, var(--success), var(--success));
    border: none;
    color: white;
}

.export-btn.primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 15px rgba(47, 107, 58, 0.4);
}

/* Sparklines */
.stat-sparkline {
    display: flex;
    align-items: flex-end;
    gap: 2px;
    height: 32px;
    margin-top: 12px;
    padding-top: 8px;
    border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.sparkline-bar {
    flex: 1;
    background: linear-gradient(to top, rgba(201, 169, 98, 0.3), rgba(201, 169, 98, 0.6));
    border-radius: 2px 2px 0 0;
    min-height: 4px;
    transition: all 0.3s ease;
}

.sparkline-bar:hover {
    background: linear-gradient(to top, rgba(201, 169, 98, 0.5), rgba(201, 169, 98, 0.9));
}

.sparkline-bar.up {
    background: linear-gradient(to top, rgba(47, 107, 58, 0.3), rgba(47, 107, 58, 0.6));
}

.sparkline-bar.down {
    background: linear-gradient(to top, rgba(239, 68, 68, 0.3), rgba(239, 68, 68, 0.6));
}

.stat-trend {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 8px;
    font-size: 12px;
}

.stat-trend.up {
    color: var(--success);
}

.stat-trend.down {
    color: var(--danger);
}

.stat-trend.neutral {
    color: var(--muted);
}

.stat-trend i {
    font-size: 10px;
}

/* Select All Header */
.select-all-header {
    display: flex;
    align-items: center;
    gap: 8px;
}

.select-all-header input {
    width: 18px;
    height: 18px;
    accent-color: var(--gold);
    cursor: pointer;
}

/* ========== PHASE 6: PERFORMANCE & DATA ========== */

/* Skeleton Loaders */
.skeleton {
    background: linear-gradient(90deg, var(--bg-tertiary) 25%, var(--bg-secondary) 50%, var(--bg-tertiary) 75%);
    background-size: 200% 100%;
    animation: skeleton-shimmer 1.5s ease-in-out infinite;
    border-radius: 8px;
}

@keyframes skeleton-shimmer {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
}

.skeleton-text {
    height: 14px;
    margin-bottom: 8px;
}

.skeleton-text.short { width: 60%; }
.skeleton-text.medium { width: 80%; }
.skeleton-text.long { width: 100%; }

.skeleton-title {
    height: 24px;
    width: 70%;
    margin-bottom: 12px;
}

.skeleton-avatar {
    width: 48px;
    height: 48px;
    border-radius: 50%;
}

.skeleton-card {
    background: var(--bg-secondary);
    border: 1px solid var(--border-primary);
    border-radius: 16px;
    padding: 20px;
    margin-bottom: 16px;
}

.skeleton-card-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 16px;
}

.skeleton-card-body {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.skeleton-image {
    width: 100%;
    height: 200px;
    border-radius: 12px;
}

.skeleton-button {
    height: 40px;
    width: 120px;
    border-radius: 8px;
}

.skeleton-stat {
    height: 48px;
    width: 100%;
    border-radius: 8px;
}

.skeleton-list-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 0;
    border-bottom: 1px solid var(--border-primary);
}

.skeleton-list-item:last-child {
    border-bottom: none;
}

/* Lazy Load Images */
.lazy-image {
    opacity: 0;
    transition: opacity 0.3s ease;
}

.lazy-image.loaded {
    opacity: 1;
}

.lazy-placeholder {
    background: var(--bg-tertiary);
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-muted);
    font-size: 24px;
}

/* Virtual Scroll Container */
.virtual-scroll-container {
    overflow-y: auto;
    position: relative;
}

.virtual-scroll-content {
    position: relative;
}

.virtual-scroll-item {
    position: absolute;
    left: 0;
    right: 0;
}

.virtual-scroll-spacer {
    pointer-events: none;
}

/* Data Cache Indicator */
.cache-indicator {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 11px;
    color: var(--text-muted);
    padding: 2px 8px;
    background: var(--bg-tertiary);
    border-radius: 4px;
}

.cache-indicator.fresh {
    color: var(--success);
}

.cache-indicator.stale {
    color: var(--warning);
}

.cache-indicator i {
    font-size: 10px;
}

/* Loading States */
.content-loading {
    position: relative;
    min-height: 200px;
}

.content-loading::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 32px;
    height: 32px;
    border: 3px solid var(--border-primary);
    border-top-color: var(--up-gold);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to { transform: translate(-50%, -50%) rotate(360deg); }
}

/* Sync Status */
.sync-status {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    color: var(--text-muted);
}

.sync-status.syncing {
    color: var(--accent);
}

.sync-status.synced {
    color: var(--success);
}

.sync-status.error {
    color: var(--danger);
}

.sync-status i {
    font-size: 10px;
}

.sync-status.syncing i {
    animation: spin 1s linear infinite;
}

/* Optimistic Update Indicators */
.optimistic-update {
    opacity: 0.7;
    position: relative;
}

.optimistic-update::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: repeating-linear-gradient(
        45deg,
        transparent,
        transparent 10px,
        rgba(155, 27, 34, 0.05) 10px,
        rgba(155, 27, 34, 0.05) 20px
    );
    pointer-events: none;
    border-radius: inherit;
}

/* Infinite Scroll Loader */
.infinite-scroll-loader {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
    gap: 8px;
    color: var(--text-muted);
    font-size: 14px;
}

.infinite-scroll-loader .dots {
    display: flex;
    gap: 4px;
}

.infinite-scroll-loader .dot {
    width: 8px;
    height: 8px;
    background: var(--up-gold);
    border-radius: 50%;
    animation: bounce 1.4s ease-in-out infinite;
}

.infinite-scroll-loader .dot:nth-child(1) { animation-delay: 0s; }
.infinite-scroll-loader .dot:nth-child(2) { animation-delay: 0.2s; }
.infinite-scroll-loader .dot:nth-child(3) { animation-delay: 0.4s; }

@keyframes bounce {
    0%, 80%, 100% { transform: scale(0.6); opacity: 0.5; }
    40% { transform: scale(1); opacity: 1; }
}

/* Data Refresh Button */
.refresh-btn {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    background: transparent;
    border: 1px solid var(--border-primary);
    border-radius: 6px;
    color: var(--text-secondary);
    font-size: 12px;
    cursor: pointer;
    transition: all 0.2s;
}

.refresh-btn:hover {
    border-color: var(--up-gold);
    color: var(--up-gold);
}

.refresh-btn.refreshing i {
    animation: spin 1s linear infinite;
}

/* Prefetch Indicator */
.prefetch-link {
    position: relative;
}

.prefetch-link.prefetching::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 100%;
    height: 2px;
    background: linear-gradient(90deg, transparent, var(--up-gold), transparent);
    animation: prefetch-wave 1s ease-in-out infinite;
}

@keyframes prefetch-wave {
    0%, 100% { opacity: 0.3; }
    50% { opacity: 1; }
}

/* Memory Usage Warning */
.memory-warning {
    position: fixed;
    bottom: 20px;
    right: 20px;
    background: #fef3c7;
    border: 1px solid var(--warning);
    color: #92400e;
    padding: 12px 16px;
    border-radius: 8px;
    font-size: 13px;
    display: none;
    align-items: center;
    gap: 8px;
    z-index: 9999;
}

.memory-warning.active {
    display: flex;
}

/* Stale Data Banner */
.stale-data-banner {
    background: linear-gradient(90deg, rgba(245, 158, 11, 0.1), rgba(245, 158, 11, 0.05));
    border: 1px solid rgba(245, 158, 11, 0.3);
    border-radius: 8px;
    padding: 10px 16px;
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-size: 13px;
    color: var(--warning);
}

.stale-data-banner button {
    background: var(--warning);
    color: #000;
    border: none;
    padding: 4px 12px;
    border-radius: 4px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
}

/* ========== PHASE 1: UX ENHANCEMENTS ========== */

/* === 1.1 Confirmation Dialog System === */
.confirmation-modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(4px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 100005;
    opacity: 0;
    visibility: hidden;
    transition: all 0.2s ease;
}

.confirmation-modal-overlay.active {
    opacity: 1;
    visibility: visible;
}

.confirmation-modal {
    background: linear-gradient(135deg, var(--emph-bg-2) 0%, var(--emph-bg) 100%);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 0;
    width: 100%;
    max-width: 420px;
    transform: scale(0.9) translateY(20px);
    transition: transform 0.2s ease;
    overflow: hidden;
    box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
}

.confirmation-modal-overlay.active .confirmation-modal {
    transform: scale(1) translateY(0);
}

.confirmation-modal-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px 24px 16px;
}

.confirmation-modal-icon .icon-circle {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 28px;
}

.confirmation-modal-icon .icon-circle.danger {
    background: rgba(239, 68, 68, 0.15);
    color: var(--danger);
}

.confirmation-modal-icon .icon-circle.warning {
    background: rgba(245, 158, 11, 0.15);
    color: var(--warning);
}

.confirmation-modal-icon .icon-circle.info {
    background: rgba(155, 27, 34, 0.15);
    color: var(--accent);
}

.confirmation-modal-icon .icon-circle.success {
    background: rgba(47, 107, 58, 0.15);
    color: #2f6b3a;
}

.confirmation-modal-body {
    padding: 0 24px 24px;
    text-align: center;
}

.confirmation-modal-title {
    font-size: 18px;
    font-weight: 600;
    color: var(--paper-2);
    margin-bottom: 8px;
}

.confirmation-modal-message {
    font-size: 14px;
    color: var(--muted);
    line-height: 1.6;
}

.confirmation-modal-item {
    background: var(--bg-tertiary);
    border-radius: 8px;
    padding: 12px 16px;
    margin-top: 16px;
    font-size: 13px;
    color: var(--text-primary);
    text-align: left;
}

.confirmation-modal-actions {
    display: flex;
    gap: 12px;
    padding: 16px 24px;
    background: rgba(0, 0, 0, 0.2);
    border-top: 1px solid var(--border);
}

.confirmation-modal-btn {
    flex: 1;
    padding: 12px 20px;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
    border: none;
    font-family: inherit;
}

.confirmation-modal-btn.cancel {
    background: var(--bg-tertiary);
    color: var(--text-secondary);
}

.confirmation-modal-btn.cancel:hover {
    background: var(--bg-hover);
    color: var(--text-primary);
}

.confirmation-modal-btn.confirm {
    background: var(--accent-gold);
    color: var(--bg-primary);
}

.confirmation-modal-btn.confirm:hover {
    background: var(--accent-gold-dim);
}

.confirmation-modal-btn.confirm:active {
    transform: scale(0.97);
    box-shadow: none;
}

.confirmation-modal-btn.confirm.danger {
    background: var(--danger);
    color: white;
}

.confirmation-modal-btn.confirm.danger:hover {
    background: var(--danger);
}

.confirmation-modal-btn.confirm.danger:active {
    transform: scale(0.97);
    box-shadow: none;
}

/* === Input Modal (native prompt replacement) === */
.input-modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(4px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 100001;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.2s;
}
.input-modal-overlay.active {
    opacity: 1;
    pointer-events: auto;
}
.input-modal {
    background: linear-gradient(135deg, var(--emph-bg-2) 0%, var(--emph-bg) 100%);
    border: 1px solid rgba(201, 169, 98, 0.2);
    border-radius: 16px;
    width: 420px;
    max-width: 90vw;
    box-shadow: 0 24px 48px rgba(0, 0, 0, 0.4);
    transform: scale(0.9) translateY(20px);
    transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.input-modal-overlay.active .input-modal {
    transform: scale(1) translateY(0);
}
.input-modal-body {
    padding: 24px 24px 16px;
}
.input-modal-title {
    font-size: 18px;
    font-weight: 700;
    color: var(--paper-2);
    margin: 0 0 6px;
}
.input-modal-message {
    font-size: 14px;
    color: var(--muted);
    margin: 0 0 16px;
}
.input-modal-input {
    width: 100%;
    padding: 10px 14px;
    border-radius: 8px;
    border: 1px solid rgba(201, 169, 98, 0.3);
    background: rgba(20,15,12, 0.6);
    color: var(--paper-2);
    font-size: 14px;
    font-family: inherit;
    outline: none;
    transition: border-color 0.2s;
    box-sizing: border-box;
}
.input-modal-input:focus {
    border-color: var(--accent-gold, var(--gold));
}
textarea.input-modal-input {
    min-height: 80px;
    resize: vertical;
}
.input-modal-actions {
    display: flex;
    gap: 12px;
    padding: 16px 24px;
    background: rgba(0, 0, 0, 0.2);
    border-top: 1px solid rgba(201, 169, 98, 0.1);
    border-radius: 0 0 16px 16px;
}
.input-modal-actions .confirmation-modal-btn { flex: 1; }

/* === 1.2 Enhanced Focus States === */
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
.nav-item:focus-visible,
.sidebar-project:focus-visible,
.channel-item:focus-visible,
.for-you-card:focus-visible,
.event-card:focus-visible,
.member-card:focus-visible,
.achievement-card:focus-visible,
[role="button"]:focus-visible,
[tabindex]:focus-visible {
    outline: 2px solid var(--accent-gold);
    outline-offset: 2px;
}

/* Remove default outline but keep focus-visible */
a:focus:not(:focus-visible),
button:focus:not(:focus-visible),
input:focus:not(:focus-visible),
select:focus:not(:focus-visible),
textarea:focus:not(:focus-visible),
[tabindex]:focus:not(:focus-visible) {
    outline: none;
}

/* Focus within for complex components */
.data-table tr:focus-within {
    background: rgba(201, 169, 98, 0.05);
}

.form-group:focus-within .form-label {
    color: var(--accent-gold);
}

/* === 1.3 Unified Empty State Component === */
.empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 48px 24px;
    text-align: center;
    min-height: 240px;
}

.empty-state-icon {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: var(--bg-tertiary);
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 20px;
}

.empty-state-icon i {
    font-size: 32px;
    color: var(--text-muted);
}

.empty-state-icon.gold {
    background: rgba(201, 169, 98, 0.1);
}

.empty-state-icon.gold i {
    color: var(--accent-gold);
}

.empty-state-title {
    font-size: 18px;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 8px;
}

.empty-state-message {
    font-size: 14px;
    color: var(--text-secondary);
    max-width: 320px;
    line-height: 1.6;
    margin-bottom: 20px;
}

.empty-state-action {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 20px;
    background: var(--accent-gold);
    color: var(--bg-primary);
    border: none;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
}

.empty-state-action:hover {
    background: var(--accent-gold-dim);
    transform: translateY(-2px);
}

.empty-state-secondary {
    margin-top: 12px;
}

.empty-state-secondary a {
    color: var(--accent-gold);
    font-size: 13px;
    text-decoration: none;
}

.empty-state-secondary a:hover {
    text-decoration: underline;
}

/* Empty state variants */
.empty-state.compact {
    padding: 32px 16px;
    min-height: 160px;
}

.empty-state.compact .empty-state-icon {
    width: 56px;
    height: 56px;
    margin-bottom: 12px;
}

.empty-state.compact .empty-state-icon i {
    font-size: 24px;
}

.empty-state.compact .empty-state-title {
    font-size: 15px;
}

.empty-state.compact .empty-state-message {
    font-size: 13px;
}

/* === 1.4 Enhanced Toast Notification System === */
/* Inline field validation */
.field-error input,
.field-error textarea,
.field-error select {
    border-color: var(--danger) !important;
    box-shadow: 0 0 0 2px rgba(239, 68, 68, 0.15) !important;
}

.field-error-msg {
    color: var(--danger);
    font-size: 12px;
    margin-top: 4px;
    display: flex;
    align-items: center;
    gap: 4px;
}

.field-error-msg i {
    font-size: 11px;
}

.toast-container {
    position: fixed;
    bottom: 24px;
    right: 24px;
    z-index: 100010;
    display: flex;
    flex-direction: column;
    gap: 12px;
    max-width: 400px;
    pointer-events: none;
}

.toast {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 14px 16px;
    background: linear-gradient(135deg, rgba(20,15,12, 0.85) 0%, rgba(20,15,12, 0.9) 100%);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 12px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3), 0 0 0 1px rgba(255, 255, 255, 0.05);
    pointer-events: auto;
    transform: translateX(120%);
    opacity: 0;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.toast.show {
    transform: translateX(0);
    opacity: 1;
}

.toast.hiding {
    transform: translateX(120%);
    opacity: 0;
}

.toast-icon {
    width: 24px;
    height: 24px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    flex-shrink: 0;
}

.toast.success .toast-icon {
    background: rgba(47, 107, 58, 0.2);
    color: var(--success);
}

.toast.error .toast-icon {
    background: rgba(239, 68, 68, 0.2);
    color: var(--danger);
}

.toast.warning .toast-icon {
    background: rgba(245, 158, 11, 0.2);
    color: var(--warning);
}

.toast.info .toast-icon {
    background: rgba(155, 27, 34, 0.2);
    color: var(--accent);
}

.toast-content {
    flex: 1;
    min-width: 0;
}

.toast-title {
    font-size: 14px;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 2px;
}

.toast-message {
    font-size: 13px;
    color: var(--text-secondary);
    line-height: 1.4;
}

.toast-actions {
    display: flex;
    gap: 8px;
    margin-top: 10px;
}

.toast-action-btn {
    padding: 6px 12px;
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: 6px;
    color: var(--text-primary);
    font-size: 12px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.toast-action-btn:hover {
    background: var(--bg-hover);
}

.toast-action-btn.primary {
    background: var(--accent-gold);
    border-color: transparent;
    color: var(--bg-primary);
}

.toast-action-btn.primary:hover {
    background: var(--accent-gold-dim);
}

.toast-close {
    background: none;
    border: none;
    color: var(--text-muted);
    cursor: pointer;
    padding: 4px;
    font-size: 14px;
    transition: color 0.2s;
    flex-shrink: 0;
}

.toast-close:hover {
    color: var(--text-primary);
}

.toast-progress {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: var(--bg-tertiary);
    border-radius: 0 0 12px 12px;
    overflow: hidden;
}

.toast-progress-bar {
    height: 100%;
    background: var(--accent-gold);
    transition: width linear;
}

.toast.success .toast-progress-bar {
    background: var(--success);
}

.toast.error .toast-progress-bar {
    background: var(--danger);
}

.toast.warning .toast-progress-bar {
    background: var(--warning);
}

.toast.info .toast-progress-bar {
    background: var(--accent);
}

/* === 1.5 Enhanced Skeleton Loading States === */
.skeleton-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 20px;
}

.skeleton-table {
    width: 100%;
}

.skeleton-table-row {
    display: flex;
    gap: 16px;
    padding: 16px 0;
    border-bottom: 1px solid var(--border);
}

.skeleton-table-cell {
    height: 16px;
    border-radius: 4px;
}

.skeleton-table-cell.checkbox { width: 20px; flex-shrink: 0; }
.skeleton-table-cell.name { flex: 2; }
.skeleton-table-cell.email { flex: 2; }
.skeleton-table-cell.status { width: 80px; flex-shrink: 0; }
.skeleton-table-cell.date { width: 100px; flex-shrink: 0; }
.skeleton-table-cell.actions { width: 60px; flex-shrink: 0; }

/* Pulse animation alternative to shimmer */
.skeleton-pulse {
    animation: skeleton-pulse 1.5s ease-in-out infinite;
}

@keyframes skeleton-pulse {
    0%, 100% { opacity: 0.4; }
    50% { opacity: 0.8; }
}

/* ========== PHASE 2: USER EXPERIENCE ========== */

/* === 2.1 Enhanced Command Palette === */
.cmd-result-category {
    padding: 8px 16px;
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    background: var(--bg-tertiary);
    border-top: 1px solid var(--border);
}

.cmd-result-category:first-child {
    border-top: none;
}

.cmd-result-item.member .cmd-result-avatar,
.cmd-result-item.event .cmd-result-avatar {
    display: inline-flex;
}

.cmd-result-avatar {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: var(--accent-gold);
    color: var(--bg-primary);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 11px;
    font-weight: 600;
    margin-right: 10px;
}

.cmd-result-meta {
    font-size: 11px;
    color: var(--text-muted);
    margin-left: auto;
}

/* === 2.2 Action Items Dashboard Widget === */
.action-items-widget {
    background: linear-gradient(135deg, var(--bg-secondary) 0%, rgba(20,15,12, 0.8) 100%);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 20px;
    margin-bottom: 24px;
}

.action-items-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 16px;
}

.action-items-title {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 16px;
    font-weight: 600;
}

.action-items-title i {
    color: var(--accent-gold);
}

.action-items-badge {
    background: rgba(239, 68, 68, 0.2);
    color: var(--danger);
    font-size: 12px;
    font-weight: 600;
    padding: 4px 10px;
    border-radius: 12px;
}

.action-items-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.action-item {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 14px 16px;
    background: var(--bg-tertiary);
    border: 1px solid transparent;
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.2s;
}

.action-item:hover {
    border-color: var(--accent-gold);
    background: rgba(201, 169, 98, 0.05);
}

.action-item-icon {
    width: 40px;
    height: 40px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
    flex-shrink: 0;
}

.action-item-icon.urgent {
    background: rgba(239, 68, 68, 0.15);
    color: var(--danger);
}

.action-item-icon.warning {
    background: rgba(245, 158, 11, 0.15);
    color: var(--warning);
}

.action-item-icon.info {
    background: rgba(155, 27, 34, 0.15);
    color: var(--accent);
}

.action-item-icon.success {
    background: rgba(47, 107, 58, 0.15);
    color: var(--success);
}

.action-item-content {
    flex: 1;
    min-width: 0;
}

.action-item-label {
    font-size: 14px;
    font-weight: 500;
    color: var(--text-primary);
    margin-bottom: 4px;
}

.action-item-meta {
    font-size: 12px;
    color: var(--text-muted);
}

.action-item-deadline {
    font-size: 12px;
    font-weight: 500;
    padding: 4px 10px;
    border-radius: 6px;
    flex-shrink: 0;
}

.action-item-deadline.urgent {
    background: rgba(239, 68, 68, 0.15);
    color: var(--danger);
}

.action-item-deadline.soon {
    background: rgba(245, 158, 11, 0.15);
    color: var(--warning);
}

.action-item-deadline.normal {
    background: var(--bg-secondary);
    color: var(--text-muted);
}

/* === 2.3 Smart Connection Recommendations === */
.connection-recs-widget {
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 20px;
}

.connection-recs-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 16px;
}

.connection-recs-title {
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 16px;
    font-weight: 600;
}

.connection-recs-title i {
    color: var(--accent);
}

.connection-rec-card {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 16px;
    background: var(--bg-tertiary);
    border-radius: 12px;
    margin-bottom: 12px;
}

.connection-rec-card:last-child {
    margin-bottom: 0;
}

.connection-rec-avatar {
    width: 48px;
    height: 48px;
    min-width: 48px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--accent), #9b1b22);
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-weight: 600;
    font-size: 14px;
    flex-shrink: 0;
    position: relative;
}

.connection-match-score {
    position: absolute;
    bottom: -4px;
    right: -4px;
    background: linear-gradient(135deg, var(--success), var(--success));
    color: white;
    font-size: 10px;
    font-weight: 700;
    padding: 2px 5px;
    border-radius: 8px;
    border: 2px solid var(--bg-secondary);
    white-space: nowrap;
}

.connection-rec-actions {
    display: flex;
    gap: 8px;
    flex-shrink: 0;
}

.connection-rec-btn {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
    font-size: 14px;
}

.connection-rec-btn.connect {
    background: linear-gradient(135deg, var(--accent), #9b1b22);
    color: white;
}

.connection-rec-btn.connect:hover {
    transform: scale(1.1);
    box-shadow: 0 4px 12px rgba(155, 27, 34, 0.4);
}

.connection-rec-btn.dismiss {
    background: var(--bg-tertiary);
    color: var(--text-muted);
}

.connection-rec-btn.dismiss:hover {
    background: rgba(239, 68, 68, 0.1);
    color: var(--danger);
}

.connection-rec-info {
    flex: 1;
    min-width: 0;
}

.connection-rec-name {
    font-size: 14px;
    font-weight: 600;
    margin-bottom: 2px;
}

.connection-rec-role {
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 6px;
}

.connection-rec-reason {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 11px;
    color: var(--accent);
    background: rgba(155, 27, 34, 0.1);
    padding: 4px 10px;
    border-radius: 6px;
    width: fit-content;
}

.connection-rec-action {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: var(--accent-gold);
    color: var(--bg-primary);
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
    flex-shrink: 0;
}

.connection-rec-action:hover {
    transform: scale(1.1);
    box-shadow: 0 4px 12px rgba(201, 169, 98, 0.3);
}

/* === 2.4 Calendar Integration === */
.add-to-calendar-dropdown {
    position: relative;
    display: inline-block;
}

.add-to-calendar-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 16px;
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: 8px;
    color: var(--text-primary);
    font-size: 13px;
    cursor: pointer;
    transition: all 0.2s;
}

.add-to-calendar-btn:hover {
    background: var(--bg-hover);
    border-color: var(--accent-gold);
}

.add-to-calendar-menu {
    position: absolute;
    top: calc(100% + 8px);
    right: 0;
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 8px;
    min-width: 200px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
    opacity: 0;
    visibility: hidden;
    transform: translateY(-10px);
    transition: all 0.2s;
    z-index: 1000;
}

.add-to-calendar-dropdown.open .add-to-calendar-menu {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
}

.calendar-option {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 14px;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s;
    color: var(--text-primary);
    font-size: 13px;
}

.calendar-option:hover {
    background: var(--bg-tertiary);
}

.calendar-option i {
    width: 20px;
    text-align: center;
    font-size: 16px;
}

.calendar-option .fa-google { color: #4285f4; }
.calendar-option .fa-apple { color: #fff; }
.calendar-option .fa-microsoft { color: #00a4ef; }
.calendar-option .fa-calendar-alt { color: var(--accent-gold); }

/* === 2.5 Mobile Event Day Mode === */
@media (max-width: 768px) {
    .day-mode .session-card {
        min-height: 48px;
        padding: 16px;
    }

    .day-mode .session-card button,
    .day-mode .session-card a {
        min-height: 48px;
        min-width: 48px;
    }

    .day-mode .tab-btn {
        min-height: 48px;
        padding: 14px 20px;
    }
}

/* Swipe hint indicator */
.swipe-hint {
    display: none;
    position: fixed;
    bottom: 100px;
    left: 50%;
    transform: translateX(-50%);
    background: rgba(0, 0, 0, 0.8);
    color: white;
    padding: 10px 20px;
    border-radius: 14px;
    font-size: 13px;
    z-index: 9999;
}

@media (max-width: 768px) {
    .swipe-hint.active {
        display: flex;
        align-items: center;
        gap: 10px;
    }
}

/* Pull to refresh indicator */
.ptr-indicator {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: 60px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--bg-secondary);
    transform: translateY(-100%);
    transition: transform 0.3s;
    z-index: 9998;
}

.ptr-indicator.pulling {
    transform: translateY(0);
}

.ptr-indicator i {
    font-size: 20px;
    color: var(--accent-gold);
    animation: spin 1s linear infinite;
}

/* ========== PHASE 3: ADMIN EFFICIENCY ========== */

/* === 3.1 Advanced Filter Builder === */
.filter-builder {
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 20px;
    margin-bottom: 20px;
}

.filter-builder-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 16px;
}

.filter-builder-title {
    font-size: 14px;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 8px;
}

.filter-builder-title i {
    color: var(--accent-gold);
}

.filter-builder-actions {
    display: flex;
    gap: 8px;
}

.filter-condition {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px;
    background: var(--bg-tertiary);
    border-radius: 8px;
    margin-bottom: 8px;
}

.filter-condition select,
.filter-condition input {
    padding: 8px 12px;
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 6px;
    color: var(--text-primary);
    font-size: 13px;
}

.filter-condition select {
    min-width: 140px;
}

.filter-condition input {
    flex: 1;
    min-width: 120px;
}

.filter-condition-remove {
    width: 36px;
    height: 36px;
    border-radius: 8px;
    background: rgba(239, 68, 68, 0.1);
    color: var(--danger);
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
}

.filter-condition-remove:hover {
    background: rgba(239, 68, 68, 0.2);
}

.filter-logic-toggle {
    display: flex;
    gap: 4px;
    margin: 8px 0 8px 12px;
}

.filter-logic-btn {
    padding: 4px 12px;
    font-size: 11px;
    font-weight: 600;
    border-radius: 4px;
    border: none;
    cursor: pointer;
    background: var(--bg-tertiary);
    color: var(--text-muted);
    transition: all 0.2s;
}

.filter-logic-btn.active {
    background: var(--accent-gold);
    color: var(--bg-primary);
}

.filter-add-btn {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    background: transparent;
    border: 1px dashed var(--border);
    border-radius: 6px;
    color: var(--text-muted);
    font-size: 13px;
    cursor: pointer;
    transition: all 0.2s;
    margin-top: 12px;
}

.filter-add-btn:hover {
    border-color: var(--accent-gold);
    color: var(--accent-gold);
}

/* Saved filter chips */
.saved-filters {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-bottom: 16px;
}

.saved-filter-chip {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: 14px;
    font-size: 12px;
    cursor: pointer;
    transition: all 0.2s;
}

.saved-filter-chip:hover {
    border-color: var(--accent-gold);
}

.saved-filter-chip.active {
    background: rgba(201, 169, 98, 0.15);
    border-color: var(--accent-gold);
    color: var(--accent-gold);
}

.saved-filter-chip i {
    font-size: 10px;
}

/* === 3.2 Registration Analytics Dashboard === */
.analytics-dashboard {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 20px;
    margin-bottom: 24px;
}

.analytics-card {
    background: var(--bg-secondary);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 20px;
}

.analytics-card-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 16px;
}

.analytics-card-title {
    font-size: 14px;
    font-weight: 600;
    color: var(--text-secondary);
}

.analytics-card-period {
    font-size: 11px;
    color: var(--text-muted);
    padding: 4px 8px;
    background: var(--bg-tertiary);
    border-radius: 4px;
}

.analytics-chart {
    height: 200px;
    display: flex;
    align-items: flex-end;
    gap: 4px;
}

.analytics-bar {
    flex: 1;
    background: linear-gradient(180deg, var(--accent-gold), rgba(201, 169, 98, 0.3));
    border-radius: 4px 4px 0 0;
    min-height: 4px;
    transition: all 0.3s;
    position: relative;
}

.analytics-bar:hover {
    background: linear-gradient(180deg, var(--accent-gold), var(--accent-gold));
}

.analytics-bar::after {
    content: attr(data-value);
    position: absolute;
    bottom: calc(100% + 4px);
    left: 50%;
    transform: translateX(-50%);
    font-size: 10px;
    color: var(--text-muted);
    opacity: 0;
    transition: opacity 0.2s;
}

.analytics-bar:hover::after {
    opacity: 1;
}

.analytics-labels {
    display: flex;
    justify-content: space-between;
    margin-top: 8px;
    font-size: 10px;
    color: var(--text-muted);
}

.analytics-stat-large {
    font-size: 36px;
    font-weight: 700;
    color: var(--text-primary);
    line-height: 1;
}

.analytics-stat-change {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 13px;
    font-weight: 600;
    margin-left: 12px;
}

.analytics-stat-change.positive {
    color: var(--success);
}

.analytics-stat-change.negative {
    color: var(--danger);
}

/* === 3.3 Task Assignment System === */
.task-assignment-modal {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.7);
    backdrop-filter: blur(4px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 100004;
    opacity: 0;
    visibility: hidden;
    transition: all 0.2s;
}

.task-assignment-modal.active {
    opacity: 1;
    visibility: visible;
}

.task-assignment-content {
    background: linear-gradient(135deg, var(--emph-bg-2) 0%, var(--emph-bg) 100%);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 24px;
    width: 100%;
    max-width: 480px;
    transform: scale(0.9);
    transition: transform 0.2s;
}

.task-assignment-modal.active .task-assignment-content {
    transform: scale(1);
}

.task-assignment-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 20px;
}

.task-assignment-header h3 {
    font-size: 18px;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 10px;
}

.task-assignment-header h3 i {
    color: var(--accent-gold);
}

.task-assignment-field {
    margin-bottom: 16px;
}

.task-assignment-label {
    font-size: 13px;
    font-weight: 500;
    color: var(--text-secondary);
    margin-bottom: 8px;
    display: block;
}

.task-assignee-select {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.task-assignee-option {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 14px;
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s;
}

.task-assignee-option:hover {
    border-color: var(--accent-gold);
}

.task-assignee-option.selected {
    background: rgba(201, 169, 98, 0.15);
    border-color: var(--accent-gold);
}

.task-assignee-avatar {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: var(--accent-gold);
    color: var(--bg-primary);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 11px;
    font-weight: 600;
}

.task-assignee-name {
    font-size: 13px;
    font-weight: 500;
}

.task-due-date-input {
    width: 100%;
    padding: 12px 14px;
    background: var(--bg-tertiary);
    border: 1px solid var(--border);
    border-radius: 8px;
    color: var(--text-primary);
    font-size: 14px;
}

.task-assignment-actions {
    display: flex;
    gap: 12px;
    margin-top: 24px;
}

/* Task status badges */
.task-status-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    border-radius: 6px;
    font-size: 11px;
    font-weight: 600;
}

.task-status-badge.assigned {
    background: rgba(155, 27, 34, 0.15);
    color: var(--accent);
}

.task-status-badge.in-progress {
    background: rgba(245, 158, 11, 0.15);
    color: var(--warning);
}

.task-status-badge.done {
    background: rgba(47, 107, 58, 0.15);
    color: var(--success);
}

/* ========== DESIGN SYSTEM STANDARDIZATION ========== */

/* Z-Index Tier System */
:root {
    --z-dropdown: 100;
    --z-sticky: 200;
    --z-fixed: 300;
    --z-modal-backdrop: 1000;
    --z-modal: 1001;
    --z-popover: 2000;
    --z-tooltip: 3000;
    --z-floating-nav: 5000;
    --z-toast: 9000;
    --z-confirmation: 100005;
}

/* Border Radius Standardization */
:root {
    --radius-sm: 6px;
    --radius-md: 8px;
    --radius-lg: 12px;
    --radius-xl: 16px;
    --radius-2xl: 24px;
    --radius-full: 50%;
}

/* ========== PHASE 4: PUSH NOTIFICATIONS ========== */

/* In-App Notification Center */
.notification-bell {
    position: relative;
    cursor: pointer;
}

.notification-bell-badge {
    position: absolute;
    top: -4px;
    right: -4px;
    min-width: 18px;
    height: 18px;
    padding: 0 5px;
    background: var(--danger);
    color: white;
    font-size: 10px;
    font-weight: 700;
    border-radius: 9px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.notification-panel {
    position: fixed;
    top: 0;
    right: 0;
    width: 400px;
    max-width: 100vw;
    height: 100vh;
    background: var(--bg-secondary);
    color: var(--text-primary);
    border-left: 1px solid var(--border);
    z-index: 10002;
    display: flex;
    flex-direction: column;
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    transform: translateX(100%);
    box-shadow: -10px 0 40px rgba(0, 0, 0, 0.3);
}

.notification-panel.active {
    transform: translateX(0);
}

.notification-panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 20px;
    border-bottom: 1px solid var(--border);
}

.notification-panel-title {
    font-size: 18px;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 10px;
}

.notification-panel-title i {
    color: var(--accent-gold);
}

.notification-panel-actions {
    display: flex;
    gap: 8px;
}

.notification-panel-btn {
    padding: 8px 12px;
    background: transparent;
    border: none;
    color: var(--text-muted);
    font-size: 12px;
    cursor: pointer;
    border-radius: 6px;
    transition: all 0.2s;
}

.notification-panel-btn:hover {
    background: var(--bg-tertiary);
    color: var(--text-primary);
}

.notification-panel-close {
    width: 40px;
    height: 40px;
    border-radius: 8px;
    background: transparent;
    border: none;
    color: var(--text-muted);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
}

.notification-panel-close:hover {
    background: var(--bg-tertiary);
    color: var(--text-primary);
}

.notification-panel-body {
    flex: 1;
    overflow-y: auto;
}

.notification-group {
    padding: 12px 20px 8px;
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-muted);
    background: var(--bg-tertiary);
    position: sticky;
    top: 0;
    z-index: 1;
}

.notification-item {
    display: flex;
    gap: 14px;
    padding: 16px 20px;
    border-bottom: 1px solid var(--border);
    cursor: pointer;
    transition: background 0.2s;
}

.notification-item:hover {
    background: rgba(201, 169, 98, 0.05);
}

.notification-item.unread {
    background: rgba(155, 27, 34, 0.05);
}

.notification-item.unread::before {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 3px;
    background: var(--accent);
}

.notification-icon {
    width: 40px;
    height: 40px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
    flex-shrink: 0;
}

.notification-icon.event {
    background: rgba(155, 27, 34, 0.15);
    color: var(--accent);
}

.notification-icon.payment {
