}

.push-permission-banner.active {
    display: flex;
    align-items: center;
    gap: 16px;
}

.push-permission-icon {
    width: 48px;
    height: 48px;
    border-radius: 12px;
    background: rgba(155, 27, 34, 0.15);
    color: var(--accent);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    flex-shrink: 0;
}

.push-permission-content {
    flex: 1;
}

.push-permission-content h4 {
    font-size: 14px;
    font-weight: 600;
    margin-bottom: 4px;
    color: var(--paper-2);
}

.push-permission-content p {
    font-size: 13px;
    color: var(--muted);
}

.push-permission-actions {
    display: flex;
    gap: 8px;
    flex-shrink: 0;
}

.push-permission-btn {
    padding: 10px 16px;
    border-radius: 8px;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
