  .up-rail{display:flex;flex-direction:column;position:fixed;top:0;left:0;bottom:0;width:236px;z-index:1250;
    background:var(--surface);border-right:1px solid var(--line);padding:20px 14px 16px;overflow-y:auto;overflow-x:hidden;}
  /* Left rail retired — replaced by the premium sticky top bar (#upTopbar). */
  #userPortal .up-main{margin-left:0;}
  .up-topbar{display:flex;}
  #upBottomNav{display:none !important;}
  /* the top bar carries brand + bell + account — drop the duplicate in-section dashboard header chrome */
  #userPortal .hub-header-left{display:none;}
  #userPortal .hub-header-right{display:none;}
}
