.splash-entry-divider{background:var(--crimson) !important;opacity:.75;}
.splash-btn-primary{background:var(--crimson) !important;color:#fff !important;border:none !important;box-shadow:0 8px 24px rgba(155,27,34,.35) !important;}
.splash-btn-secondary{background:transparent !important;color:#f3efe9 !important;border:1px solid rgba(243,239,233,.3) !important;}
.splash-entry-footer{color:rgba(243,239,233,.72) !important;}
.splash-entry-orb-1{background:radial-gradient(circle, rgba(194,72,78,.22), transparent 70%) !important;}
.splash-entry-orb-2{background:radial-gradient(circle, rgba(210,177,106,.15), transparent 70%) !important;}
.splash-entry-orb-3{background:radial-gradient(circle, rgba(194,72,78,.12), transparent 70%) !important;}
/* ===== Login / auth modal — brand surface + crimson CTA + crimson focus ===== */
.auth-modal{background:var(--surface) !important;color:var(--ink) !important;border:1px solid var(--line) !important;border-radius:var(--radius-lg) !important;box-shadow:var(--shadow-lg) !important;}
.auth-modal p{color:var(--muted) !important;}
.auth-form-label{color:var(--ink-soft) !important;}
.auth-form-input{background:var(--paper-2) !important;color:var(--ink) !important;border:1px solid var(--line-strong) !important;border-radius:var(--radius) !important;}
.auth-form-input:focus{border-color:var(--crimson) !important;box-shadow:0 0 0 3px rgba(155,27,34,.15) !important;outline:none !important;}
.auth-btn:not([style*="background"]){background:var(--crimson) !important;color:#fff !important;border:none !important;}
/* ============================================================
   PREMIUM POLISH — close the gap to the marketing website
   (editorial display type, card+color discipline, breathing room)
   ============================================================ */
/* 1. Editorial display scale: large Fraunces greeting + real hierarchy */
.hub-welcome-greeting{font-family:var(--serif) !important;font-size:30px !important;font-weight:600 !important;letter-spacing:-.02em !important;line-height:1.08 !important;color:var(--ink) !important;}
@media (min-width:768px){.hub-welcome-greeting{font-size:42px !important;}}
.up-card-title,.card-title,.section-title,.up-section-title,.px-card-title{font-family:var(--serif) !important;font-size:19px !important;font-weight:600 !important;letter-spacing:-.01em !important;}
/* 2. Section labels become quiet uppercase eyebrows (not big filler headings) */
.hub-dashboard-header h2,.hub-section-label{font-family:var(--sans) !important;font-size:11px !important;font-weight:700 !important;letter-spacing:.13em !important;text-transform:uppercase !important;color:var(--muted) !important;margin:0 !important;}
/* 3. Card discipline: warm surface, hairline border, one soft shadow, generous radius */
.up-card,.hub-card,.mymedx-container .up-card{background:var(--surface) !important;border:1px solid var(--line) !important;border-radius:14px !important;box-shadow:var(--shadow-sm) !important;}
/* 4. Tone the rainbow: program/quick icon tiles → warm neutral with crimson glyph */
.up-project-icon,.hub-quick-icon,.feature-icon,.project-icon-wrap{background:var(--paper-2) !important;color:var(--crimson) !important;}
.up-project-icon i,.hub-quick-icon i{color:var(--crimson) !important;}
/* 5. Breathing room on mobile */
@media (max-width:768px){
  .hub-welcome-section{padding-top:22px !important;padding-bottom:6px !important;}
  .hub-dashboard-header{margin-top:26px !important;}
}
/* 6. Quieter, premium status pills (less SaaS-badge) */
.status-pill,.up-status,.px-badge,.hub-badge{font-weight:600 !important;letter-spacing:.02em !important;border-radius:999px !important;}
/* 7. Featured carousel → PHOTOGRAPHIC heroes (website signature): real event photos under a
      dark-ink→crimson overlay so the white Fraunces headline + crimson CTA stay legible. */
.featured-slide-bg{background-size:cover !important;background-position:center !important;}
.featured-slide-bg::before{background:transparent !important;}
.featured-slide-bg.plexus{background:linear-gradient(135deg, rgba(20,17,15,.86) 0%, rgba(20,17,15,.60) 55%, rgba(18,15,13,.82) 100%), url('/assets/photos/plexus_25_gala_grupna.jpg') center/cover !important;}
.featured-slide-bg.gala{background:linear-gradient(135deg, rgba(20,17,15,.86) 0%, rgba(20,17,15,.60) 55%, rgba(18,15,13,.82) 100%), url('/assets/photos/plexus_25_gala.jpg') center/cover !important;}
.featured-slide-bg.accelerator{background:linear-gradient(135deg, rgba(20,17,15,.86) 0%, rgba(20,17,15,.60) 55%, rgba(18,15,13,.82) 100%), url('/assets/photos/plexus_25_acc_panel.jpg') center/cover !important;}
.featured-slide-bg.forum{background:linear-gradient(135deg, rgba(20,17,15,.88) 0%, rgba(20,17,15,.64) 55%, rgba(18,15,13,.82) 100%), url('/assets/photos/plexus_2022.jpg') center/cover !important;}
.featured-slide-bg.bridges{background:linear-gradient(135deg, rgba(20,17,15,.86) 0%, rgba(20,17,15,.60) 55%, rgba(18,15,13,.82) 100%), url('/assets/photos/plexus_2022.jpg') center/cover !important;}
/* 8. Quieter quick-check-in card (was a hard navy gradient) → warm-ink emphasis */
.hub-checkin-card{background:linear-gradient(135deg, var(--emph-bg), var(--emph-bg-2)) !important;border:1px solid var(--emph-line) !important;}
/* Demo Login: keep it (handy for review) but make it a quiet ghost button, not cheap green */
button[onclick*="demoLogin"]{background:transparent !important;color:var(--muted) !important;border:1px solid var(--line-strong) !important;font-weight:500 !important;box-shadow:none !important;}
/* ===== Editorial calm: cut redundancy + add breathing room (dashboard was 3434px, events repeated 5x) ===== */
#hubWelcomeSubtitle{display:none !important;}                 /* redundant cheap promo line under greeting */
#dashboardSplitSection{display:none !important;}             /* busy duplicate 'My Events' (payment pills); 'Your Events' list remains */
#upNextEvent{margin-top:18px !important;}
#featuredCarousel,.hub-checkin-card,.news-programs-row,#dashboardBento{margin-top:28px !important;}
.hub-programs-trio,.my-network-card-compact{margin-bottom:28px !important;}
#userPortal .up-section,.hub-container{padding-left:18px !important;padding-right:18px !important;}
/* Hide fabricated notification/count badges (hardcoded 2/3/5) — they read as cheap, not real.
   Real, gated badges (#hubBellBadge / #adminMsgBadge, default display:none) are untouched. */
.up-project-badge,.hub-grid-btn-badge,#upFloatNotifBadge,#msgBadge,#hubBadgeNotif{display:none !important;}
/* Browser autofill must not tint inputs blue — keep paper surface + ink text */
input:-webkit-autofill,input:-webkit-autofill:hover,input:-webkit-autofill:focus,textarea:-webkit-autofill,select:-webkit-autofill{-webkit-box-shadow:0 0 0 1000px var(--paper-2) inset !important;-webkit-text-fill-color:var(--ink) !important;caret-color:var(--ink) !important;}
/* ===== Panel pass 2: unify accents to crimson, drop in-app marketing filler ===== */
.featured-cta,.hub-cta-primary,.up-btn-gold{background:var(--crimson) !important;color:#fff !important;border:none !important;}
.hub-footer-minimal{display:none !important;}
.my-event-icon,.post-event-icon,.hub-event-icon,.preview-event-icon{background:var(--paper-2) !important;color:var(--crimson) !important;}
.my-event-icon i,.post-event-icon i,.hub-event-icon i,.preview-event-icon i{color:var(--crimson) !important;}
/* a11y: ensure modal close buttons meet the 44px touch target */
.auth-modal-close,.up-generic-modal-close,.up-help-close{min-width:44px !important;min-height:44px !important;display:inline-flex !important;align-items:center !important;justify-content:center !important;}
/* ===== Editorial dashboard hero (greeting + next event, website-style photographic) ===== */
#upNextEvent{margin:0 0 22px;}
.up-hero{position:relative;overflow:hidden;border-radius:18px;min-height:min(352px,48vh);display:flex;flex-direction:column;justify-content:flex-end;padding:26px 24px;color:#f3efe9;box-shadow:var(--shadow-md);background:linear-gradient(180deg, rgba(18,15,13,.28) 0%, rgba(18,15,13,.55) 48%, rgba(18,15,13,.92) 100%), url('/assets/photos/plexus_25_gala_grupna.jpg') center/cover;background-color:#14110f;}
.up-hero-greeting{font-family:var(--serif);font-size:30px;font-weight:600;letter-spacing:-.02em;line-height:1.05;margin-bottom:16px;}
.up-hero-eyebrow{font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:rgba(243,239,233,.78);display:flex;align-items:center;gap:10px;flex-wrap:wrap;}
.up-hero-status{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:#fff;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.22);padding:3px 9px;border-radius:999px;}
.up-hero-event{font-family:var(--serif);font-size:24px;font-weight:700;line-height:1.12;margin:9px 0 5px;}
.up-hero-meta{font-size:13px;color:rgba(243,239,233,.88);}
.up-hero-actions{display:flex;gap:10px;margin-top:18px;flex-wrap:wrap;}
.up-hero-btn{border-radius:10px;padding:11px 18px;font-weight:700;font-size:13px;cursor:pointer;border:none;font-family:var(--sans);}
.up-hero-btn.primary{background:var(--crimson);color:#fff;}
.up-hero-btn.primary:hover{background:var(--crimson-deep);}
.up-hero-btn.ghost{background:rgba(255,255,255,.12);color:#fff;border:1px solid rgba(255,255,255,.28);font-weight:600;}
@media(min-width:768px){.up-hero{min-height:min(412px,50vh);padding:min(40px,4vh) 38px;} .up-hero-greeting{font-size:44px;} .up-hero-event{font-size:30px;}}
/* greeting now lives in the hero — hide the old plain greeting block */
.hub-welcome-section{display:none !important;}
/* ============================================================
   POLISH PASS 3 — final-audit fixes (premium + UX)
   ============================================================ */
/* (1) Section heroes were pale-slate in the DEFAULT light theme (a [data-theme=light] override
   re-applied the abandoned style and won). Re-assert warm-ink photographic + white text in light,
   using LOCAL photos (also drops the Squarespace-CDN dependency for these). */
[data-theme="light"] .px-hero{background:linear-gradient(135deg,rgba(18,15,13,.86) 0%,rgba(18,15,13,.70) 55%,rgba(18,15,13,.58) 100%),url('/assets/photos/plexus_2022.jpg') center/cover !important;}
[data-theme="light"] .gala-hero{background:linear-gradient(135deg,rgba(18,15,13,.86) 0%,rgba(18,15,13,.66) 55%,rgba(18,15,13,.62) 100%),url('/assets/photos/plexus_25_gala.jpg') center/cover !important;}
[data-theme="light"] .ax-hero{background:linear-gradient(135deg,rgba(18,15,13,.86) 0%,rgba(18,15,13,.70) 55%,rgba(18,15,13,.58) 100%),url('/assets/photos/plexus_25_acc_panel.jpg') center/cover !important;}
[data-theme="light"] .fm-hero{background:linear-gradient(135deg,rgba(18,15,13,.86) 0%,rgba(18,15,13,.70) 55%,rgba(18,15,13,.58) 100%),url('/assets/photos/plexus_25_gala_grupna.jpg') center/cover !important;}
[data-theme="light"] .px-hero,[data-theme="light"] .gala-hero,[data-theme="light"] .ax-hero,[data-theme="light"] .fm-hero,
[data-theme="light"] .px-hero h1,[data-theme="light"] .px-hero p,[data-theme="light"] .gala-hero h1,[data-theme="light"] .gala-hero p,
[data-theme="light"] .ax-hero h1,[data-theme="light"] .ax-hero p,[data-theme="light"] .fm-hero h1,[data-theme="light"] .fm-hero p{color:#f3efe9 !important;}
[data-theme="light"] .px-hero .px-hero-badge,[data-theme="light"] .gala-hero .gala-hero-badge,[data-theme="light"] .ax-hero .ax-hero-badge,[data-theme="light"] .fm-hero .fm-hero-badge{color:#fff !important;}
/* (2) Primary CTAs were gold across the portal (biggest legacy tell) -> crimson.
   .up-hero-btn.primary is crimson too (single crimson primary per view). Color-only; no payment logic touched. */
.btn-primary,.connection-btn.primary,.px-hero-btn-primary,.gala-hero-btn-primary,.ax-hero-btn-primary,.fm-hero-btn-primary,.fm-directory-btn-primary,.btn-landing-primary,.wt-btn.primary,.af-btn-primary{background:var(--crimson) !important;background-image:none !important;color:#fff !important;border-color:var(--crimson) !important;}
.btn-primary:hover,.connection-btn.primary:hover,.af-btn-primary:hover,.px-hero-btn-primary:hover,.gala-hero-btn-primary:hover{background:var(--crimson-deep) !important;}
/* (3) Active tab was green -> crimson */
.tab-btn.active{background:var(--crimson) !important;color:#fff !important;}
/* (4) Content section headings missing Fraunces */
.bb-section-title,.fm-section-title,.fm-network-section-title,.bb-event-section-title,.for-you-section-title,.profile-section-title,.px-package-section-title,.landing-section-title{font-family:var(--serif) !important;letter-spacing:-.01em;}
/* (5) UX: the 5-slide marketing carousel duplicates the editorial next-event hero + quick menus -> retire it */
#featuredCarousel{display:none !important;}
/* ============================================================
   POLISH PASS 4 — premium parity (review 2026-07-01)
   ============================================================ */
/* (item 12) Buttons/inputs inherit the brand sans instead of the OS default (was Arial) */
button,input,select,textarea{font-family:var(--sans);}
/* (item 6) Connection-grid Message buttons -> quiet ghost. Crimson stays reserved for the
   featured CTA + real actions (Accept/Connect/Confirm), which keep the crimson primary above. */
.connection-btn.primary[onclick*="messageConnection"]{background:var(--surface) !important;background-image:none !important;color:var(--ink) !important;border:1px solid var(--line-strong) !important;}
.connection-btn.primary[onclick*="messageConnection"] i{color:var(--crimson) !important;}
.connection-btn.primary[onclick*="messageConnection"]:hover{background:var(--paper-2) !important;border-color:var(--crimson) !important;}
/* (item 11) Novelty motion OFF — premium is stillness. Keep functional transitions only. */
.dashboard-particles{display:none !important;}
.dashboard-widget h3 i:hover,.quiz-widget-title i:hover,.my-events-title i:hover,.pending-items-title i:hover{animation:none !important;}
.status-bar-crown,.up-float-btn .fa-crown,.rewards-crown{animation:none !important;}
#upWelcomeHeader{animation:none !important;}
.floating-help-btn{animation:none !important;}
/* (item 24) One global reduced-motion sweep: kill all animations + heavy transitions */
@media (prefers-reduced-motion: reduce){
  *,*::before,*::after{animation-duration:.001ms !important;animation-iteration-count:1 !important;transition-duration:.001ms !important;scroll-behavior:auto !important;}
}
/* ============================================================
   STAGE 4 — member polish (items 19 + 20)
   ============================================================ */
/* (item 20) One tab component: gold-outline pill active-state so crimson stays
   reserved for CTAs. px/gala/ax tabs already use the gold outline; bring the
   Network segmented control and the generic .tab-btn into the same language. */
.network-tab.active{background:var(--surface) !important;color:#a8842f !important;font-weight:600 !important;box-shadow:inset 0 0 0 1px var(--gold), 0 1px 3px rgba(20,15,12,.08) !important;}
.network-tab.active .network-tab-badge{background:var(--gold) !important;color:var(--ink) !important;}
.tab-btn.active{background:var(--paper-2) !important;color:#a8842f !important;box-shadow:inset 0 0 0 1px var(--gold) !important;}
